/// `Lint/IncompatibleIoSelectWithFiberScheduler`。
///
/// 期待値は本家 1.89.0 を `--only Lint/IncompatibleIoSelectWithFiberScheduler` で走らせた
/// 実出力から取った (検出 8 件・`-A` の結果ともバイト一致を確認済み)。
mod lint_incompatible_io_select_with_fiber_scheduler {
    use super::*;

    const COP: &str = "Lint/IncompatibleIoSelectWithFiberScheduler";

    #[test]
    fn one_stream_in_one_direction_becomes_a_wait() {
        expect_offense(
            COP,
            r#"
            IO.select([io], nil)
            ^^^^^^^^^^^^^^^^^^^^ Use `io.wait_readable` instead of `IO.select([io], nil)`.
            "#,
        );
        expect_correction(
            COP,
            "IO.select([io], nil)\nIO.select([io])\nIO.select(nil, [io])\nIO.select([io], [])\n\
             IO.select([io], nil, nil, 1)\n::IO.select([io], nil)\n",
            "io.wait_readable\nio.wait_readable\nio.wait_writable\nio.wait_readable\n\
             io.wait_readable(1)\nio.wait_readable\n",
        );
    }

    /// 値を受け取る形は置き換えると意味が変わるので、報告だけして補正しない。
    #[test]
    fn an_assigned_call_is_reported_but_not_corrected() {
        CopCase::annotated(
            COP,
            r#"
            x = IO.select([io], nil)
                ^^^^^^^^^^^^^^^^^^^^ Use `io.wait_readable` instead of `IO.select([io], nil)`.
            "#,
        )
        .correctable(false)
        .run();
    }

    #[test]
    fn what_the_cop_leaves_alone() {
        for source in [
            "IO.select([io], nil, [x])\n",
            "IO.select([a, b], nil)\n",
            "IO.select([*a], nil)\n",
            "IO.select([io], [io2])\n",
            "Foo::IO.select([io], nil)\n",
            "IO.select\n",
        ] {
            expect_no_offenses(COP, source);
        }
    }
}

/// `Lint/AmbiguousOperatorPrecedence`。
///
/// 期待値は本家 1.89.0 を `--only Lint/AmbiguousOperatorPrecedence` で走らせた実出力から
/// 取った (検出 8 件・`-A` の結果ともバイト一致を確認済み)。
mod lint_ambiguous_operator_precedence {
    use super::*;

    const COP: &str = "Lint/AmbiguousOperatorPrecedence";

    #[test]
    fn the_tighter_half_gets_parentheses() {
        expect_offense(
            COP,
            r#"
            a = 1 + 2 * 3
                    ^^^^^ Wrap expressions with varying precedence with parentheses to avoid ambiguity.
            "#,
        );
        expect_correction(
            COP,
            "a = 1 + 2 * 3\nb = 1 * 2 + 3\nc = 1 ** 2 * 3\ne = x && y || z\ng = 1 | 2 & 3\n\
             h = 1 << 2 + 3\nl = x || y && z\n",
            "a = 1 + (2 * 3)\nb = (1 * 2) + 3\nc = (1 ** 2) * 3\ne = (x && y) || z\n\
             g = 1 | (2 & 3)\nh = 1 << (2 + 3)\nl = x || (y && z)\n",
        );
        // `and` / `or` は `on_and` 側なので綴りを問わない。
        expect_correction(COP, "f = x and y or z\n", "(f = x and y) or z\n");
    }

    /// 本家は `and` / `or` の優先順位を表から引けないので、算術演算の親がキーワード形の
    /// ときは報告しない。同じ優先順位どうしと、括弧で括られたものも対象外。
    #[test]
    fn what_the_cop_leaves_alone() {
        for source in [
            "a = 1 + 2 and 3\n",
            "d = (1 + 2) * 3\n",
            "k = 1 + 2 + 3\n",
            "i = -a * b\n",
            "j = a.+(b) * c\n",
            "d = x and y\n",
        ] {
            expect_no_offenses(COP, source);
        }
    }
}

/// `Lint/UnreachablePatternBranch`。
///
/// 期待値は本家 1.89.0 を `--only Lint/UnreachablePatternBranch` で走らせた実出力から取った。
mod lint_unreachable_pattern_branch {
    use super::*;

    const COP: &str = "Lint/UnreachablePatternBranch";

    /// 何でも束縛するパターンより後ろの枝と `else` は届かない。`else` のレンジは
    /// キーワードだけ。
    #[test]
    fn everything_after_a_catch_all_is_reported() {
        CopCase::annotated(
            COP,
            r#"
            case x
            in Integer
            in y
            in 1
            ^^^^ Unreachable `in` pattern branch detected.
            end
            "#,
        )
        .target_ruby("3.0")
        .run();
        CopCase::annotated(
            COP,
            r#"
            case x
            in y
            else
            ^^^^ Unreachable `else` branch detected.
            end
            "#,
        )
        .target_ruby("3.0")
        .run();
        // 括弧付きも `match_alt` の片側も catch-all。
        CopCase::new(COP, "case x\nin (y)\nin 1\nend\n", Vec::new())
            .target_ruby("3.0")
            .without_offense_check()
            .inspect();
    }

    /// ガード付き、`match_as` の左が定数、選言のどちらもリテラルなら catch-all ではない。
    #[test]
    fn what_the_cop_leaves_alone() {
        for source in [
            "case x\nin y if z\nin 1\nend\n",
            "case x\nin Integer => n\nin 1\nend\n",
            "case x\nin Integer | String\nin 1\nend\n",
        ] {
            CopCase::new(COP, source, Vec::new())
                .target_ruby("3.0")
                .run();
        }
    }
}

/// `Lint/UselessDefaultValueArgument`。
///
/// 期待値は本家 1.89.0 を `--only Lint/UselessDefaultValueArgument` で走らせた実出力から
/// 取った (検出 6 件・`-A` の結果ともバイト一致を確認済み)。
mod lint_useless_default_value_argument {
    use super::*;

    const COP: &str = "Lint/UselessDefaultValueArgument";

    #[test]
    fn the_default_and_the_comma_before_it_are_removed() {
        expect_offense(
            COP,
            r#"
            h.fetch(:k, 0) { 1 }
                        ^ Block supersedes default value argument.
            "#,
        );
        expect_correction(
            COP,
            "h.fetch(:k, 0) { 1 }\nh.fetch(:k, 0) do 1 end\nArray.new(3, 0) { 1 }\n\
             Foo::Array.new(3, 0) { 1 }\nh.fetch(:k, {a: 1}) { 1 }\nh&.fetch(:k, 0) { 1 }\n",
            "h.fetch(:k) { 1 }\nh.fetch(:k) do 1 end\nArray.new(3) { 1 }\n\
             Foo::Array.new(3) { 1 }\nh.fetch(:k) { 1 }\nh&.fetch(:k) { 1 }\n",
        );
    }

    /// レシーバ無し・引数 1 個・波括弧なしハッシュ・ブロック無しは対象外。
    #[test]
    fn what_the_cop_leaves_alone() {
        for source in [
            "h.fetch(:k) { 1 }\n",
            "h.fetch(:k, 0)\n",
            "fetch(:k, 0) { 1 }\n",
            "h.fetch(:k, a: 1) { 1 }\n",
            "Array.new(3) { 1 }\n",
            "Array.new(3, 0)\n",
        ] {
            expect_no_offenses(COP, source);
        }
    }
}

/// `Lint/ItWithoutArgumentsInBlock`。
///
/// 期待値は本家 1.89.0 を `--only Lint/ItWithoutArgumentsInBlock` で走らせた実出力から
/// 取った (検出 3 件を確認済み)。
mod lint_it_without_arguments_in_block {
    use super::*;

    const COP: &str = "Lint/ItWithoutArgumentsInBlock";

    #[test]
    fn a_bare_it_inside_a_block_without_parameters_is_reported() {
        expect_offense(
            COP,
            r#"
            [1].each { it }
                       ^^ `it` calls without arguments will refer to the first block param in Ruby 3.4; use `it()` or `self.it`.
            "#,
        );
        for source in [
            "[1].each do it end\n",
            "[1].each { [2].each { it } }\n",
            "proc { it }\n",
            "[1].map { it.to_s }\n",
        ] {
            let report = CopCase::new(COP, source, Vec::new())
                .without_offense_check()
                .inspect();
            assert_eq!(report.offenses.len(), 1, "{source:?}");
        }
    }

    /// 引数・括弧・レシーバ・自前のブロックが付けば `it` は曖昧ではない。パラメータを
    /// 持つブロックも対象外。3.4 以降は cop 自体が動かない。
    #[test]
    fn what_the_cop_leaves_alone() {
        for source in [
            "[1].each { it(1) }\n",
            "[1].each { it() }\n",
            "[1].each { |x| it }\n",
            "[1].each { self.it }\n",
            "[1].each { it { } }\n",
            "[1].each { |  | it }\n",
            "it\n",
            "def m; it; end\n",
            "it = 1\n[1].each { it }\n",
        ] {
            expect_no_offenses(COP, source);
        }
        CopCase::new(COP, "[1].each { it }\n", Vec::new())
            .target_ruby("3.4")
            .run();
    }

    /// 書き込まれる名前は上流では `lvasgn` で、`it += 1` は変数の読み書きであって
    /// メソッド呼び出しではない。
    #[test]
    fn a_name_being_assigned_is_a_variable() {
        for source in ["foo { it += 1 }\n", "foo { it = 1 }\n"] {
            CopCase::new(COP, source.to_owned(), Vec::new())
                .target_ruby("3.3")
                .run();
        }
    }
}

/// `Lint/UnexpectedBlockArity`。
///
/// 期待値は本家 1.89.0 を `--only Lint/UnexpectedBlockArity` で走らせた実出力から取った
/// (検出 6 件を確認済み)。
mod lint_unexpected_block_arity {
    use super::*;

    const COP: &str = "Lint/UnexpectedBlockArity";

    #[test]
    fn a_block_with_too_few_parameters_is_reported() {
        expect_offense(
            COP,
            r#"
            x.reduce { |a| a }
            ^^^^^^^^^^^^^^^^^^ `reduce` expects at least 2 positional arguments, got 1.
            "#,
        );
        expect_offense(
            COP,
            r#"
            x.reduce { }
            ^^^^^^^^^^^^ `reduce` expects at least 2 positional arguments, got 0.
            "#,
        );
        // 分解引数は 1 個として数える。
        expect_offense(
            COP,
            r#"
            x.inject { |(a, b)| a }
            ^^^^^^^^^^^^^^^^^^^^^^^ `inject` expects at least 2 positional arguments, got 1.
            "#,
        );
    }

    /// `restarg` はいくつでも受け取れる。レシーバ無しの呼び出しと一覧に無いメソッドは
    /// 対象外。
    #[test]
    fn what_the_cop_leaves_alone() {
        for source in [
            "x.reduce { |a, b| a }\n",
            "x.sort { |a, *b| a }\n",
            "reduce { |a| a }\n",
            "x.map { |a| a }\n",
        ] {
            expect_no_offenses(COP, source);
        }
    }
}

/// `Lint/LiteralAssignmentInCondition`。
///
/// 期待値は本家 1.89.0 を `--only Lint/LiteralAssignmentInCondition` で走らせた実出力から
/// 取った (検出 18 件を確認済み)。
mod lint_literal_assignment_in_condition {
    use super::*;

    const COP: &str = "Lint/LiteralAssignmentInCondition";

    /// レンジは `=` から右辺の末尾まで。
    #[test]
    fn a_literal_assigned_in_a_condition_is_reported() {
        expect_offense(
            COP,
            r#"
            if x = 1
                 ^^^ Don't use literal assignment `= 1` in conditional, should be `==` or non-literal operand.
            end
            "#,
        );
        for source in [
            "while y = \"str\"\nend\n",
            "until z = [1, 2]\nend\n",
            "if a = { b: 1 }\nend\n",
            "if (c = 1)\nend\n",
            "if f = :sym\nend\n",
            "if g = nil\nend\n",
            "if h = 1..2\nend\n",
            "x if y = 1\n",
            "x unless y = 2\n",
            "a = 1 if b = /re/\n",
            "c = (d = 4) ? 1 : 2\n",
            "if g = -1\nend\n",
            "if i = :\"a#{b}\"\nend\n",
            "def m\n  if n = 5\n  end\nend\n",
            "while r = 7 do end\n",
            "if e = <<~TXT\n  one\nTXT\nend\n",
        ] {
            let report = CopCase::new(COP, source, Vec::new())
                .without_offense_check()
                .inspect();
            assert_eq!(report.offenses.len(), 1, "{source:?}");
        }
    }

    /// `dstr` / `xstr` はリテラル扱いされず、`= *x` も対象外。本体がブロックの中に
    /// あるものは条件ではない。
    #[test]
    fn what_the_cop_leaves_alone() {
        for source in [
            "if x = foo\nend\n",
            "if b = [*c]\nend\n",
            "if d == 1\nend\n",
            "if e = \"a#{b}\"\nend\n",
            "if h = `cmd`\nend\n",
            "if j = [1].map { |k| k = 2 }\nend\n",
        ] {
            expect_no_offenses(COP, source);
        }
    }
}

/// `Lint/UselessRescue`。
///
/// 期待値は本家 1.89.0 を `--only Lint/UselessRescue` で走らせた実出力から取った
/// (検出 7 件を確認済み)。
mod lint_useless_rescue {
    use super::*;

    const COP: &str = "Lint/UselessRescue";

    /// 捕まえた例外をそのまま投げ直すだけの節は無意味。報告されるのは最後の節だけ。
    #[test]
    fn a_clause_that_only_reraises_is_reported() {
        expect_offense(
            COP,
            r#"
            begin
              x
            rescue
            ^^^^^^ Useless `rescue` detected.
              raise
            end
            "#,
        );
        for source in [
            "begin\n  x\nrescue => e\n  raise e\nend\n",
            "begin\n  x\nrescue => e\n  raise\nend\n",
            "begin\n  x\nrescue\n  raise $!\nend\n",
            "begin\n  x\nrescue\n  raise $ERROR_INFO\nend\n",
            "def m\n  x\nrescue\n  raise\nend\n",
            "begin\n  x\nrescue Foo => e\n  raise e\nrescue Bar => f\n  raise f\nend\n",
        ] {
            let report = CopCase::new(COP, source, Vec::new())
                .without_offense_check()
                .inspect();
            assert_eq!(report.offenses.len(), 1, "{source:?}");
        }
    }

    /// 本体が 2 文以上・引数が 2 つ・別の例外・空、そして `ensure` が例外変数を読む形は
    /// 無意味ではない。
    #[test]
    fn what_the_cop_leaves_alone() {
        for source in [
            "begin\n  x\nrescue => e\n  log(e)\n  raise e\nend\n",
            "begin\n  x\nrescue => e\n  raise Foo, e\nend\n",
            "begin\n  x\nrescue => e\n  raise other\nend\n",
            "begin\n  x\nrescue => e\n  raise e\nensure\n  puts e\nend\n",
            "begin\n  x\nrescue => e\nend\n",
        ] {
            expect_no_offenses(COP, source);
        }
    }
}

/// `Lint/ConstantResolution` (既定では無効)。
///
/// 期待値は本家 1.89.0 を `--only Lint/ConstantResolution` で走らせた実出力から取った。
mod lint_constant_resolution {
    use super::*;

    const COP: &str = "Lint/ConstantResolution";

    const ENABLED: &str = "Lint/ConstantResolution:\n  Enabled: true\n";

    #[test]
    fn an_unqualified_constant_read_is_reported() {
        CopCase::annotated(
            COP,
            r#"
            Foo
            ^^^ Fully qualify this constant to avoid possibly ambiguous resolution.
            "#,
        )
        .config(ENABLED)
        .run();
        // `Baz::Qux` の `Baz` は修飾されていない。`Foo::Bar = 1` の `Foo` も同じ。
        for source in [
            "Baz::Qux\n",
            "Foo::Bar = 1\n",
            "defined?(Foo)\n",
            "def m(x = Foo); end\n",
        ] {
            let report = CopCase::new(COP, source, Vec::new())
                .config(ENABLED)
                .without_offense_check()
                .inspect();
            assert_eq!(report.offenses.len(), 1, "{source:?}");
        }
    }

    /// `::` 付き・定数代入の代入先・`class` / `module` が定義する名前とその親クラスは
    /// 対象外。1 文だけの本体は本家ではその文が直接 `class` の子になる。
    #[test]
    fn what_the_cop_leaves_alone() {
        for source in [
            "::Bar\n",
            "Foo = 1\n",
            "module M\nend\n",
            "class C\nend\n",
            "class C < Foo\nend\n",
            "module M\n  Bar\nend\n",
        ] {
            CopCase::new(COP, source, Vec::new()).config(ENABLED).run();
        }
    }

    /// 多重代入の代入先も、大文字始まりのメソッド定義の名前も定数の参照ではない。
    #[test]
    fn a_multiple_assignment_target_and_a_capitalised_method_name_are_not_reads() {
        for source in ["A, B = 1, 2\n", "def O0(&block)\n  block\nend\n"] {
            CopCase::new(COP, source, Vec::new()).config(ENABLED).run();
        }
    }

    /// 引数の既定値に書いた定数は読み。文法は `def m(a = X, b = {})` を「並んだ代入先へ
    /// の 1 つの代入」と読むが、上流では引数 2 つと `X` の素の参照になる。
    #[test]
    fn a_constant_written_as_a_parameter_default_is_a_read() {
        let report = CopCase::new(
            COP,
            "def m(value = EMPTY, opts = {})\n  value\nend\n",
            Vec::new(),
        )
        .config(ENABLED)
        .without_offense_check()
        .inspect();
        assert_eq!(report.offenses.len(), 1);
    }

    /// 大文字で始まるメソッド呼び出しは本家では `send` で、定数の参照ではない。文法は
    /// メソッド名も定数と同じ節で書くので、名前の位置だけを外す。
    #[test]
    fn a_capitalised_method_call_is_not_a_constant() {
        for source in [
            "Rainbow('x')\n",
            "Integer('1')\n",
            "warn Rainbow('x').red\n",
        ] {
            CopCase::new(COP, source, Vec::new()).config(ENABLED).run();
        }
        // レシーバに立っている定数は参照のまま。
        let report = CopCase::new(COP, "Baz.qux\n", Vec::new())
            .config(ENABLED)
            .without_offense_check()
            .inspect();
        assert_eq!(report.offenses.len(), 1);
    }

    /// `Only` と `Ignore` は名前で絞る。
    #[test]
    fn the_two_name_lists_narrow_what_is_reported() {
        CopCase::new(COP, "Foo\nBaz::Qux\n", Vec::new())
            .config("Lint/ConstantResolution:\n  Enabled: true\n  Only: ['Foo']\n")
            .without_offense_check()
            .run();
        let report = CopCase::new(COP, "Foo\nBaz::Qux\n", Vec::new())
            .config("Lint/ConstantResolution:\n  Enabled: true\n  Ignore: ['Foo']\n")
            .without_offense_check()
            .inspect();
        assert_eq!(report.offenses.len(), 1);
    }
}

/// `Lint/ArrayLiteralInRegexp`。
///
/// 期待値は本家 1.89.0 を `--only Lint/ArrayLiteralInRegexp` で走らせた実出力から取った
/// (検出 12 件・`-A` の結果ともバイト一致を確認済み)。
mod lint_array_literal_in_regexp {
    use super::*;

    const COP: &str = "Lint/ArrayLiteralInRegexp";

    /// 全部が 1 文字なら文字クラス、そうでなければ選言。値は `Regexp.escape` される。
    #[test]
    fn a_literal_array_becomes_a_character_class_or_an_alternation() {
        expect_offense(
            COP,
            r#"
            /#{[1, 2]}/
             ^^^^^^^^^ Use a character class instead of interpolating an array in a regexp.
            "#,
        );
        expect_correction(
            COP,
            "/#{[1, 2]}/\n/#{['a', 'b']}/\n/#{[:a, :b]}/\n/#{['ab', 'cd']}/\n\
             /#{[1, 'a', nil, true]}/\n/x#{[1, 2]}y/\n/#{[]}/\n/#{[1]}/\n/#{['.', '*']}/\n",
            "/[12]/\n/[ab]/\n/[ab]/\n/(?:ab|cd)/\n/(?:1|a|nil|true)/\n/x[12]y/\n/[]/\n/[1]/\n\
             /[\\.\\*]/\n",
        );
    }

    /// リテラルでない要素は置き換え先が決められないので、別のメッセージで報告だけする。
    #[test]
    fn a_computed_element_is_reported_without_a_correction() {
        CopCase::annotated(
            COP,
            r#"
            /#{[foo, bar]}/
             ^^^^^^^^^^^^^ Use alternation or a character class instead of interpolating an array in a regexp.
            "#,
        )
        .correctable(false)
        .run();
    }

    #[test]
    fn what_the_cop_leaves_alone() {
        expect_no_offenses(COP, "\"#{[1, 2]}\"\n");
        expect_no_offenses(COP, "/#{foo}/\n");
    }
}

/// `Lint/SuppressedExceptionInNumberConversion`。
///
/// 期待値は本家 1.89.0 を `--only Lint/SuppressedExceptionInNumberConversion` で走らせた
/// 実出力から取った (検出 9 件・`-A` の結果ともバイト一致を確認済み)。
mod lint_suppressed_exception_in_number_conversion {
    use super::*;

    const COP: &str = "Lint/SuppressedExceptionInNumberConversion";

    #[test]
    fn the_rescue_becomes_an_exception_keyword_argument() {
        expect_offense(
            COP,
            r#"
            Integer('1') rescue nil
            ^^^^^^^^^^^^^^^^^^^^^^^ Use `Integer('1', exception: false)` instead.
            "#,
        );
        expect_correction(
            COP,
            "Integer('1') rescue nil\nFloat('1.0') rescue nil\nInteger('1', 10) rescue nil\n\
             Kernel.Integer('1') rescue nil\nRational('1') rescue nil\nBigDecimal('1') rescue nil\n\
             Complex('1') rescue nil\n",
            "Integer('1', exception: false)\nFloat('1.0', exception: false)\n\
             Integer('1', 10, exception: false)\nKernel.Integer('1', exception: false)\n\
             Rational('1', exception: false)\nBigDecimal('1', exception: false)\n\
             Complex('1', exception: false)\n",
        );
        expect_correction(
            COP,
            "begin\n  Integer('1')\nrescue ArgumentError, TypeError\n  nil\nend\n",
            "Integer('1', exception: false)\n",
        );
        expect_correction(
            COP,
            "begin\n  Integer('1')\nrescue ArgumentError\nend\n",
            "Integer('1', exception: false)\n",
        );
    }

    /// 例外クラスが広すぎる・例外変数を取る・`exception:` を既に書いている・戻り値が
    /// `nil` でないものは対象外。
    #[test]
    fn what_the_cop_leaves_alone() {
        for source in [
            "begin\n  Integer('1')\nrescue StandardError\n  nil\nend\n",
            "begin\n  Integer('1')\nrescue => e\n  nil\nend\n",
            "begin\n  Integer('1')\nrescue ArgumentError\n  0\nend\n",
            "Integer('1', exception: false) rescue nil\n",
            "Float('1', 2) rescue nil\n",
            "foo('1') rescue nil\n",
            "Integer('1') rescue 0\n",
        ] {
            expect_no_offenses(COP, source);
        }
    }
}

/// `Lint/UselessRuby2Keywords`。
///
/// 期待値は本家 1.89.0 を `--only Lint/UselessRuby2Keywords` で走らせた実出力から取った
/// (検出 4 件を確認済み)。
mod lint_useless_ruby2_keywords {
    use super::*;

    const COP: &str = "Lint/UselessRuby2Keywords";

    /// `def` を直接渡した形はセレクタだけ、シンボルで指す形は呼び出し全体がレンジ。
    #[test]
    fn a_signature_that_does_not_need_the_flag_is_reported() {
        expect_offense(
            COP,
            r#"
            ruby2_keywords def baz(*args, **kw); end
            ^^^^^^^^^^^^^^ `ruby2_keywords` is unnecessary for method `baz`.
            "#,
        );
        expect_offense(
            COP,
            r#"
            ruby2_keywords def qux(a); end
            ^^^^^^^^^^^^^^ `ruby2_keywords` is unnecessary for method `qux`.
            "#,
        );
        expect_offense(
            COP,
            r#"
            ruby2_keywords def non(); end
            ^^^^^^^^^^^^^^ `ruby2_keywords` is unnecessary for method `non`.
            "#,
        );
        expect_offense(
            COP,
            r#"
            class C
              def n(a); end
              ruby2_keywords :n
              ^^^^^^^^^^^^^^^^^ `ruby2_keywords` is unnecessary for method `n`.
            end
            "#,
        );
    }

    /// `*args` があってキーワード引数が無い形は本来の用途。定義が見つからないものも
    /// 対象外。
    #[test]
    fn what_the_cop_leaves_alone() {
        for source in [
            "ruby2_keywords def foo(*args); end\n",
            "ruby2_keywords def bar(a, *args); end\n",
            "class C\n  def m(*args); end\n  ruby2_keywords :m\nend\n",
            "class C\n  define_method(:o) { |*args| }\n  ruby2_keywords :o\nend\n",
            "ruby2_keywords :unknown\n",
        ] {
            expect_no_offenses(COP, source);
        }
    }
}

/// `Lint/UselessConstantScoping`。
///
/// 期待値は本家 1.89.0 を `--only Lint/UselessConstantScoping` で走らせた実出力から取った
/// (検出 3 件を確認済み)。
mod lint_useless_constant_scoping {
    use super::*;

    const COP: &str = "Lint/UselessConstantScoping";

    /// 直前の bare な可視性が `private` で、`private_constant` に載っていない定数が対象。
    #[test]
    fn a_constant_under_private_is_reported() {
        expect_offense(
            COP,
            r#"
            class C
              private
              FOO = 1
              ^^^^^^^ Useless `private` access modifier for constant scope.
            end
            "#,
        );
        // 一番後ろの可視性宣言だけが効く。
        expect_offense(
            COP,
            r#"
            class F
              public
              private
              FOO = 1
              ^^^^^^^ Useless `private` access modifier for constant scope.
            end
            "#,
        );
    }

    #[test]
    fn what_the_cop_leaves_alone() {
        for source in [
            "class C\n  private\n  BAR = 2\n  private_constant :BAR\nend\n",
            "class D\n  FOO = 1\n  private\n  def m; end\nend\n",
            "class G\n  private\n  public\n  BAR = 2\nend\n",
            "module M\n  private\n  Foo::BAR = 1\n  private_constant 'BAR'\nend\n",
        ] {
            expect_no_offenses(COP, source);
        }
    }
}

/// `Lint/CopDirectiveSyntax`。
///
/// 期待値は本家 1.89.0 を `--only Lint/CopDirectiveSyntax` で走らせた実出力から取った
/// (検出 7 件を確認済み)。
mod lint_cop_directive_syntax {
    use super::*;

    const COP: &str = "Lint/CopDirectiveSyntax";

    /// 追加メッセージはモード名の有無・妥当性・cop 名の有無で 4 通りに分かれる。
    #[test]
    fn the_four_reasons_have_their_own_messages() {
        expect_offense(
            COP,
            r#"
            # rubocop:
            ^^^^^^^^^^ Malformed directive comment detected. The mode name is missing.
            "#,
        );
        expect_offense(
            COP,
            r#"
            # rubocop:disable
            ^^^^^^^^^^^^^^^^^ Malformed directive comment detected. The cop name is missing.
            "#,
        );
        expect_offense(
            COP,
            r#"
            # rubocop:foo Style/For
            ^^^^^^^^^^^^^^^^^^^^^^^ Malformed directive comment detected. The mode name must be one of `enable`, `disable`, `todo`, `push`, or `pop`.
            "#,
        );
        expect_offense(
            COP,
            r#"
            # rubocop:disable Style/For Layout/LineLength
            ^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^ Malformed directive comment detected. Cop names must be separated by commas. Comment in the directive must start with `--`.
            "#,
        );
    }

    /// マーカーで始まらないもの、`--` で始まる注記付き、`push` / `pop`、`all` は
    /// 正しい形。
    #[test]
    fn what_the_cop_leaves_alone() {
        for source in [
            "# rubocop:disable Style/For\n",
            "# rubocop:enable Style/For\n",
            "# rubocop:disable Style/For, Layout/LineLength\n",
            "# rubocop:disable Style/For -- reason\n",
            "# rubocop:push\n",
            "# rubocop:pop\n",
            "# rubocop:push +Style/For\n",
            "#   # rubocop:disable Style/For\n",
            "# some text # rubocop:disable Style/For\n",
            "# rubocop : disable Style/For\n",
            "#rubocop:disable Style/For\n",
            "# rubocop:disable all\n",
            "# rubocop:todo Style/For\n",
        ] {
            expect_no_offenses(COP, source);
        }
    }
}

/// `Lint/DuplicateBranch`。
///
/// 期待値は本家 1.89.0 を `--only Lint/DuplicateBranch` で走らせた実出力から取った
/// (検出 17 件を確認済み)。
mod lint_duplicate_branch {
    use super::*;

    const COP: &str = "Lint/DuplicateBranch";

    /// レンジは本家の `duplicate_branch.parent`。`elsif` / `when` / `in` / `rescue` は
    /// その節全体、`else` はキーワードだけ、三項演算子は枝そのもの。
    #[test]
    fn the_owning_clause_is_the_reported_span() {
        CopCase::annotated(
            COP,
            r#"
            if a
              foo
            elsif b
            ^^^^^^^ Duplicate branch body detected.
              foo
            end
            "#,
        )
        .locations(&[(3, 1, 4, 5)])
        .lengths(&[13])
        .run();
        expect_offense(
            COP,
            r#"
            if a
              foo
            else
            ^^^^ Duplicate branch body detected.
              foo
            end
            "#,
        );
        CopCase::annotated(
            COP,
            r#"
            case x
            when 1
              foo
            when 2
            ^^^^^^ Duplicate branch body detected.
              foo
            end
            "#,
        )
        .locations(&[(4, 1, 5, 5)])
        .lengths(&[12])
        .run();
        CopCase::annotated(
            COP,
            r#"
            begin
              x
            rescue Foo
              foo
            rescue Bar
            ^^^^^^^^^^ Duplicate branch body detected.
              foo
            end
            "#,
        )
        .locations(&[(5, 1, 6, 5)])
        .lengths(&[16])
        .run();
        expect_offense(
            COP,
            r#"
            a ? foo : foo
                      ^^^ Duplicate branch body detected.
            "#,
        );
        CopCase::annotated(
            COP,
            r#"
            case y
            in 1
              foo
            in 2
            ^^^^ Duplicate branch body detected.
              foo
            end
            "#,
        )
        .target_ruby("3.0")
        .locations(&[(4, 1, 5, 5)])
        .lengths(&[10])
        .run();
    }

    /// 既定ではリテラルも定数も比べる。設定で切ると外れる。
    #[test]
    fn the_three_switches_narrow_what_is_compared() {
        let literal = "if a\n  [1, 2]\nelse\n  [1, 2]\nend\n";
        let constant = "if a\n  CONST\nelse\n  CONST\nend\n";
        for source in [literal, constant] {
            let report = CopCase::new(COP, source, Vec::new())
                .without_offense_check()
                .inspect();
            assert_eq!(report.offenses.len(), 1, "{source:?}");
        }
        CopCase::new(COP, literal, Vec::new())
            .config("Lint/DuplicateBranch:\n  IgnoreLiteralBranches: true\n")
            .run();
        CopCase::new(COP, constant, Vec::new())
            .config("Lint/DuplicateBranch:\n  IgnoreConstantBranches: true\n")
            .run();
        CopCase::new(
            COP,
            "if a\n  foo\nelsif b\n  bar\nelse\n  foo\nend\n",
            Vec::new(),
        )
        .config("Lint/DuplicateBranch:\n  IgnoreDuplicateElseBranch: true\n")
        .run();
    }

    #[test]
    fn what_the_cop_leaves_alone() {
        for source in [
            "if a\n  foo\nend\n",
            "if a\n  foo\nelse\n  bar\nend\n",
            "case x\nwhen 1\n  foo\nwhen 2\n  bar\nend\n",
            // ヒアドキュメントの中身は開始記号の下に書かれる。開始記号だけを見ると
            // どの `<<~EOS` も同じに見えてしまう。
            "if a\n  <<~EOS\n    one\n  EOS\nelse\n  <<~EOS\n    two\n  EOS\nend\n",
            "case x\nwhen 1\n  <<~A\n    one\n  A\nwhen 2\n  <<~B\n    two\n  B\nend\n",
        ] {
            expect_no_offenses(COP, source);
        }
    }

    /// 中身が同じなら終端記号の名前が違っても同じ枝。上流では中身だけが literal になる。
    #[test]
    fn two_heredocs_holding_the_same_text_are_one_branch() {
        let report = CopCase::new(
            COP,
            "if a\n  <<~A\n    same\n  A\nelse\n  <<~B\n    same\n  B\nend\n".to_owned(),
            Vec::new(),
        )
        .without_offense_check()
        .inspect();
        assert_eq!(report.offenses.len(), 1);
    }
}

/// `Style/MapIntoArray`。
///
/// 期待値は本家 1.89.0 を `--only Style/MapIntoArray` で走らせた実出力から取った
/// (検出 8 件 / 7 件・`-A` の結果ともバイト一致を確認済み)。
mod style_map_into_array {
    use super::*;

    const COP: &str = "Style/MapIntoArray";

    /// 空配列を作って `each` で詰めるだけの形は `map` の戻り値そのもの。詰め先の代入も
    /// 直後の読みも消え、`map` の結果がその変数に入る。
    #[test]
    fn pushing_into_a_fresh_array_becomes_map() {
        expect_correction(
            COP,
            "dest = []\nsrc.each { |e| dest << e * 2 }\ndest\n",
            "dest = src.map { |e| e * 2 }\n",
        );
        expect_correction(
            COP,
            "dest = []\nsrc.each { |e| dest.push(e) }\ndest\n",
            "dest = src.map { |e| e }\n",
        );
        expect_correction(
            COP,
            "dest = []\nsrc.each { |e| dest.append(e) }\n",
            "dest = src.map { |e| e }\n",
        );
    }

    /// 「空の配列」の書き方は 4 通りある。
    #[test]
    fn every_spelling_of_an_empty_array_counts() {
        for empty in ["[]", "Array.new", "Array[]", "Array.new([])"] {
            expect_correction(
                COP,
                &format!("dest = {empty}\nsrc.each {{ |e| dest << e }}\n"),
                "dest = src.map { |e| e }\n",
            );
        }
    }

    /// `[].tap { |dest| ... }` で包んだ形も対象で、`tap` ごと畳まれる。
    #[test]
    fn an_empty_array_tap_is_folded_too() {
        expect_correction(
            COP,
            "[].tap do |dest|\n  src.each { |e| dest << e }\nend\n",
            "dest = src.map { |e| e }\n",
        );
    }

    /// 空でない配列、詰め先が別の用途にも使われるもの、ブロックが詰める以外もするもの、
    /// 詰め先が宣言されていないもの、splat を詰めるものは黙る。
    #[test]
    fn what_the_cop_leaves_alone() {
        for source in [
            "dest = [1]\nsrc.each { |e| dest << e }\n",
            "dest = []\nsrc.each { |e| dest << e; foo }\n",
            "src.each { |e| dest << e }\n",
            "dest = []\nsrc.each { |e| dest.push(*e) }\n",
        ] {
            expect_no_offenses(COP, source);
        }
    }

    /// `begin ... end` は本家では `kwbegin` で、最後の文だけがその値になる。途中に置かれた
    /// `each` は戻り値が使われないので補正できる。
    #[test]
    fn a_keyword_begin_only_hands_on_its_last_statement() {
        expect_correction(
            COP,
            "x = begin\n  dest = []\n  src.each { |e| dest << e }\n  dest\nend\n",
            "x = begin\n  dest = src.map { |e| e }\nend\n",
        );
    }
}

/// `Security/IoMethods` — `IO` の読み書きを `File` へ寄せる。期待値は本家 1.89.0 の実測。
mod security_io_methods {
    use super::*;

    const COP: &str = "Security/IoMethods";

    /// レシーバは**ソースが `IO`** であることが条件なので、`::IO` も `Foo::IO` も対象外。
    /// 安全ナビゲーションは `csend` で `on_send` に届かない。
    #[test]
    fn only_a_receiver_written_exactly_as_io_is_reported() {
        CopCase::annotated(
            COP,
            r#"
            IO.read('/path/to/file')
            ^^^^^^^^^^^^^^^^^^^^^^^^ `File.read` is safer than `IO.read`.
            IO.foreach('/path/to/file') { |l| p l }
            ^^^^^^^^^^^^^^^^^^^^^^^^^^^ `File.foreach` is safer than `IO.foreach`.
            IO.read
            ^^^^^^^ `File.read` is safer than `IO.read`.
            ::IO.read('x')
            Foo::IO.read('x')
            IO&.read('x')
            File.read('x')
            IO.popen('x')
            "#,
        )
        .corrected(
            r#"
            File.read('/path/to/file')
            File.foreach('/path/to/file') { |l| p l }
            File.read
            ::IO.read('x')
            Foo::IO.read('x')
            IO&.read('x')
            File.read('x')
            IO.popen('x')
            "#,
        )
        .run();
    }

    /// 第 1 引数が `|` で始まる文字列はコマンドの実行なので `File` に置き換えられない。
    #[test]
    fn a_command_argument_is_left_alone() {
        for source in [
            "IO.read('| ls')\n",
            "IO.read('  | ls')\n",
            "IO.read(\"|ls\")\n",
        ] {
            expect_no_offenses(COP, source);
        }
        // 文字列でなければ判定できないので報告される。
        CopCase::annotated(
            COP,
            "IO.read(path)\n^^^^^^^^^^^^^ `File.read` is safer than `IO.read`.\n",
        )
        .corrected("File.read(path)\n")
        .run();
    }
}

/// `Security/CompoundHash` — 期待値は本家 1.89.0 の実測。
mod security_compound_hash {
    use super::*;

    const COP: &str = "Security/CompoundHash";
    const COMBINATOR: &str = "Use `[...].hash` instead of combining hash values manually.";
    const MONUPLE: &str =
        "Delegate hash directly without wrapping in an array when only using a single value.";
    const REDUNDANT: &str = "Calling .hash on elements of a hashed array is redundant.";

    /// 報告されるのは**最も外側**の結合だけ。`hash` の定義の中に限る。
    /// `def hash(x)` のように引数を取る定義は `(args)` に合わないので対象外。
    #[test]
    fn the_outermost_combination_inside_a_hash_definition_is_reported() {
        CopCase::annotated_with(
            COP,
            r#"
            def hash
              a.hash ^ b.hash
              ^^^^^^^^^^^^^^^ %{combinator}
            end
            def hash
              a.hash ^ (b.hash * c.hash)
              ^^^^^^^^^^^^^^^^^^^^^^^^^^ %{combinator}
            end
            def hash
              a.hash - b.hash
            end
            def other
              a.hash ^ b.hash
            end
            def hash(x)
              a.hash | b.hash
            end
            def hash()
              a.hash | b.hash
              ^^^^^^^^^^^^^^^ %{combinator}
            end
            "#,
            &[("combinator", COMBINATOR)],
        )
        .correctable(false)
        .run();
    }

    /// `def self.hash` / `define_method(:hash)` も定義。`x ^= y` の op-asgn と
    /// `a.^(b)` の呼び出しも結合として数える。
    #[test]
    fn every_spelling_of_the_definition_and_the_operator_counts() {
        CopCase::annotated_with(
            COP,
            r#"
            def self.hash
              x = a.hash
              x ^= b.hash
              ^^^^^^^^^^^ %{combinator}
            end
            define_method(:hash) do
              a.^(b)
              ^^^^^^ %{combinator}
            end
            define_method(:hash) do |x|
              a.hash * b.hash
            end
            "#,
            &[("combinator", COMBINATOR)],
        )
        .run();
    }

    /// 配列 1 要素の `.hash` は委譲すべき。要素の `.hash` は冗長。同じレンジに
    /// 2 つ当たると `add_offense` がレンジで弾くので最初の 1 件だけ残る。
    #[test]
    fn a_hashed_array_reports_its_wrapper_and_its_elements() {
        CopCase::annotated_with(
            COP,
            r#"
            [a].hash
            ^^^^^^^^ %{monuple}
            [a.hash, b.hash].hash
             ^^^^^^ %{redundant}
                     ^^^^^^ %{redundant}
            [[a].hash].hash
            ^^^^^^^^^^^^^^^ %{monuple}
             ^^^^^^^^ %{monuple}
            [a, b].hash
            "#,
            &[("monuple", MONUPLE), ("redundant", REDUNDANT)],
        )
        .run();
    }
}

/// `Metrics/CollectionLiteralLength` — 期待値は本家 1.89.0 の実測。
mod metrics_collection_literal_length {
    use super::*;

    const COP: &str = "Metrics/CollectionLiteralLength";
    const MSG: &str = "Avoid hard coding large quantities of data in code. \
                       Prefer reading the data from an external source.";
    const MAX3: &str = "Metrics/CollectionLiteralLength:\n  Max: 3\n";

    /// 数えるのは要素数で、閾値は `>=`。`%w[]` も配列。
    #[test]
    fn an_array_or_a_hash_at_the_threshold_is_reported() {
        CopCase::annotated_with(
            COP,
            r#"
            [1, 2, 3]
            ^^^^^^^^^ %{msg}
            [1, 2]
            { a: 1, b: 2, c: 3 }
            ^^^^^^^^^^^^^^^^^^^^ %{msg}
            %w[a b c]
            ^^^^^^^^^ %{msg}
            %i[a b c]
            ^^^^^^^^^ %{msg}
            "#,
            &[("msg", MSG)],
        )
        .config(MAX3)
        .correctable(false)
        .run();
    }

    /// `Set[...]` は `:[]` の呼び出しとして数える。定数はトップレベルの `Set` だけ。
    #[test]
    fn a_set_literal_is_counted_by_its_indices() {
        CopCase::annotated_with(
            COP,
            r#"
            Set[1, 2, 3]
            ^^^^^^^^^^^^ %{msg}
            Set[1, 2]
            ::Set[1, 2, 3]
            ^^^^^^^^^^^^^^ %{msg}
            Foo::Set[1, 2, 3]
            Set[1, 2, 3] = x
            "#,
            &[("msg", MSG)],
        )
        .config(MAX3)
        .run();
    }

    /// 波括弧を書かない `key: value` の並びも本家では 1 個の `hash` なので数えられる。
    /// 配列の中に書いた並びは配列の要素 1 個に畳まれる。
    #[test]
    fn a_braceless_hash_is_counted_as_the_hash_it_stands_for() {
        CopCase::annotated_with(
            COP,
            r#"
            foo(a: 1, b: 2, c: 3)
                ^^^^^^^^^^^^^^^^ %{msg}
            foo(1, a: 1, b: 2, c: 3)
                   ^^^^^^^^^^^^^^^^ %{msg}
            [a: 1, b: 2, c: 3]
             ^^^^^^^^^^^^^^^^ %{msg}
            "#,
            &[("msg", MSG)],
        )
        .config(MAX3)
        .run();
    }

    /// `Max` が無ければ閾値は `Float::INFINITY` なので何も報告されない。
    #[test]
    fn no_max_reports_nothing() {
        CopCase::new(COP, "[1, 2, 3]\n", Vec::new())
            .config("Metrics/CollectionLiteralLength:\n  Max: ~\n")
            .run();
    }
}

/// `Bundler/GemVersion` (既定無効) — 期待値は本家 1.89.0 の実測。
mod bundler_gem_version {
    use super::*;

    const COP: &str = "Bundler/GemVersion";
    const GEMFILE: &str = "Gemfile";

    /// 既定の `required` はバージョン要求もコミット参照も無い宣言を報告する。
    #[test]
    fn a_version_is_required_by_default() {
        CopCase::annotated(
            COP,
            r#"
            gem 'rubocop'
            ^^^^^^^^^^^^^ Gem version specification is required.
            gem 'rubocop', '~> 1.0'
            gem 'a', branch: 'main'
            gem 'b', { tag: 'v1' }
            gem 'd', github: 'x'
            ^^^^^^^^^^^^^^^^^^^^ Gem version specification is required.
            gem 'f', tag: 1
            ^^^^^^^^^^^^^^^ Gem version specification is required.
            "#,
        )
        .path(GEMFILE)
        .correctable(false)
        .run();
    }

    /// `forbidden` は逆向き。`AllowedGems` はどちらの体裁でも見送られる。
    #[test]
    fn the_forbidden_style_reports_the_pinned_declarations() {
        CopCase::annotated(
            COP,
            r#"
            gem 'rubocop'
            gem 'rubocop', '~> 1.0'
            ^^^^^^^^^^^^^^^^^^^^^^^ Gem version specification is forbidden.
            gem 'a', branch: 'main'
            ^^^^^^^^^^^^^^^^^^^^^^^ Gem version specification is forbidden.
            "#,
        )
        .path(GEMFILE)
        .config("Bundler/GemVersion:\n  EnforcedStyle: forbidden\n")
        .run();
        CopCase::new(COP, "gem 'rubocop'\ngem 'rspec'\n", Vec::new())
            .path(GEMFILE)
            .config("Bundler/GemVersion:\n  AllowedGems:\n    - rubocop\n    - rspec\n")
            .run();
    }
}

/// `Bundler/GemComment` (既定無効) — 期待値は本家 1.89.0 の実測。
mod bundler_gem_comment {
    use super::*;

    const COP: &str = "Bundler/GemComment";
    const GEMFILE: &str = "Gemfile";
    const MSG: &str = "Missing gem description comment.";

    /// 直上の行の**行頭コメント**が説明になる。前の宣言の行末コメントは前の宣言に
    /// 紐づくので、次の宣言の説明にはならない。空行を挟むと 2 行離れるので効かない。
    /// 先頭の magic comment は associator が読み飛ばすので説明にならない。
    #[test]
    fn a_comment_on_the_line_above_describes_the_declaration() {
        CopCase::annotated_with(
            COP,
            r#"
            # frozen_string_literal: true
            gem 'a'
            ^^^^^^^ %{msg}

            # A described gem
            gem 'b'
            gem 'c'
            ^^^^^^^ %{msg}
            gem 'd' # trailing description
            gem 'e'
            ^^^^^^^ %{msg}

            # far away

            gem 'f'
            ^^^^^^^ %{msg}
            "#,
            &[("msg", MSG)],
        )
        .path(GEMFILE)
        .correctable(false)
        .run();
    }

    /// 宣言の子ノードに紐づくコメントも説明になるので、複数行の宣言の途中や行末の
    /// コメントで足りる。`group` の直上のコメントは `group` の説明であって
    /// 中の宣言の説明ではない。
    #[test]
    fn a_comment_inside_the_declaration_or_the_group_body_counts() {
        CopCase::annotated_with(
            COP,
            r#"
            gem 'g',
              # why this version
              '1.0'
            gem 'h', # inline why
              '1.0'
            group :test do
              # described inside
              gem 'i'
              gem 'j'
              ^^^^^^^ %{msg}
            end
            # above the group
            group :dev do
              gem 'k'
              ^^^^^^^ %{msg}
            end
            "#,
            &[("msg", MSG)],
        )
        .path(GEMFILE)
        .run();
    }

    /// `OnlyFor` が空でなければ、そこに挙げたものを持つ宣言だけを報告する。
    #[test]
    fn only_for_narrows_the_declarations_that_need_a_comment() {
        CopCase::annotated_with(
            COP,
            r#"
            gem 'a'
            gem 'b', '~> 1.0'
            ^^^^^^^^^^^^^^^^^ %{msg}
            gem 'c', '>= 1.0'
            ^^^^^^^^^^^^^^^^^ %{msg}
            gem 'd', require: false
            gem 'e', github: 'x'
            "#,
            &[("msg", MSG)],
        )
        .path(GEMFILE)
        .config("Bundler/GemComment:\n  OnlyFor:\n    - version_specifiers\n")
        .run();
        // `>=` は先頭が `>` なので `restrictive_version_specifiers` に当たらない。
        CopCase::annotated_with(
            COP,
            r#"
            gem 'a'
            gem 'b', '~> 1.0'
            ^^^^^^^^^^^^^^^^^ %{msg}
            gem 'c', '>= 1.0'
            gem 'd', require: false
            gem 'e', github: 'x'
            "#,
            &[("msg", MSG)],
        )
        .path(GEMFILE)
        .config("Bundler/GemComment:\n  OnlyFor:\n    - restrictive_version_specifiers\n")
        .run();
        // 末尾ハッシュの鍵の名前も指定できる。`:require => false` の書き方も同じ鍵。
        CopCase::annotated_with(
            COP,
            r#"
            gem 'a'
            gem 'b', '~> 1.0'
            gem 'd', require: false
            ^^^^^^^^^^^^^^^^^^^^^^^ %{msg}
            gem 'e', github: 'x'
            ^^^^^^^^^^^^^^^^^^^^ %{msg}
            gem 'f', :require => false
            ^^^^^^^^^^^^^^^^^^^^^^^^^^ %{msg}
            "#,
            &[("msg", MSG)],
        )
        .path(GEMFILE)
        .config("Bundler/GemComment:\n  OnlyFor:\n    - require\n    - github\n")
        .run();
    }

    /// `AllowedGems` の gem は説明が無くても報告しない。
    #[test]
    fn allowed_gems_need_no_comment() {
        CopCase::new(COP, "gem 'a'\ngem 'b'\n", Vec::new())
            .path(GEMFILE)
            .config("Bundler/GemComment:\n  AllowedGems:\n    - a\n    - b\n")
            .run();
    }
}

/// `Naming/BlockForwarding` — 期待値は本家 1.89.0 の実測。既定は `anonymous`。
mod naming_block_forwarding {
    use super::*;

    const COP: &str = "Naming/BlockForwarding";
    const MSG: &str = "Use anonymous block forwarding.";

    /// `&block` の宣言と、それを渡している `&block` の両方を報告する。括弧が無い
    /// 引数リストには `add_parentheses` で括弧を付ける。
    #[test]
    fn the_parameter_and_every_pass_of_it_are_reported() {
        CopCase::annotated_with(
            COP,
            r#"
            def foo(&block)
                    ^^^^^^ %{msg}
              bar(&block)
                  ^^^^^^ %{msg}
            end
            def foo &block
                    ^^^^^^ %{msg}
              bar &block
                  ^^^^^^ %{msg}
            end
            def self.foo(&block)
                         ^^^^^^ %{msg}
              bar(&block)
                  ^^^^^^ %{msg}
              baz(&:sym)
            end
            "#,
            &[("msg", MSG)],
        )
        .target_ruby("3.1")
        .corrected(
            r#"
            def foo(&)
              bar(&)
            end
            def foo(&)
              bar(&)
            end
            def self.foo(&)
              bar(&)
              baz(&:sym)
            end
            "#,
        )
        .run();
    }

    /// 3.1 未満では構文自体が無いので何も報告しない。
    #[test]
    fn nothing_is_reported_before_ruby_31() {
        CopCase::new(COP, "def foo(&block)\n  bar(&block)\nend\n", Vec::new())
            .target_ruby("3.0")
            .run();
    }

    /// キーワード引数があると匿名の `&` は渡せない。本体が名前を変数として読んでいる
    /// ときも名前を落とせない。
    #[test]
    fn a_keyword_parameter_or_a_variable_read_keeps_the_name() {
        for source in [
            "def foo(k:, &block)\n  bar(&block)\nend\n",
            "def foo(&block)\n  block.call\nend\n",
            "def foo(&block)\n  block = 1\nend\n",
        ] {
            CopCase::new(COP, source, Vec::new())
                .target_ruby("3.1")
                .run();
        }
        // `**opts` は kwarg ではないので妨げにならない。
        CopCase::annotated_with(
            COP,
            r#"
            def foo(**opts, &block)
                            ^^^^^^ %{msg}
              bar(&block)
                  ^^^^^^ %{msg}
            end
            "#,
            &[("msg", MSG)],
        )
        .target_ruby("3.1")
        .corrected("def foo(**opts, &)\n  bar(&)\nend\n")
        .run();
    }

    /// 3.3 以下ではブロックの中の匿名 `&` が構文エラーになるので、ブロックの中で
    /// 渡している定義は 1 件も報告しない。レシーバや引数の側にあっても、本家では
    /// `block` ノードが `send` の上に乗るので「ブロックの中」に数える。
    #[test]
    fn a_pass_inside_a_block_stops_the_whole_definition() {
        for source in [
            "def foo(&block)\n  [1].each { bar(&block) }\nend\n",
            "def foo(x, &block)\n  Timer.new(x, &block).tap { |t| t }\nend\n",
        ] {
            CopCase::new(COP, source, Vec::new())
                .target_ruby("3.1")
                .run();
        }
    }

    /// `EnforcedStyle: explicit` は逆に匿名の `&` を報告して名前を付ける。
    #[test]
    fn the_explicit_style_names_the_anonymous_parameter() {
        CopCase::annotated(
            COP,
            r#"
            def foo(&)
                    ^ Use explicit block forwarding.
              bar(&)
                  ^ Use explicit block forwarding.
            end
            "#,
        )
        .target_ruby("3.1")
        .config("Naming/BlockForwarding:\n  EnforcedStyle: explicit\n")
        .corrected("def foo(&block)\n  bar(&block)\nend\n")
        .run();
    }
}

/// `Naming/PredicateMethod` — 期待値は本家 1.89.0 の実測。
mod naming_predicate_method {
    use super::*;

    const COP: &str = "Naming/PredicateMethod";
    const PREDICATE: &str = "Predicate method names should end with `?`.";
    const NON_PREDICATE: &str = "Non-predicate method names should not end with `?`.";

    /// 返す値がすべて真偽値なら `?` を付けるべき。比較・述語・否定の呼び出しも
    /// 真偽値を返すものとして数える。
    #[test]
    fn a_method_returning_only_booleans_should_be_a_predicate() {
        CopCase::annotated_with(
            COP,
            r#"
            def foo
                ^^^ %{predicate}
              x == y
            end
            def bar
                ^^^ %{predicate}
              x.nil?
            end
            def baz
                ^^^ %{predicate}
              !x
            end
            def qux
                ^^^ %{predicate}
              true && false
            end
            def quux = true
                ^^^^ %{predicate}
            "#,
            &[("predicate", PREDICATE)],
        )
        // 終端なし定義は 3.0 の構文。
        .target_ruby("3.0")
        .correctable(false)
        .run();
    }

    /// 逆に `?` で終わる名前が真偽値でないリテラルを返しうるなら `?` を外すべき。
    /// 保守的な既定では、真偽値を返しうる枝が 1 つでもあれば見送る。
    #[test]
    fn a_predicate_returning_a_literal_should_not_be_one() {
        CopCase::annotated_with(
            COP,
            r#"
            def foo?
                ^^^^ %{non_predicate}
              1
            end
            def bar?
              return 1 if x
              true
            end
            def baz?
                ^^^^ %{non_predicate}
              return nil
            end
            def qux? = 1
                ^^^^ %{non_predicate}
            "#,
            &[("non_predicate", NON_PREDICATE)],
        )
        .target_ruby("3.0")
        .run();
    }

    /// `super` は読めないので除き、読めない呼び出しが 1 つでもあれば保守的な既定では
    /// 名前を判定しない。`aggressive` では判定する。
    #[test]
    fn an_unreadable_call_is_left_alone_in_conservative_mode() {
        CopCase::new(COP, "def foo?\n  x.to_s\nend\n", Vec::new()).run();
        CopCase::annotated_with(
            COP,
            r#"
            def foo?
                ^^^^ %{non_predicate}
              return 1 if x
              y.to_s
            end
            "#,
            &[("non_predicate", NON_PREDICATE)],
        )
        .config("Naming/PredicateMethod:\n  Mode: aggressive\n")
        .run();
    }

    /// `initialize` / `AllowedMethods` / 演算子名 / 本体が空のものは対象外。
    /// `WaywardPredicates` の述語は真偽値を返すものとして数えない。
    #[test]
    fn the_exempt_definitions_are_skipped() {
        for source in [
            "def initialize\n  1\nend\n",
            "def call\n  1\nend\n",
            "def ==(other)\n  1\nend\n",
            "def foo?\nend\n",
            "def foo\n  x.infinite?\nend\n",
            "def foo\n  x.nonzero?\nend\n",
        ] {
            CopCase::new(COP, source, Vec::new()).run();
        }
        // `AllowBangMethods` を立てると `!` で終わる名前も外れる。
        CopCase::new(COP, "def foo!\n  1\nend\n", Vec::new())
            .config("Naming/PredicateMethod:\n  AllowBangMethods: true\n")
            .run();
    }

    /// 分岐は枝ごとの最後の値に展開される。`else` の無い `if` は `nil` の枝を足すので
    /// すべて真偽値にはならない。`elsif` があるときは足さない (本家の挙動)。
    #[test]
    fn a_conditional_expands_into_the_values_of_its_branches() {
        CopCase::annotated_with(
            COP,
            r#"
            def foo
                ^^^ %{predicate}
              if x
                true
              else
                false
              end
            end
            def bar
              if x
                true
              end
            end
            def baz
                ^^^ %{predicate}
              if x
                true
              elsif y
                false
              end
            end
            def qux
                ^^^ %{predicate}
              case x
              when 1 then true
              else false
              end
            end
            "#,
            &[("predicate", PREDICATE)],
        )
        .run();
    }
}

/// `Naming/InclusiveLanguage` (既定無効) — 期待値は本家 1.89.0 の実測。
mod naming_inclusive_language {
    use super::*;

    const COP: &str = "Naming/InclusiveLanguage";
    const BLACK: &str = "Consider replacing 'blacklist' with 'denylist' or 'block'.";
    const WHITE: &str = "Consider replacing 'whitelist' with 'allowlist' or 'permit'.";
    /// ファイルパスも既定で検査されるので、既定設定のケースは `CheckFilepaths: false` で
    /// 切ってからトークンだけを見る。
    const NO_PATH: &str = "Naming/InclusiveLanguage:\n  CheckFilepaths: false\n";

    /// 検査されるのは識別子・定数・インスタンス/クラス/グローバル変数・シンボル・
    /// コメント。文字列は既定で検査しない。ラベル (`foo:`) は `tLABEL` なので対象外。
    #[test]
    fn each_token_type_follows_its_own_switch() {
        CopCase::annotated_with(
            COP,
            r#"
            whitelist = 1
            ^^^^^^^^^ %{white}
            def blacklist; end
                ^^^^^^^^^ %{black}
            BLACKLIST = 1
            ^^^^^^^^^ Consider replacing 'BLACKLIST' with 'denylist' or 'block'.
            @whitelist = 3
             ^^^^^^^^^ %{white}
            @@whitelist = 4
              ^^^^^^^^^ %{white}
            $whitelist = 5
             ^^^^^^^^^ %{white}
            :blacklist
             ^^^^^^^^^ %{black}
            foo(blacklist: 1)
            { blacklist: 1 }
            'blacklist string'
            # a blacklist comment
                ^^^^^^^^^ %{black}
            "#,
            &[("white", WHITE), ("black", BLACK)],
        )
        .config(NO_PATH)
        .correctable(false)
        .run();
    }

    /// `?` / `!` で終わる名前は `tFID` なので対象外。素の `def` の名前だけが
    /// `tIDENTIFIER` になる (`def self.foo?` は `tFID`)。
    #[test]
    fn a_name_ending_in_a_question_mark_is_a_different_token() {
        CopCase::annotated_with(
            COP,
            r#"
            def blacklist?; end
                ^^^^^^^^^ %{black}
            def self.blacklist?; end
            blacklist?
            x.blacklist?
            alias blacklist? whitelist?
            :blacklist?
             ^^^^^^^^^ %{black}
            "#,
            &[("black", BLACK)],
        )
        .config(NO_PATH)
        .run();
    }

    /// `WholeWord` の項は語境界で切る。`_` の隣は境界として扱う。
    #[test]
    fn a_whole_word_term_needs_a_boundary() {
        CopCase::annotated(
            COP,
            r#"
            slave = 1
            ^^^^^ Consider replacing 'slave' with 'replica', 'secondary', or 'follower'.
            foo_slave = 2
                ^^^^^ Consider replacing 'slave' with 'replica', 'secondary', or 'follower'.
            slaves = 3
            enslaved = 4
            "#,
        )
        .config(NO_PATH)
        .run();
    }

    /// `CheckStrings` を立てると文字列・ヒアドキュメント・正規表現・`%w` の中も見る。
    /// 1 つのトークンに同じ語が 2 度あっても `add_offense` がレンジで弾くので 1 件。
    #[test]
    fn strings_are_checked_only_when_asked_for() {
        CopCase::annotated_with(
            COP,
            r#"
            'blacklist string'
             ^^^^^^^^^ %{black}
            "blacklist blacklist"
             ^^^^^^^^^ %{black}
            %w[blacklist]
               ^^^^^^^^^ %{black}
            /blacklist/
             ^^^^^^^^^ %{black}
            "#,
            &[("black", BLACK)],
        )
        .config("Naming/InclusiveLanguage:\n  CheckFilepaths: false\n  CheckStrings: true\n")
        .run();
    }

    /// 候補が 1 つだけの項は置き換えられる。`AllowedRegex` に当たる部分は
    /// `*` で覆ってから探すので見送られるが、レンジは元のトークンから引き直すため
    /// 同じ語の**最初の**出現位置になる。
    #[test]
    fn a_sole_suggestion_is_written_in() {
        CopCase::annotated(
            COP,
            r#"
            whitelist_ok = 1
            whitelist = 2
            ^^^^^^^^^ Consider replacing 'whitelist' with 'allowlist'.
            whitelist_ok_and_whitelist = 3
            ^^^^^^^^^ Consider replacing 'whitelist' with 'allowlist'.
            "#,
        )
        .config(concat!(
            "Naming/InclusiveLanguage:\n",
            "  CheckFilepaths: false\n",
            "  FlaggedTerms:\n",
            "    whitelist:\n",
            "      Regex: !ruby/regexp '/white[-_\\s]?list/'\n",
            "      AllowedRegex:\n",
            "        - 'whitelist_ok'\n",
            "      Suggestions:\n",
            "        - allowlist\n",
        ))
        .corrected("whitelist_ok = 1\nallowlist = 2\nallowlist_ok_and_allowlist = 3\n")
        .run();
    }

    /// `CheckFilepaths` はパスを 1 件の global offense で報告する。語が 2 つ以上なら
    /// 候補ではなく `with other terms` になる。
    #[test]
    fn the_file_path_is_reported_once() {
        CopCase::annotated(
            COP,
            "x = 1\n^{} Consider replacing 'blacklist' in file path with 'denylist' or 'block'.\n",
        )
        .path("blacklist_dir/plain.rb")
        .locations(&[(1, 1, 1, 1)])
        .lengths(&[0])
        .run();
        CopCase::annotated(
            COP,
            "x = 1\n^{} Consider replacing 'blacklist', 'whitelist' in file path with other terms.\n",
        )
        .path("blacklist_dir/whitelist_file.rb")
        .locations(&[(1, 1, 1, 1)])
        .lengths(&[0])
        .run();
    }
}

/// `Layout/SpaceBeforeBrackets` — 期待値は本家 1.89.0 の実測。
mod layout_space_before_brackets {
    use super::*;

    const COP: &str = "Layout/SpaceBeforeBrackets";
    const MSG: &str = "Remove the space before the opening brackets.";

    /// 添字読みの前の空白を消す。`a.[](0)` はドットがあるので対象外。
    /// 受け手が局所変数でなければ `undefined_method [0]` は配列を渡す呼び出しであって
    /// 添字ではないので報告しない。
    #[test]
    fn the_space_before_an_index_is_reported() {
        CopCase::annotated_with(
            COP,
            r#"
            collection = [1, 2]
            collection [0]
                      ^ %{msg}
            collection[0]
            collection  [0]
                      ^^ %{msg}
            collection [0] = 2
                      ^ %{msg}
            collection.[](0)
            collection&.[](0)
            undefined_method [0]
            foo.bar [1]
            %w[a b] [0]
                   ^ %{msg}
            h = { a: 1 } [:a]
                        ^ %{msg}
            "#,
            &[("msg", MSG)],
        )
        .corrected(
            r#"
            collection = [1, 2]
            collection[0]
            collection[0]
            collection[0]
            collection[0] = 2
            collection.[](0)
            collection&.[](0)
            undefined_method [0]
            foo.bar [1]
            %w[a b][0]
            h = { a: 1 }[:a]
            "#,
        )
        .run();
    }

    /// 添字の連鎖や添字の後ろの呼び出しも、文法上は配列を渡す呼び出しに読まれるが
    /// 本家では最初の `[` が添字なので報告する。
    #[test]
    fn a_chained_index_is_reported_at_the_first_bracket() {
        CopCase::annotated_with(
            COP,
            r#"
            collection = [1, 2]
            b = collection [0][1]
                          ^ %{msg}
            collection [0].foo
                      ^ %{msg}
            collection [0, 1]
                      ^ %{msg}
            collection %w[a]
            "#,
            &[("msg", MSG)],
        )
        .corrected(
            r#"
            collection = [1, 2]
            b = collection[0][1]
            collection[0].foo
            collection[0, 1]
            collection %w[a]
            "#,
        )
        .run();
    }
}

/// `Layout/LineContinuationSpacing` — 期待値は本家 1.89.0 の実測。
mod layout_line_continuation_spacing {
    use super::*;

    const COP: &str = "Layout/LineContinuationSpacing";

    /// 既定の `space` は空白 0 個と 2 個以上を報告する。1 個なら正しい。
    #[test]
    fn the_space_style_wants_exactly_one_blank() {
        CopCase::annotated(
            COP,
            r#"
            foo = 1 + \
              2
            baz = 1 +  \
                     ^^^ Use one space in front of backslash.
              2
            qux = 1 +\
                     ^ Use one space in front of backslash.
              2
            "#,
        )
        .corrected(
            r#"
            foo = 1 + \
              2
            baz = 1 + \
              2
            qux = 1 + \
              2
            "#,
        )
        .run();
    }

    /// `no_space` は逆に空白をすべて消す。
    #[test]
    fn the_no_space_style_wants_none() {
        CopCase::annotated(
            COP,
            r#"
            foo = 1 + \
                     ^^ Use zero spaces in front of backslash.
              2
            qux = 1 +\
              2
            "#,
        )
        .config("Layout/LineContinuationSpacing:\n  EnforcedStyle: no_space\n")
        .corrected(
            r#"
            foo = 1 +\
              2
            qux = 1 +\
              2
            "#,
        )
        .run();
    }

    /// 文字列・正規表現・逆クォート・ヒアドキュメント本体・`%w`・コメントの中の
    /// バックスラッシュは行継続ではないので見送る。
    #[test]
    fn a_backslash_inside_a_literal_is_not_a_continuation() {
        let source = concat!(
            "s = 'a \\\n",
            "b'\n",
            "d = \"a \\\n",
            "b\"\n",
            "r = /a \\\n",
            "b/\n",
            "c = `a \\\n",
            "b`\n",
            "w = %w[a \\\n",
            "b]\n",
            "h = <<~X\n",
            "  a \\\n",
            "  b\n",
            "X\n",
            "# comment \\\n",
        );
        CopCase::new(COP, source, Vec::new()).run();
        CopCase::new(COP, source, Vec::new())
            .config("Layout/LineContinuationSpacing:\n  EnforcedStyle: no_space\n")
            .run();
    }
}

/// `Layout/LineContinuationLeadingSpace` — 期待値は本家 1.89.0 の実測。
mod layout_line_continuation_leading_space {
    use super::*;

    const COP: &str = "Layout/LineContinuationLeadingSpace";

    /// 既定の `trailing` は次の行の先頭の空白を前の行の末尾へ移す。
    #[test]
    fn the_trailing_style_moves_the_leading_blanks_back() {
        CopCase::annotated(
            COP,
            r#"
            a = 'foo bar' \
                'baz qux'
            b = 'foo ' \
                'bar'
            c = 'foo' \
                ' bar'
                 ^ Move leading spaces to the end of the previous line.
            g = 'foo' \
                '   bar'
                 ^^^ Move leading spaces to the end of the previous line.
            i = "a" +
                " b"
            "#,
        )
        .corrected(
            r#"
            a = 'foo bar' \
                'baz qux'
            b = 'foo ' \
                'bar'
            c = 'foo ' \
                'bar'
            g = 'foo   ' \
                'bar'
            i = "a" +
                " b"
            "#,
        )
        .run();
    }

    /// `leading` は逆に前の行の末尾の空白を次の行の先頭へ移す。
    #[test]
    fn the_leading_style_moves_the_trailing_blanks_on() {
        CopCase::annotated(
            COP,
            r#"
            b = 'foo ' \
                    ^ Move trailing spaces to the start of the next line.
                'bar'
            f = 'foo   ' \
                    ^^^ Move trailing spaces to the start of the next line.
                'bar'
            c = 'foo' \
                ' bar'
            "#,
        )
        .config("Layout/LineContinuationLeadingSpace:\n  EnforcedStyle: leading\n")
        .corrected(
            r#"
            b = 'foo' \
                ' bar'
            f = 'foo' \
                '   bar'
            c = 'foo' \
                ' bar'
            "#,
        )
        .run();
    }

    /// 補間を含む文字列も `dstr` なので対象。3 つ以上の連結でも各継ぎ目を見る。
    #[test]
    fn an_interpolated_literal_and_a_longer_chain_are_read_too() {
        CopCase::annotated(
            COP,
            r#"
            k = "a#{1} " \
                      ^ Move trailing spaces to the start of the next line.
                "b"
            h = 'a' \
                'b' \
                ' c'
            "#,
        )
        .config("Layout/LineContinuationLeadingSpace:\n  EnforcedStyle: leading\n")
        .corrected(
            r#"
            k = "a#{1}" \
                " b"
            h = 'a' \
                'b' \
                ' c'
            "#,
        )
        .run();
    }
}

/// `Layout/EmptyLinesAfterModuleInclusion` — 期待値は本家 1.89.0 の実測。
mod layout_empty_lines_after_module_inclusion {
    use super::*;

    const COP: &str = "Layout/EmptyLinesAfterModuleInclusion";
    const MSG: &str = "Add an empty line after module inclusion.";

    /// `include` / `extend` / `prepend` の後ろには空行を置く。次の文がまた
    /// モジュール取り込みなら不要。ブロックの最後なら次の文が無いので不要。
    #[test]
    fn an_inclusion_followed_by_something_else_wants_a_blank_line() {
        CopCase::annotated_with(
            COP,
            r#"
            class A
              include Foo
              ^^^^^^^^^^^ %{msg}
              def bar; end
            end
            class B
              include Foo

              def bar; end
            end
            class C
              include Foo
              extend Bar
              prepend Baz

              def qux; end
            end
            class D
              include Foo
            end
            "#,
            &[("msg", MSG)],
        )
        .corrected(
            r#"
            class A
              include Foo

              def bar; end
            end
            class B
              include Foo

              def bar; end
            end
            class C
              include Foo
              extend Bar
              prepend Baz

              def qux; end
            end
            class D
              include Foo
            end
            "#,
        )
        .run();
    }

    /// 直下の `# rubocop:enable` は空行の代わりにならないが、補正の挿入位置は
    /// そのコメントの後ろになる。`# rubocop:disable` や普通のコメントは違う。
    #[test]
    fn an_enable_directive_below_takes_the_inserted_line() {
        CopCase::annotated_with(
            COP,
            r#"
            class E
              include Foo
              # rubocop:enable Style/For

              def bar; end
            end
            class F
              include Foo
              ^^^^^^^^^^^ %{msg}
              # rubocop:enable Style/For
              def bar; end
            end
            class G
              include Foo
              ^^^^^^^^^^^ %{msg}
              # a comment
              def bar; end
            end
            "#,
            &[("msg", MSG)],
        )
        .corrected(
            r#"
            class E
              include Foo
              # rubocop:enable Style/For

              def bar; end
            end
            class F
              include Foo
              # rubocop:enable Style/For

              def bar; end
            end
            class G
              include Foo

              # a comment
              def bar; end
            end
            "#,
        )
        .run();
    }

    /// 受け手付き・引数無し・他の呼び出しの引数・配列の要素は対象外。条件分岐の枝に
    /// 書かれた取り込みも次の文を持たないので対象外 (`elsif` の枝も同じ)。
    #[test]
    fn the_shapes_the_cop_passes_over() {
        for source in [
            "class J\n  self.include Foo\n  def bar; end\nend\n",
            "class K\n  include\n  def bar; end\nend\n",
            "class L\n  foo(include Bar)\n  def baz; end\nend\n",
            "class M\n  x = [include(Foo)]\n  def baz; end\nend\n",
            "class H\n  include Foo if x\n  def bar; end\nend\n",
            "class N\n  if a\n    include Foo\n  elsif b\n    include Bar\n  elsif c\n    include Baz\n  end\n  def bar; end\nend\n",
        ] {
            CopCase::new(COP, source, Vec::new()).run();
        }
        // 次の文が修飾形の取り込みでも取り込みとして扱う。
        CopCase::new(
            COP,
            "class I\n  include Foo\n  include Bar if x\n  def bar; end\nend\n",
            Vec::new(),
        )
        .run();
    }
}

/// 要素の改行を見る Layout 8 cop (すべて既定無効) — 期待値は本家 1.89.0 の実測。
mod layout_element_line_breaks {
    use super::*;

    const FIRST_ARRAY: &str = "Layout/FirstArrayElementLineBreak";
    const FIRST_HASH: &str = "Layout/FirstHashElementLineBreak";
    const FIRST_ARG: &str = "Layout/FirstMethodArgumentLineBreak";
    const FIRST_PARAM: &str = "Layout/FirstMethodParameterLineBreak";
    const MULTI_ARRAY: &str = "Layout/MultilineArrayLineBreaks";
    const MULTI_HASH: &str = "Layout/MultilineHashKeyLineBreaks";
    const MULTI_ARG: &str = "Layout/MultilineMethodArgumentLineBreaks";
    const MULTI_PARAM: &str = "Layout/MultilineMethodParameterLineBreaks";

    /// 最初の要素がリテラルと同じ行に始まり、他の要素が別の行にあるときだけ報告する。
    #[test]
    fn the_first_element_must_start_on_its_own_line() {
        CopCase::annotated(
            FIRST_ARRAY,
            r#"
            a = [1, 2]
            b = [
              1,
              2
            ]
            c = [1,
                 ^ Add a line break before the first element of a multi-line array.
              2]
            "#,
        )
        .corrected("a = [1, 2]\nb = [\n  1,\n  2\n]\nc = [\n1,\n  2]\n")
        .run();
        CopCase::annotated(
            FIRST_HASH,
            r#"
            i = { a: 1, b: 2 }
            k = { a: 1,
                  ^^^^ Add a line break before the first element of a multi-line hash.
              b: 2 }
            "#,
        )
        .corrected("i = { a: 1, b: 2 }\nk = { \na: 1,\n  b: 2 }\n")
        .run();
    }

    /// 引数とパラメータは括弧で開いたリストだけが対象 (`method_uses_parens?`)。
    #[test]
    fn only_a_parenthesised_list_is_measured() {
        CopCase::annotated(
            FIRST_ARG,
            r#"
            foo(1,
                ^ Add a line break before the first argument of a multi-line method argument list.
              2)
            bar 1,
              2
            "#,
        )
        .corrected("foo(\n1,\n  2)\nbar 1,\n  2\n")
        .run();
        CopCase::annotated(
            FIRST_PARAM,
            r#"
            def m(x,
                  ^ Add a line break before the first parameter of a multi-line method parameter list.
              y); end
            "#,
        )
        .corrected("def m(\nx,\n  y); end\n")
        .run();
    }

    /// 複数行のリストでは、前の要素と同じ行に始まる要素をすべて報告する。
    #[test]
    fn every_element_sharing_a_line_is_reported() {
        CopCase::annotated(
            MULTI_ARRAY,
            r#"
            d = [1, 2,
                    ^ Each item in a multi-line array must start on a separate line.
              3]
            e = [
              1, 2
            ]
            "#,
        )
        .run();
        CopCase::annotated(
            MULTI_HASH,
            r#"
            l = { a: 1, b: 2,
                        ^^^^ Each key in a multi-line hash must start on a separate line.
              c: 3 }
            "#,
        )
        .run();
        CopCase::annotated(
            MULTI_ARG,
            r#"
            foo(1, 2,
                   ^ Each argument in a multi-line method call must start on a separate line.
              3)
            "#,
        )
        .run();
        CopCase::annotated(
            MULTI_PARAM,
            r#"
            def m(x, y,
                     ^ Each parameter in a multi-line method definition must start on a separate line.
              z); end
            "#,
        )
        .run();
    }

    /// 括弧の無い `key: value` の並びは本家では 1 個の `hash` 引数。最後の引数のときだけ
    /// pair へ展開されるので、`&block` が後ろに付くと hash のまま測られる。
    #[test]
    fn a_braceless_hash_is_one_argument_unless_it_is_last() {
        CopCase::annotated(
            MULTI_ARG,
            r#"
            super_call(a: 1,
              b: 2)
            "#,
        )
        .cops(&[MULTI_ARG])
        .run();
        CopCase::annotated(
            MULTI_ARG,
            r#"
            def m(&block)
              mail(to: 1, from: 2,
                subject: 3, &block)
                            ^^^^^^ Each argument in a multi-line method call must start on a separate line.
            end
            "#,
        )
        .run();
        // 配列の中の並びも 1 個の hash に畳まれる。
        CopCase::new(
            MULTI_ARRAY,
            "assert_called_with Redis, :new, [\n  url: 1,\n  connect_timeout: 1, read_timeout: 1\n]\n",
            Vec::new(),
        )
        .run();
    }

    /// `super` は本家では独自のノードなので `MultilineMethodArgumentLineBreaks` は見ない
    /// (`FirstMethodArgumentLineBreak` だけが `on_super` を持つ)。
    #[test]
    fn super_is_seen_by_the_first_argument_cop_only() {
        CopCase::new(
            MULTI_ARG,
            "def m\n  super content_path: 1, key_path: 2,\n    env_key: 3\nend\n",
            Vec::new(),
        )
        .run();
        CopCase::annotated(
            FIRST_ARG,
            r#"
            def m
              super(1,
                    ^ Add a line break before the first argument of a multi-line method argument list.
                2)
            end
            "#,
        )
        .run();
    }

    /// `rescue` の例外一覧は本家では `array` なので配列の cop が見る。
    #[test]
    fn a_rescue_exception_list_is_an_array() {
        CopCase::annotated(
            MULTI_ARRAY,
            r#"
            begin
            rescue AError, BError,
                           ^^^^^^ Each item in a multi-line array must start on a separate line.
                   CError
              nil
            end
            "#,
        )
        .run();
    }

    /// `%w[]` の要素は空白で区切られる。文法は `\a` のような escape を含む並びを
    /// 1 要素に潰すので、要素の範囲はソースから測り直している。
    #[test]
    fn a_percent_literal_is_split_on_blanks() {
        CopCase::new(MULTI_ARRAY, "X = %w[\n  \\a \\c \\C \\e\n]\n", Vec::new()).run();
        CopCase::annotated(
            FIRST_ARRAY,
            r#"
            h = %w[a
                   ^ Add a line break before the first element of a multi-line array.
              b]
            "#,
        )
        .run();
    }

    /// `AllowMultilineFinalElement` は最後の要素が複数行に跨るのを許す。
    #[test]
    fn the_final_element_may_span_lines_when_allowed() {
        CopCase::annotated(
            FIRST_ARRAY,
            r#"
            a = [1, [2,
                     ^ Add a line break before the first element of a multi-line array.
              3]]
            "#,
        )
        .config("Layout/FirstArrayElementLineBreak:\n  AllowMultilineFinalElement: true\n")
        .run();
        CopCase::annotated(
            FIRST_ARRAY,
            r#"
            a = [1, [2,
                 ^ Add a line break before the first element of a multi-line array.
                     ^ Add a line break before the first element of a multi-line array.
              3]]
            "#,
        )
        .run();
    }
}
/// `Layout/SingleLineBlockChain` (既定無効) — 期待値は本家 1.89.0 の実測。
mod layout_redundant_line_break {
    use super::*;

    const COP: &str = "Layout/RedundantLineBreak";
    const MSG: &str = "Redundant line break detected.";

    /// 1 行に収まる式を複数行に割っているものを報告する。補正は行の切れ目を
    /// 空白 1 つに置き換えるので、括弧の内側に空白が残る。
    #[test]
    fn an_expression_that_fits_on_one_line_is_reported() {
        CopCase::annotated_with(
            COP,
            r#"
            foo(
            ^^^^ %{msg}
              a,
              b
            )
            foo(a, b)
            "#,
            &[("msg", MSG)],
        )
        .locations(&[(1, 1, 4, 1)])
        .lengths(&[15])
        .corrected("foo( a, b )\nfoo(a, b)\n")
        .run();
    }

    /// 逆斜線で割った文字列は 1 つのリテラルに畳まれる。引用符が違う組は `+` の
    /// 連結になり、どちらも同じ文字列を作るので木の比較は通る。
    #[test]
    fn a_split_string_literal_is_joined() {
        CopCase::annotated_with(
            COP,
            r#"
            puts 'a ' \
            ^^^^^^^^^^^ %{msg}
                 'b'
            x = "c" \
            ^^^^^^^^^ %{msg}
                'd'
            "#,
            &[("msg", MSG)],
        )
        .locations(&[(1, 1, 2, 8), (3, 1, 4, 7)])
        .lengths(&[20, 17])
        .corrected("puts 'a b'\nx = \"c\" + 'd'\n")
        .run();
    }

    /// ブロックは `InspectBlocks` が真のときだけ見る。
    #[test]
    fn a_block_is_looked_at_only_where_asked_for() {
        CopCase::new(COP, "foo(a) do |x|\n  puts x\nend\n", Vec::new()).run();
        CopCase::annotated_with(
            COP,
            r#"
            foo(a) do |x|
            ^^^^^^^^^^^^^ %{msg}
              puts x
            end
            "#,
            &[("msg", MSG)],
        )
        .config("Layout/RedundantLineBreak:\n  InspectBlocks: true\n")
        .locations(&[(1, 1, 3, 3)])
        .lengths(&[26])
        .corrected("foo(a) do |x| puts x end\n")
        .run();
    }

    /// 畳んだ結果が読み直せないものは報告しない。逆斜線で割った連鎖呼び出しは
    /// 畳むと `\` が呼び出しの前に残って構文が壊れ、修飾なしの `while` は区切り
    /// なしで 1 行に書けない。
    #[test]
    fn a_join_that_would_not_parse_is_not_reported() {
        CopCase::new(COP, "a = b \\\n  .c\n", Vec::new()).run();
        CopCase::new(COP, "d = while e\n        f\n      end\n", Vec::new()).run();
    }

    /// 行の切れ目を残す理由が式の中にあるもの: 途中のコメント、ヒアドキュメント、
    /// 改行を値に持つ文字列、複数行の `if`。
    #[test]
    fn what_keeps_the_break_is_left_alone() {
        CopCase::new(COP, "u = foo(\n  # note\n  1\n)\n", Vec::new()).run();
        CopCase::new(COP, "t = <<~X\n  y\nX\n", Vec::new()).run();
        CopCase::new(COP, "s = \"a\\nb\" \\\n    \"c\"\n", Vec::new()).run();
        CopCase::new(COP, "aa = bar(\n  if true\n    1\n  end\n)\n", Vec::new()).run();
    }

    /// 括弧なしの呼び出しに書かれたブロックは式の一部ではない。報告されるのは
    /// 呼び出しだけで `do ... end` は残り、引数が 1 行に収まっている呼び出しは
    /// そもそも複数行ではない。
    #[test]
    fn the_block_on_an_unparenthesized_call_is_no_part_of_the_expression() {
        CopCase::annotated_with(
            COP,
            r#"
            ll mm,
            ^^^^^^ %{msg}
               nn do
              1
            end
            jj kk do
              1
            end
            "#,
            &[("msg", MSG)],
        )
        .locations(&[(1, 1, 2, 5)])
        .lengths(&[12])
        .corrected("ll mm, nn do\n  1\nend\njj kk do\n  1\nend\n")
        .run();
    }
}

mod layout_single_line_block_chain {
    use super::*;

    const COP: &str = "Layout/SingleLineBlockChain";
    const MSG: &str = "Put method call on a separate line if chained to a single line block.";

    /// 1 行のブロックに続けて書いた呼び出しは行を分ける。ブロックが複数行なら、
    /// あるいは呼び出しが既に別の行にあるなら対象外。
    #[test]
    fn a_call_chained_onto_a_single_line_block_is_reported() {
        CopCase::annotated_with(
            COP,
            r#"
            a = b.map { |x| x }.first
                               ^^^^^^ %{msg}
            c = d.map { |x| x }
              .first
            e = f.map do |x|
              x
            end.first
            g = h.map { |x|
              x
            }.first
            k = l.map { |x| x }&.first
                               ^^^^^^^ %{msg}
            m = -> { 1 }.call
                        ^^^^^ %{msg}
            p1 = q.map { |x| x }[0]
            "#,
            &[("msg", MSG)],
        )
        .corrected(
            r#"
            a = b.map { |x| x }
            .first
            c = d.map { |x| x }
              .first
            e = f.map do |x|
              x
            end.first
            g = h.map { |x|
              x
            }.first
            k = l.map { |x| x }
            &.first
            m = -> { 1 }
            .call
            p1 = q.map { |x| x }[0]
            "#,
        )
        .run();
    }
}

/// `Layout/MultilineAssignmentLayout` (既定無効) — 期待値は本家 1.89.0 の実測。
mod layout_multiline_assignment_layout {
    use super::*;

    const COP: &str = "Layout/MultilineAssignmentLayout";
    const NEW_LINE: &str = "Right hand side of multi-line assignment is on the same line as the \
                            assignment operator `=`.";
    const SAME_LINE: &str = "Right hand side of multi-line assignment is not on the same line as \
                             the assignment operator `=`.";

    /// 既定の `new_line` は複数行の右辺が `=` と同じ行に始まるのを報告する。
    #[test]
    fn the_new_line_style_wants_the_right_hand_side_below() {
        CopCase::annotated_with(
            COP,
            r#"
            foo = if bar
            ^^^^^^^^^^^^ %{msg}
                    1
                  end
            baz =
              if bar
                1
              end
            qux = 1
            "#,
            &[("msg", NEW_LINE)],
        )
        .corrected("foo =\n if bar\n        1\n      end\nbaz =\n  if bar\n    1\n  end\nqux = 1\n")
        .run();
    }

    /// `same_line` は逆向き。
    #[test]
    fn the_same_line_style_wants_it_beside_the_operator() {
        CopCase::annotated_with(
            COP,
            r#"
            baz =
            ^^^^^ %{msg}
              if bar
                1
              end
            "#,
            &[("msg", SAME_LINE)],
        )
        .config("Layout/MultilineAssignmentLayout:\n  EnforcedStyle: same_line\n")
        .corrected("baz = if bar\n    1\n  end\n")
        .run();
    }

    /// `SupportedTypes` に無い右辺は対象外。ブロックは**自身の区切り文字**で 1 行かを
    /// 測るので、`foo { 1 }` に続けた連鎖は 1 行扱いになる。`_1` を読むブロックは
    /// `numblock` で `block_type?` が偽なので、1 行なら常に見送られる。
    #[test]
    fn a_block_is_measured_by_its_own_delimiters() {
        CopCase::annotated_with(
            COP,
            r#"
            a = foo { 1 }
            ^^^^^^^^^^^^^ %{msg}
              .bar { 2 }
            b = foo(1) { 2 }
            c = capture("x") { Book.first }
              .find { _1.payload }
            "#,
            &[("msg", NEW_LINE)],
        )
        .correctable(true)
        .run();
    }
}

/// `Layout/EmptyLineAfterMultilineCondition` (既定無効) — 期待値は本家 1.89.0 の実測。
mod layout_empty_line_after_multiline_condition {
    use super::*;

    const COP: &str = "Layout/EmptyLineAfterMultilineCondition";
    const MSG: &str = "Use empty line after multiline condition.";

    /// 複数行の条件の下には空行を置く。`if` / `unless` / `while` / `until` と
    /// その修飾形、`elsif` も同じ。
    #[test]
    fn a_multiline_condition_wants_a_blank_line_under_it() {
        CopCase::annotated_with(
            COP,
            r#"
            if a &&
               ^^^^ %{msg}
               b
              do_x
            end
            if a &&
               b

              do_x
            end
            if a
              do_x
            end
            unless a &&
                   ^^^^ %{msg}
                   b
              do_x
            end
            while a &&
                  ^^^^ %{msg}
                  b
              do_x
            end
            "#,
            &[("msg", MSG)],
        )
        .locations(&[(1, 4, 2, 4), (13, 8, 14, 8), (17, 7, 18, 7)])
        .lengths(&[9, 13, 12])
        .run();
    }

    /// 修飾形は後ろに文があるときだけ見る。`begin ... end while` は `while_post`。
    #[test]
    fn a_modifier_form_needs_something_after_it() {
        CopCase::annotated_with(
            COP,
            r#"
            do_x if a &&
                    ^^^^ %{msg}
                    b
            do_y
            do_x if a &&
                    b
            "#,
            &[("msg", MSG)],
        )
        .locations(&[(1, 9, 2, 9)])
        .lengths(&[14])
        .run();
    }

    /// `case` は `when` ごとに条件の一覧を、`rescue` は例外の一覧を見る。報告される
    /// ノードは条件ではなく `when` / `rescue` の枝で、空行は一覧の最後の行の下に入る。
    #[test]
    fn a_when_list_and_a_rescue_list_are_measured_whole() {
        CopCase::annotated_with(
            COP,
            r#"
            case x
            when 1,
            ^^^^^^^ %{msg}
                 2
              do_x
            when 3
              do_y
            end
            begin
              do_x
            rescue AError,
            ^^^^^^^^^^^^^^ %{msg}
                   BError
              do_y
            end
            begin
              do_x
            rescue AError
              do_y
            end
            "#,
            &[("msg", MSG)],
        )
        .locations(&[(2, 1, 4, 6), (10, 1, 12, 6)])
        .lengths(&[21, 35])
        .corrected(
            r#"
            case x
            when 1,
                 2

              do_x
            when 3
              do_y
            end
            begin
              do_x
            rescue AError,
                   BError

              do_y
            end
            begin
              do_x
            rescue AError
              do_y
            end
            "#,
        )
        .run();
    }

    /// `condition.multiline?` はブロックのときだけ**自身の区切り文字**で測る。
    /// `%w(...).any? { |k| k }` は書き方が複数行でも 1 行扱いなので報告しない。
    #[test]
    fn a_condition_ending_in_a_single_line_block_is_not_multiline() {
        CopCase::new(
            COP,
            "if %w(\n  A\n  B\n).any? { |key| ENV[key] }\n  do_x\nend\n",
            Vec::new(),
        )
        .run();
    }
}

/// `Style/StringHashKeys` (既定無効)。
///
/// 期待値は本家 1.89.0 を `--only Style/StringHashKeys` で走らせた実出力から取った
/// (検出 10 件・`-A` の結果ともバイト一致を確認済み)。
mod style_string_hash_keys {
    use super::*;

    const COP: &str = "Style/StringHashKeys";

    /// 位置は鍵の文字列だけ。置き換えは `Symbol#inspect` の綴り。
    #[test]
    fn a_string_key_becomes_a_symbol() {
        expect_offense(
            COP,
            r"
            { 'a' => 1 }
              ^^^ Prefer symbols instead of strings as hash keys.
            ",
        );
        expect_correction(COP, "{ 'a' => 1 }\n", "{ :a => 1 }\n");
        expect_correction(COP, "{ 'a' => 1, 'b' => 2 }\n", "{ :a => 1, :b => 2 }\n");
        // 素の名前にできない綴りは引用符付きのシンボルになる。
        expect_correction(COP, "{ 'a-b' => 1 }\n", "{ :\"a-b\" => 1 }\n");
        expect_correction(COP, "{ 'with space' => 1 }\n", "{ :\"with space\" => 1 }\n");
        expect_correction(
            COP,
            "{ \"tab\\there\" => 1 }\n",
            "{ :\"tab\\there\" => 1 }\n",
        );
    }

    /// 環境変数を渡す呼び出しでは文字列の鍵しか通らないので触らない。
    #[test]
    fn an_environment_hash_is_exempt() {
        for source in [
            "IO.popen({ 'A' => 'b' }, 'cmd')\n",
            "::IO.popen({ 'A' => 'b' }, 'cmd')\n",
            "Open3.capture2({ 'A' => 'b' }, 'cmd')\n",
            "Open3.popen3({ 'A' => 'b' }, 'cmd')\n",
            "Open3.pipeline([{ 'A' => 'b' }, 'cmd'])\n",
            "Kernel.spawn({ 'A' => 'b' }, 'cmd')\n",
            "spawn({ 'A' => 'b' }, 'cmd')\n",
            "system({ 'A' => 'b' }, 'cmd')\n",
            "str.gsub(/x/, { 'a' => 'b' })\n",
            "str.gsub!(/x/, { 'a' => 'b' })\n",
        ] {
            expect_no_offenses(COP, source);
        }
    }

    /// シンボルの鍵と補間する文字列は触らない。名前空間の違う `popen` は除外されない。
    #[test]
    fn what_the_cop_leaves_alone() {
        for source in [
            "{ a: 1 }\n",
            "{ :a => 1 }\n",
            "{ \"#{x}\" => 1 }\n",
            // `:` 区切りで書いた引用符付きの鍵はすでにシンボル。文法は `=>` 区切りと同じ
            // 節で書くので、区切り記号だけが違いになる。
            "{ 'a': 1 }\n",
            "{ \"a\": 1 }\n",
            "{ 'file:///x.rb': [] }\n",
            // `\xAD` は 1 バイトを書くので、鍵の中身は valid_encoding? を満たさない。
            "{ \"\\xAD\" => 1 }\n",
            "{ \"malformed \\251\" => 1 }\n",
        ] {
            expect_no_offenses(COP, source);
        }
        expect_correction(
            COP,
            "Foo.popen({ 'A' => 'b' }, 'cmd')\n",
            "Foo.popen({ :A => 'b' }, 'cmd')\n",
        );
    }
}

/// `Style/ArrayFirstLast` (既定無効)。
///
/// 期待値は本家 1.89.0 を `--only Style/ArrayFirstLast` で走らせた実出力から取った
/// (検出 9 件・`-A` の結果ともバイト一致を確認済み)。
mod style_array_first_last {
    use super::*;

    const COP: &str = "Style/ArrayFirstLast";

    /// 位置は `[...]` の部分。ドット付きで書かれていると selector から末尾まで。
    #[test]
    fn a_zero_or_minus_one_subscript_is_reported() {
        expect_offense(
            COP,
            r"
            a[0]
             ^^^ Use `first`.
            ",
        );
        expect_correction(COP, "a[0]\n", "a.first\n");
        expect_correction(COP, "a[-1]\n", "a.last\n");
        expect_correction(COP, "a.[](0)\n", "a.first\n");
        expect_correction(COP, "a.[](-1)\n", "a.last\n");
        expect_correction(COP, "a&.[](0)\n", "a&.first\n");
        expect_correction(COP, "[1, 2][0]\n", "[1, 2].first\n");
        expect_correction(COP, "a.b[0]\n", "a.b.first\n");
        expect_correction(COP, "h[0].c\n", "h.first.c\n");
    }

    /// 添字が続くもの、代入の左辺、`[0, 1]`、文字列の鍵は触らない。
    #[test]
    fn what_the_cop_leaves_alone() {
        for source in [
            "a[1]\n",
            "a[0][1]\n",
            "a[0][0]\n",
            "a[0] = 1\n",
            "a[0] += 1\n",
            "a[0, 1]\n",
            "a['k']\n",
            // `brace_method?` は親が何かだけを尋ねるので、別の添字の中に書いた添字も対象外。
            "a[b[0]]\n",
        ] {
            expect_no_offenses(COP, source);
        }
    }
}

/// `Style/RedundantInitialize`。
///
/// 期待値は本家 1.89.0 を `--only Style/RedundantInitialize` で走らせた実出力から取った
/// (検出 4 件・`-A` の結果ともバイト一致を確認済み)。
mod style_redundant_initialize {
    use super::*;

    const COP: &str = "Style/RedundantInitialize";

    /// 引数の無い空の `initialize` は「空」の方のメッセージになる。位置は定義全体。
    #[test]
    fn an_empty_initialize_is_reported() {
        CopCase::annotated(COP, "class A\n  def initialize\n  end\nend\n")
            .id("empty")
            .without_offense_check()
            .locations(&[(2, 3, 3, 5)])
            .lengths(&[20])
            .run();
        expect_correction(
            COP,
            "class A\n  def initialize\n  end\nend\n",
            "class A\nend\n",
        );
    }

    /// `super` へそのまま渡すだけの定義も消える。並びが変わっていたら残す。
    #[test]
    fn a_definition_that_only_forwards_is_reported() {
        expect_correction(
            COP,
            "class C\n  def initialize(a)\n    super\n  end\nend\n",
            "class C\nend\n",
        );
        expect_correction(
            COP,
            "class D\n  def initialize(a, b)\n    super(a, b)\n  end\nend\n",
            "class D\nend\n",
        );
        expect_no_offenses(
            COP,
            "class E\n  def initialize(a, b)\n    super(b, a)\n  end\nend\n",
        );
    }

    /// `*args` / `**kw` / `...` は渡す先が変わりうるので残す。`&blk` は `forwards?` には
    /// 数えないが、上流のパターン `(args $arg*)` が素の引数だけを取るので結局対象外になる。
    #[test]
    fn forwarding_parameters_keep_the_definition() {
        for source in [
            "class F\n  def initialize(*args)\n    super\n  end\nend\n",
            "class G\n  def initialize(**kw)\n    super\n  end\nend\n",
            "class H\n  def initialize(&blk)\n    super\n  end\nend\n",
        ] {
            expect_no_offenses(COP, source);
        }
    }

    /// 引数付きの空の定義、2 文以上の本体、`super` でない本体は触らない。
    /// 既定の `AllowComments: true` は本体にコメントがあるものを見送る。
    #[test]
    fn what_the_cop_leaves_alone() {
        for source in [
            "class B\n  def initialize(a)\n  end\nend\n",
            "class I\n  def initialize\n    # comment\n  end\nend\n",
            "class J\n  def initialize\n    do_something\n  end\nend\n",
            "class K\n  def initialize(a)\n    super(a)\n    other\n  end\nend\n",
        ] {
            expect_no_offenses(COP, source);
        }
    }

    /// `AllowComments: false` ならコメントがあっても報告する。
    #[test]
    fn allow_comments_off_reports_anyway() {
        CopCase::new(
            COP,
            "class I\n  def initialize\n    # comment\n  end\nend\n".to_owned(),
            Vec::new(),
        )
        .config("Style/RedundantInitialize:\n  AllowComments: false\n")
        .without_offense_check()
        .corrected("class I\nend\n")
        .run();
    }
}

/// `Style/NegativeArrayIndex`。
///
/// 期待値は本家 1.89.0 を `--only Style/NegativeArrayIndex` で走らせた実出力から取った
/// (検出 19 件・`-A` の結果ともバイト一致を確認済み)。
mod style_negative_array_index {
    use super::*;

    const COP: &str = "Style/NegativeArrayIndex";

    /// 位置は添字の式だけ。メッセージには元の書き方が入る。
    #[test]
    fn a_length_subtraction_becomes_a_negative_index() {
        expect_offense(
            COP,
            r"
            arr[arr.length - 1]
                ^^^^^^^^^^^^^^ Use `arr[-1]` instead of `arr[arr.length - 1]`.
            ",
        );
        expect_correction(COP, "arr[arr.length - 1]\n", "arr[-1]\n");
        expect_correction(COP, "arr[arr.size - 1]\n", "arr[-1]\n");
        expect_correction(COP, "arr[arr.count - 2]\n", "arr[-2]\n");
        expect_correction(COP, "arr[arr.length-1]\n", "arr[-1]\n");
        expect_correction(COP, "arr[arr.length - 1, 2]\n", "arr[-1, 2]\n");
        expect_correction(COP, "arr&.[](arr.length - 1)\n", "arr&.[](-1)\n");
        expect_correction(COP, "@arr[@arr.length - 1]\n", "@arr[-1]\n");
        expect_correction(COP, "self[length - 1]\n", "self[-1]\n");
    }

    /// 長さを保つメソッドが挟まっていても対象。並びが違っていても、受け手に土台があれば通る。
    #[test]
    fn length_preserving_chains_count() {
        expect_correction(COP, "arr.sort[arr.sort.length - 1]\n", "arr.sort[-1]\n");
        expect_correction(
            COP,
            "arr.sort.reverse[arr.sort.reverse.length - 1]\n",
            "arr.sort.reverse[-1]\n",
        );
        expect_correction(COP, "arr.sort[arr.length - 1]\n", "arr.sort[-1]\n");
    }

    /// 範囲の終端でも同じ。位置は終端の式で、置き換えは添字全体。
    #[test]
    fn a_range_end_is_handled_too() {
        expect_offense(
            COP,
            r"
            arr[0..arr.length - 1]
                   ^^^^^^^^^^^^^^ Use `arr[0..-1]` instead of `arr[0..arr.length - 1]`.
            ",
        );
        expect_correction(COP, "arr[0..arr.length - 1]\n", "arr[0..-1]\n");
        expect_correction(COP, "arr[0...arr.length - 1]\n", "arr[0...-1]\n");
        expect_correction(COP, "arr[1..arr.length - 2]\n", "arr[1..-2]\n");
        expect_correction(COP, "arr[(0..arr.length - 1)]\n", "arr[(0..-1)]\n");
        expect_correction(COP, "arr[foo..arr.length - 1]\n", "arr[foo..-1]\n");
    }

    /// 引き算でないもの、引く数が 0 や整数でないもの、受け手が違うもの、
    /// 長さを保たないメソッドが挟まるものは触らない。
    #[test]
    fn what_the_cop_leaves_alone() {
        for source in [
            "arr[arr.length - 0]\n",
            "arr[arr.length + 1]\n",
            "arr[other.length - 1]\n",
            "arr[length - 1]\n",
            "a.b[a.b.length - 1]\n",
            "arr[0..arr.length - 1.0]\n",
            "arr[arr.length - 1..2]\n",
        ] {
            expect_no_offenses(COP, source);
        }
    }
}

/// `Style/StaticClass` (既定無効)。
///
/// 期待値は本家 1.89.0 を `--only Style/StaticClass` で走らせた実出力から取った
/// (検出 9 件・`-A` の結果ともバイト一致を確認済み)。
mod style_static_class {
    use super::*;

    const COP: &str = "Style/StaticClass";

    /// 位置はクラス全体。`class` が `module` になり、名前の後ろに `module_function` が入る。
    #[test]
    fn a_class_of_only_class_methods_is_reported() {
        CopCase::annotated(COP, "class A\n  def self.foo; end\nend\n")
            .id("static")
            .without_offense_check()
            .locations(&[(1, 1, 3, 3)])
            .lengths(&[31])
            .run();
        expect_correction(
            COP,
            "class A\n  def self.foo; end\nend\n",
            "module A\nmodule_function\n\n  def foo; end\nend\n",
        );
    }

    /// `class << self`・定数代入・`extend` が混ざっていても通る。`class << self` は
    /// 見出しと `end` が消えるだけなので、字下げがそのまま残る。
    #[test]
    fn the_other_shapes_a_convertible_class_may_hold() {
        expect_correction(
            COP,
            "class C\n  class << self\n    def foo; end\n  end\nend\n",
            "module C\nmodule_function\n\n  \n    def foo; end\n  \nend\n",
        );
        expect_correction(
            COP,
            "class D\n  CONST = 1\n  def self.foo; end\nend\n",
            "module D\nmodule_function\n\n  CONST = 1\n  def foo; end\nend\n",
        );
        // `extend_call?` は selector しか見ないので、レシーバ付きの `extend` も通る。
        expect_correction(
            COP,
            "class F\n  Foo.extend Bar\n  def self.foo; end\nend\n",
            "module F\nmodule_function\n\n  Foo.extend Bar\n  def foo; end\nend\n",
        );
    }

    /// インスタンスメソッド・空のクラス・スーパークラス付き・可視性の指定が混ざったものは
    /// 触らない。
    #[test]
    fn what_the_cop_leaves_alone() {
        for source in [
            "class F\n  def foo; end\nend\n",
            "class G\nend\n",
            "class H < Base\n  def self.foo; end\nend\n",
            "class I\n  private\n  def self.foo; end\nend\n",
            "class J\n  class << self\n    private\n    def foo; end\n  end\nend\n",
            "module K\n  def self.foo; end\nend\n",
        ] {
            expect_no_offenses(COP, source);
        }
    }
}

/// `Style/RedundantArgument`。
///
/// 期待値は本家 1.89.0 を `--only Style/RedundantArgument` で走らせた実出力から取った
/// (検出 13 件・`-A` の結果ともバイト一致を確認済み)。
mod style_redundant_argument {
    use super::*;

    const COP: &str = "Style/RedundantArgument";

    /// 位置は括弧ごと。メッセージには書かれたままの引数が入る。
    #[test]
    fn an_argument_equal_to_the_default_is_reported() {
        expect_offense(
            COP,
            r"
            a.join('')
                  ^^^^ Argument '' is redundant because it is implied by default.
            ",
        );
        expect_correction(COP, "a.join('')\n", "a.join\n");
        expect_correction(COP, "a.join(\"\")\n", "a.join\n");
        expect_correction(COP, "a.sum(0)\n", "a.sum\n");
        expect_correction(COP, "'x'.split(' ')\n", "'x'.split\n");
        expect_correction(COP, "\"x\".chomp(\"\\n\")\n", "\"x\".chomp\n");
        expect_correction(COP, "\"x\".chomp!(\"\\n\")\n", "\"x\".chomp!\n");
    }

    /// 比べるのは Ruby が `inspect` する値なので、基数が違っても同じ数なら当たる。
    /// `true` / `false` は値を持たないノードで、ソースがそのまま比べられる。
    #[test]
    fn the_value_is_compared_the_way_ruby_inspects_it() {
        expect_correction(COP, "'x'.to_i(10)\n", "'x'.to_i\n");
        expect_correction(COP, "'x'.to_i(0xa)\n", "'x'.to_i\n");
        expect_correction(COP, "exit(true)\n", "exit\n");
        expect_correction(COP, "exit!(false)\n", "exit!\n");
    }

    /// 括弧なしなら前後の空白ごと落ちる。改行までは食わない。
    #[test]
    fn without_parentheses_the_spaces_go_too() {
        expect_correction(COP, "a.join ''\n", "a.join\n");
        expect_correction(COP, "a.chomp \"\\n\"\n", "a.chomp\n");
    }

    /// 既定と違う値、引数 2 個、レシーバの要る呼び出しをレシーバ無しで書いたもの、
    /// 単一引用符の `'\n'` (中身はバックスラッシュと n) は触らない。
    #[test]
    fn what_the_cop_leaves_alone() {
        for source in [
            "a.join(', ')\n",
            "a.sum(1)\n",
            "exit(false)\n",
            "'x'.to_i(16)\n",
            "'x'.split(\"\\t\")\n",
            "\"x\".chomp('\\n')\n",
            "join('')\n",
            "a.join\n",
            "a.join('', 1)\n",
        ] {
            expect_no_offenses(COP, source);
        }
    }
}

/// `Style/QuotedSymbols`。
///
/// 期待値は本家 1.89.0 を `--only Style/QuotedSymbols` で走らせた実出力から取った
/// (既定・両 `EnforcedStyle` それぞれで検出 5 件・`-A` の結果ともバイト一致を確認済み)。
mod style_quoted_symbols {
    use super::*;

    const COP: &str = "Style/QuotedSymbols";

    /// 既定 (`same_as_string_literals`) は `Style/StringLiterals` に従い、その既定は単一引用符。
    #[test]
    fn a_double_quoted_symbol_is_reported() {
        expect_offense(
            COP,
            r#"
            :"a"
            ^^^^ Prefer single-quoted symbols when you don't need string interpolation or special symbols.
            "#,
        );
        expect_correction(COP, ":\"a\"\n", ":'a'\n");
        expect_correction(COP, ":\"a-b\"\n", ":'a-b'\n");
        expect_correction(COP, "{ \"k\": 1 }\n", "{ 'k': 1 }\n");
        // 中身が空のものはハッシュの鍵でだけ `sym` になる。
        expect_correction(COP, "{ \"\": 1 }\n", "{ '': 1 }\n");
    }

    /// 単一引用符が要る綴り、補間するもの、`:''` / `:\"\"` (上流では dsym)、
    /// 引用符の無いシンボルは触らない。
    #[test]
    fn what_the_cop_leaves_alone() {
        for source in [
            ":'a'\n",
            ":a\n",
            "{ 'k' => 1 }\n",
            "{ k: 1 }\n",
            ":\"it's\"\n",
            ":'it\\'s'\n",
            ":\"a\\nb\"\n",
            ":'a\\nb'\n",
            ":\"#{x}\"\n",
            ":\"a#{'b'}\"\n",
            ":''\n",
            ":\"\"\n",
        ] {
            expect_no_offenses(COP, source);
        }
        // バックスラッシュだけの中身は単一引用符でもそのまま書けるので置き換わる。
        expect_correction(COP, ":\"\\\\\"\n", ":'\\\\'\n");
    }

    /// `double_quotes` は逆向き。`\n` のような意味のあるエスケープを持つ単一引用符は
    /// そのまま残る。
    #[test]
    fn the_double_quotes_style() {
        for (source, corrected) in [
            (":'a'\n", ":\"a\"\n"),
            ("{ 'k': 1 }\n", "{ \"k\": 1 }\n"),
            (":'a-b'\n", ":\"a-b\"\n"),
            (":'it\\'s'\n", ":\"it's\"\n"),
            (":'\\t'\n", ":'\\t'\n"),
        ] {
            CopCase::new(COP, source.to_owned(), Vec::new())
                .config("Style/QuotedSymbols:\n  EnforcedStyle: double_quotes\n")
                .without_offense_check()
                .corrected(corrected)
                .run();
        }
    }

    /// `same_as_string_literals` は `Style/StringLiterals` の設定を見に行く。
    #[test]
    fn the_default_style_follows_string_literals() {
        CopCase::new(COP, ":'a'\n".to_owned(), Vec::new())
            .config("Style/StringLiterals:\n  EnforcedStyle: double_quotes\n")
            .without_offense_check()
            .corrected(":\"a\"\n")
            .run();
    }
}

/// `Style/RedundantRegexpArgument`。
///
/// 期待値は本家 1.89.0 を `--only Style/RedundantRegexpArgument` で走らせた実出力から取った
/// (検出 14 件・`-A` の結果ともバイト一致を確認済み)。
mod style_redundant_regexp_argument {
    use super::*;

    const COP: &str = "Style/RedundantRegexpArgument";

    /// 1 つの文字列しか表さない正規表現は文字列に置き換わる。位置は引数だけ。
    #[test]
    fn a_deterministic_regexp_becomes_a_string() {
        expect_offense(
            COP,
            r"
            'a'.split(/,/)
                      ^^^ Use string `','` as argument instead of regexp `/,/`.
            ",
        );
        expect_correction(COP, "'a'.split(/,/)\n", "'a'.split(',')\n");
        expect_correction(COP, "'a'.gsub(/a/, 'b')\n", "'a'.gsub('a', 'b')\n");
        expect_correction(COP, "'a'.scan(/ab/)\n", "'a'.scan('ab')\n");
        expect_correction(COP, "'a'.start_with?(/a/)\n", "'a'.start_with?('a')\n");
        // 正規表現でだけ意味を持つバックスラッシュは落ちる。
        expect_correction(COP, "'a'.split(/\\./)\n", "'a'.split('.')\n");
    }

    /// 引用符は中身で決まる。文字列としても意味のあるエスケープは二重引用符が要る。
    #[test]
    fn the_quotes_follow_what_the_content_needs() {
        expect_correction(COP, "'a'.split(/\\n/)\n", "'a'.split(\"\\n\")\n");
        expect_correction(COP, "'a'.split(/\"/)\n", "'a'.split('\"')\n");
        expect_correction(COP, "'a'.split(/'/)\n", "'a'.split('\\'')\n");
        expect_correction(COP, "'a'.split(/\\\\/)\n", "'a'.split(\"\\\\\")\n");
        expect_correction(COP, "'a'.split(/a\\tb/)\n", "'a'.split(\"a\\tb\")\n");
    }

    /// 量指定子・文字クラス・オプション付き、`/ /`、対象外のメソッドは触らない。
    #[test]
    fn what_the_cop_leaves_alone() {
        for source in [
            "'a'.split(/ /)\n",
            "'a'.split(/\\s/)\n",
            "'a'.split(/a+/)\n",
            "'a'.split(/[ab]/)\n",
            "'a'.split(/a/i)\n",
            "'a'.split(',')\n",
            "'a'.index(/a/)\n",
        ] {
            expect_no_offenses(COP, source);
        }
    }

    /// 引用符の既定は `Style/StringLiterals` に従う。
    #[test]
    fn the_default_quotes_follow_string_literals() {
        CopCase::new(COP, "'a'.split(/,/)\n".to_owned(), Vec::new())
            .config("Style/StringLiterals:\n  EnforcedStyle: double_quotes\n")
            .without_offense_check()
            .corrected("'a'.split(\",\")\n")
            .run();
    }
}

/// `Style/OperatorMethodCall`。
///
/// 期待値は本家 1.89.0 を `--only Style/OperatorMethodCall` で走らせた実出力から取った
/// (検出 28 件・`-A` の結果ともバイト一致を確認済み)。
mod style_operator_method_call {
    use super::*;

    const COP: &str = "Style/OperatorMethodCall";

    /// 位置はドット 1 文字。
    #[test]
    fn the_dot_before_an_operator_is_reported() {
        expect_offense(
            COP,
            r"
            foo.+(bar)
               ^ Redundant dot detected.
            ",
        );
        expect_correction(COP, "foo.+(bar)\n", "foo +(bar)\n");
        expect_correction(COP, "foo.==(bar)\n", "foo ==(bar)\n");
        expect_correction(COP, "foo.<<(bar)\n", "foo <<(bar)\n");
        expect_correction(COP, "1.+(2)\n", "1 +(2)\n");
        // 括弧が無ければ selector の後ろに空白が入る。
        expect_correction(COP, "foo.+ bar\n", "foo + bar\n");
        // `/` の後ろの `(` は正規表現の始まりに読めるので空白を足す。
        expect_correction(COP, "foo./(bar)\n", "foo / (bar)\n");
    }

    /// 続きが繋がっているときは、引数の括弧を外して式全体を括弧で包む。
    #[test]
    fn a_chained_call_gets_parentheses_around_the_operation() {
        expect_correction(COP, "foo.+(bar).baz\n", "(foo + bar).baz\n");
        expect_correction(COP, "a.+(b) + c\n", "(a + b) + c\n");
        expect_correction(COP, "-foo.+(bar)\n", "-(foo + bar)\n");
        expect_correction(COP, "foo.+(\n  bar\n).baz\n", "(foo + bar).baz\n");
        // 引数の位置にあるものは包まない。
        expect_correction(COP, "baz(foo.+(bar))\n", "baz(foo +(bar))\n");
        expect_correction(COP, "a + b.+(c)\n", "a + b +(c)\n");
        expect_correction(COP, "x[foo.+(bar)]\n", "x[foo +(bar)]\n");
    }

    /// 引数が「子を持つ」ノードで、続きが繋がっていて、括弧付き — の 3 つが揃うと見送る。
    /// レシーバ無しの呼び出しと `nil` は上流では children.first が nil なので当たらない。
    #[test]
    fn an_argument_with_a_first_child_is_left_alone_when_chained() {
        for source in [
            "foo.+(1).baz\n",
            "foo.+(bar.baz).qux\n",
            "x = 1\nfoo.+(x).baz\n",
            "foo.+(@iv).baz\n",
            "foo.+(:sym).baz\n",
            "foo.+(\"s\").baz\n",
            "foo.+([1]).baz\n",
        ] {
            expect_no_offenses(COP, source);
        }
        expect_correction(COP, "foo.+(nil).baz\n", "(foo + nil).baz\n");
    }

    /// `[]`、定数レシーバ、splat / `&block`、引数が 1 個でないもの、`&.` は触らない。
    #[test]
    fn what_the_cop_leaves_alone() {
        for source in [
            "foo.[](bar)\n",
            "Foo.+(bar)\n",
            "foo.+(*bar)\n",
            "foo.+(&bar)\n",
            "foo.+(bar, baz)\n",
            "foo.+()\n",
            "foo + bar\n",
            "foo.!\n",
            "foo.~\n",
            "foo&.+(bar)\n",
        ] {
            expect_no_offenses(COP, source);
        }
    }
}

/// `Style/ReduceToHash`。
///
/// 期待値は本家 1.89.0 を `--only Style/ReduceToHash` で走らせた実出力から取った
/// (検出 10 件・`-A` の結果ともバイト一致を確認済み)。
mod style_reduce_to_hash {
    use super::*;

    const COP: &str = "Style/ReduceToHash";

    /// 位置は selector。置き換えは selector からブロックの閉じまで。
    #[test]
    fn a_fold_that_only_fills_a_hash_is_reported() {
        expect_offense(
            COP,
            r"
            xs.each_with_object({}) { |e, h| h[e] = e * 2 }
               ^^^^^^^^^^^^^^^^ Use `to_h { ... }` instead of `each_with_object`.
            ",
        );
        expect_correction(
            COP,
            "xs.each_with_object({}) { |e, h| h[e] = e * 2 }\n",
            "xs.to_h { |e| [e, e * 2] }\n",
        );
        expect_correction(
            COP,
            "xs.each_with_object({}) { |e, h| h[e.k] = e.v }\n",
            "xs.to_h { |e| [e.k, e.v] }\n",
        );
    }

    /// `inject` / `reduce` は蓄積器を返す 2 文の形。引数の順序が逆になる。
    #[test]
    fn the_folding_spellings_take_the_accumulator_first() {
        expect_correction(
            COP,
            "xs.inject({}) { |h, e| h[e] = e * 2; h }\n",
            "xs.to_h { |e| [e, e * 2] }\n",
        );
        expect_correction(
            COP,
            "xs.reduce({}) { |h, e| h[e] = e * 2; h }\n",
            "xs.to_h { |e| [e, e * 2] }\n",
        );
    }

    /// 番号付き引数では `inject` の要素が `_2` なので、`to_h` の `_1` に読み替える。
    #[test]
    fn the_numbered_spellings_are_renumbered() {
        expect_correction(
            COP,
            "xs.each_with_object({}) { _2[_1] = _1 * 2 }\n",
            "xs.to_h { [_1, _1 * 2] }\n",
        );
        expect_correction(
            COP,
            "xs.inject({}) { _1[_2] = _2 * 2; _1 }\n",
            "xs.to_h { [_1, _1 * 2] }\n",
        );
    }

    /// `do`...`end` は字下げが受け手の桁に揃う (上流の `block` ノードはレシーバから始まる)。
    #[test]
    fn a_do_end_block_keeps_the_receivers_indentation() {
        expect_correction(
            COP,
            "def m\n  xs.inject({}) do |h, e|\n    h[e] = e\n    h\n  end\nend\n",
            "def m\n  xs.to_h do |e|\n    [e, e]\n  end\nend\n",
        );
    }

    /// 種が空のハッシュでないもの、鍵や値が蓄積器を読むもの、蓄積器を返さない `inject`、
    /// 文が余分にあるものは触らない。
    #[test]
    fn what_the_cop_leaves_alone() {
        for source in [
            "xs.each_with_object([]) { |e, h| h[e] = e }\n",
            "xs.each_with_object({ a: 1 }) { |e, h| h[e] = e }\n",
            "xs.each_with_object({}) { |e, h| h[e] = h.size }\n",
            "xs.inject({}) { |h, e| h[e] = e }\n",
            "xs.each_with_object({}) { |e, h| h[e] = e; other }\n",
            "xs.each_with_object({}) { |e| e }\n",
            "xs.map { |e| e }\n",
        ] {
            expect_no_offenses(COP, source);
        }
    }

    /// 入れ子になった同じ形は、その回は内側だけが直る。`-A` は収束するまで回るので
    /// 2 パス目で外側も畳まれる。
    #[test]
    fn a_nested_fold_defers_the_outer_one() {
        expect_correction(
            COP,
            "xs.each_with_object({}) { |e, h| h[e] = ys.each_with_object({}) { |y, g| g[y] = y } }\n",
            "xs.to_h { |e| [e, ys.to_h { |y| [y, y] }] }\n",
        );
    }

    /// 2.6 未満では `to_h` がブロックを取らないので黙る。
    #[test]
    fn it_needs_ruby_2_6() {
        CopCase::new(
            COP,
            "xs.each_with_object({}) { |e, h| h[e] = e }\n".to_owned(),
            Vec::new(),
        )
        .target_ruby("2.5")
        .run();
    }
}

/// `Style/DocumentationMethod` (既定無効)。
///
/// 期待値は本家 1.89.0 を `--only Style/DocumentationMethod` で走らせた実出力から取った
/// (既定と `RequireForNonPublicMethods: true` の両方で一致)。
mod style_documentation_method {
    use super::*;

    const COP: &str = "Style/DocumentationMethod";

    /// 位置は定義全体。修飾子に渡した定義はその呼び出し全体になる。
    #[test]
    fn a_public_method_without_prose_is_reported() {
        expect_offense(
            COP,
            r"
            def foo; end
            ^^^^^^^^^^^^ Missing method documentation comment.
            ",
        );
        expect_offense(
            COP,
            r"
            module_function def mf; end
            ^^^^^^^^^^^^^^^^^^^^^^^^^^^ Missing method documentation comment.
            ",
        );
    }

    /// 直前の行のコメントがあれば触らない。注記・マジックコメント・ディレクティブは
    /// 説明とは数えない。
    #[test]
    fn a_comment_directly_above_is_documentation() {
        expect_no_offenses(COP, "# prose\ndef bar; end\n");
        expect_no_offenses(COP, "# prose\nmodule_function def mf2; end\n");
        for source in [
            "# TODO: annotation\ndef annotated; end\n",
            "# frozen_string_literal: true\ndef magic; end\n",
            "# rubocop:disable Style/For\ndef directive; end\n",
        ] {
            CopCase::new(COP, source.to_owned(), Vec::new())
                .without_offense_check()
                .run();
        }
    }

    /// `initialize` と、既定では非公開のメソッドは対象外。
    #[test]
    fn what_the_cop_leaves_alone() {
        for source in [
            "def initialize; end\n",
            "class A\n  private\n  def hidden; end\nend\n",
            "private def inline; end\n",
        ] {
            expect_no_offenses(COP, source);
        }
    }

    /// `RequireForNonPublicMethods` と `AllowedMethods` で範囲が変わる。
    #[test]
    fn the_settings_change_what_is_required() {
        CopCase::annotated(
            COP,
            r"
            class A
              private
              def hidden; end
              ^^^^^^^^^^^^^^^ Missing method documentation comment.
            end
            ",
        )
        .config("Style/DocumentationMethod:\n  RequireForNonPublicMethods: true\n")
        .run();
        CopCase::new(COP, "def foo; end\n".to_owned(), Vec::new())
            .config("Style/DocumentationMethod:\n  AllowedMethods:\n    - foo\n")
            .run();
    }

    /// 見えかたは「最後に書かれた印」で決まる。`private` を閉じる裸の `public` の下は
    /// また公開なので、そこの定義は咎められる。
    #[test]
    fn a_bare_public_puts_the_definitions_after_it_back_in_view() {
        expect_offense(
            COP,
            r"
            class C
              private

              def a; end

              public

              def b; end
              ^^^^^^^^^^ Missing method documentation comment.
            end
            ",
        );
    }

    /// `else` や `begin` の行末に書いたコメントは、その下の定義の説明になる。上流の
    /// 関連付けは「その行で終わるノード」にコメントを渡し、何も終わっていなければ
    /// 次のノードに渡すため、キーワードだけの行は素通しになる。
    #[test]
    fn a_comment_after_a_bare_keyword_documents_what_follows() {
        expect_no_offenses(
            COP,
            "if x\n  1\nelse # note\n  def foo\n    2\n  end\nend\n",
        );
        // 行に文があるときはそちらのコメントなので、定義は説明されていない。
        let report = CopCase::new(
            COP,
            "x = 1 # note\ndef foo\n  1\nend\n".to_owned(),
            Vec::new(),
        )
        .without_offense_check()
        .inspect();
        assert_eq!(report.offenses.len(), 1);
    }
}

/// `Lint/NonAtomicFileOperation`。
///
/// 期待値は本家 1.89.0 を `--only Lint/NonAtomicFileOperation` で走らせた実出力から取った
/// (検出 22 件・`-A` の結果ともバイト一致を確認済み)。
mod lint_non_atomic_file_operation {
    use super::*;

    const COP: &str = "Lint/NonAtomicFileOperation";

    /// 1 か所につき「存在確認を消す」(キーワードから条件の末尾まで) と「アトミックな
    /// メソッドへ替える」(呼び出し全体) の 2 件。後者は補正を持たない。
    #[test]
    fn the_check_and_the_method_are_reported_separately() {
        CopCase::annotated(
            COP,
            r#"
            unless File.exist?(path)
            ^^^^^^^^^^^^^^^^^^^^^^^^ Remove unnecessary existence check `File.exist?`.
              FileUtils.mkdir(path)
              ^^^^^^^^^^^^^^^^^^^^^ Use atomic file operation method `FileUtils.mkdir_p`.
            end
            "#,
        )
        .run();
    }

    /// 補正は条件と `end` を消し、メソッドを置き換える。`Dir.mkdir(path, mode)` の
    /// 位置引数はキーワードへ移り、既に force なメソッドは置き換えない。
    ///
    /// 先頭に 1 文置いてあるのは、補正後の 1 行目が空行になるとハーネスの `corrected`
    /// が字下げを削る際にそれを落としてしまうため。
    #[test]
    fn the_condition_and_the_end_are_removed() {
        expect_correction(
            COP,
            "x = 1\nunless File.exist?(path)\n  FileUtils.mkdir(path)\nend\n",
            "x = 1\n\n  FileUtils.mkdir_p(path)\n\n",
        );
        expect_correction(
            COP,
            "y = 2\nunless Dir.exist?(path)\n  Dir.mkdir(path, 0o700)\nend\n",
            "y = 2\n\n  FileUtils.mkdir_p(path, mode: 0o700)\n\n",
        );
        expect_correction(
            COP,
            "z = 3\nunless File.exist?(path)\n  FileUtils.makedirs(path)\nend\n",
            "z = 3\n\n  FileUtils.makedirs(path)\n\n",
        );
        // 修飾形は本体の後ろの `unless ...` を落とす。
        expect_correction(
            COP,
            "FileUtils.mkdir_p(path) unless File.exist?(path)\n",
            "FileUtils.mkdir_p(path)\n",
        );
    }

    /// `elsif` は連鎖の途中なので報告だけして補正しない。
    #[test]
    fn an_elsif_is_reported_but_not_corrected() {
        CopCase::annotated(
            COP,
            r#"
            if a
              b
            elsif File.exist?(path)
            ^^^^^^^^^^^^^^^^^^^^^^^ Remove unnecessary existence check `File.exist?`.
              FileUtils.rm(path)
              ^^^^^^^^^^^^^^^^^^ Use atomic file operation method `FileUtils.rm_f`.
            end
            "#,
        )
        .without_offense_check()
        .correctable(false)
        .run();
    }

    /// `force: false`、複合条件、`else` 付き、本体が 2 文、引数が食い違うものは対象外。
    #[test]
    fn what_the_cop_leaves_alone() {
        for source in [
            "if File.exist?(path)\n  FileUtils.rm(path, force: false)\nend\n",
            "if File.exist?(path) && x\n  FileUtils.rm(path)\nend\n",
            "if File.exist?(path)\n  FileUtils.rm(path)\nelse\n  y\nend\n",
            "if File.exist?(other)\n  FileUtils.rm(path)\nend\n",
            "unless File.exist?(path)\n  puts 1\n  FileUtils.mkdir_p(path)\nend\n",
            "FileUtils.rm(path)\n",
        ] {
            expect_no_offenses(COP, source);
        }
    }
}

/// `Lint/ConstantReassignment`。
///
/// 期待値は本家 1.89.0 を `--only Lint/ConstantReassignment` で走らせた実出力から取った
/// (検出 12 件を確認済み)。
mod lint_constant_reassignment {
    use super::*;

    const COP: &str = "Lint/ConstantReassignment";

    /// 名前空間ごとに追跡する。`class` / `module` の定義も名前を埋めるので、後から
    /// 同名の定数を代入すると衝突する。
    #[test]
    fn a_second_assignment_in_the_same_namespace_is_reported() {
        expect_offense(
            COP,
            r#"
            FOO = 1
            FOO = 2
            ^^^^^^^ Constant `FOO` is already assigned in this namespace.
            "#,
        );
        for source in [
            "class C\n  BAR = 1\n  BAR = 2\nend\n",
            "module M\n  BAZ = 1\nend\nmodule M\n  BAZ = 2\nend\n",
            "class D\nend\nD = 1\n",
            "A::B = 1\nA::B = 2\n",
            "::E = 1\n::E = 2\n",
            "G = [1].freeze\nG = 2\n",
            "H, I = 1, 2\nH = 3\n",
            "::O = 1\nO = 2\n",
            "class P\n  self::Q = 1\n  self::Q = 2\nend\n",
        ] {
            let report = CopCase::new(COP, source, Vec::new())
                .without_offense_check()
                .inspect();
            assert_eq!(report.offenses.len(), 1, "{source:?}");
        }
    }

    /// 条件付きの代入、`remove_const` を挟んだもの、別の名前空間、動的なスコープは
    /// 対象外。`Object.send(:remove_const, ...)` はレシーバ付きなので本家も見ない。
    #[test]
    fn what_the_cop_leaves_alone() {
        for source in [
            "QUX = 1\nQUX = 2 if x\n",
            "class J\nend\nclass J\nend\n",
            "module N\n  M1 = 1\n  remove_const :M1\n  M1 = 2\nend\n",
            "module N2\n  M2 = 1\n  self.remove_const :M2\n  M2 = 3\nend\n",
            "module Outer\n  module Inner\n    K = 1\n  end\nend\nclass Outer2\n  \
             L = 1\n  class Inner2\n    L = 2\n  end\nend\n",
            "foo::T = 1\nfoo::T = 2\n",
        ] {
            expect_no_offenses(COP, source);
        }
        // `Object.send(:remove_const, :F)` は削除として数えないので、後の代入は衝突する。
        let report = CopCase::new(
            COP,
            "F = 1\nObject.send(:remove_const, :F)\nF = 2\n",
            Vec::new(),
        )
        .without_offense_check()
        .inspect();
        assert_eq!(report.offenses.len(), 1);
    }
}

/// `Lint/DeprecatedReference`。
///
/// 本家のハンドラはどれも `return unless project_index` で始まる。索引は
/// `AllCops: UseProjectIndex` を立てて `rubydex` gem を入れたときだけ作られるので、
/// 既定では何も報告しない。sonicop は索引を持たないため常にその側に立つ。
mod lint_deprecated_reference {
    use super::*;

    const COP: &str = "Lint/DeprecatedReference";

    #[test]
    fn nothing_is_reported_without_a_project_index() {
        for source in [
            "# @deprecated Use bar instead.\ndef foo; end\nfoo\n",
            "class C\n  # @deprecated\n  BAR = 1\nend\nC::BAR\n",
        ] {
            expect_no_offenses(COP, source);
        }
    }
}

/// `Lint/NumberConversion` (既定では無効)。
///
/// 期待値は本家 1.89.0 を `--only Lint/NumberConversion` で走らせた実出力から取った
/// (検出 17 件・`-A` の結果ともバイト一致を確認済み)。
mod lint_number_conversion {
    use super::*;

    const COP: &str = "Lint/NumberConversion";

    const ENABLED: &str = "Lint/NumberConversion:\n  Enabled: true\n";

    #[test]
    fn a_conversion_call_becomes_class_parsing() {
        CopCase::annotated(
            COP,
            r#"
            "10".to_i
            ^^^^^^^^^ Replace unsafe number conversion with number class parsing, instead of using `"10".to_i`, use stricter `Integer("10", 10)`.
            "#,
        )
        .config(ENABLED)
        .corrected("Integer(\"10\", 10)\n")
        .run();
        CopCase::new(
            COP,
            "\"10.2\".to_f\n\"10\".to_c\n\"10\".to_r\nfoo.to_i\nfoo.to_i.to_f\n\
             Date.today.to_i\nfoo.bar.to_i\n",
            Vec::new(),
        )
        .config(ENABLED)
        .without_offense_check()
        .corrected(
            "Float(\"10.2\")\nComplex(\"10\")\nRational(\"10\")\nInteger(foo, 10)\n\
             Integer(foo, 10).to_f\nInteger(Date.today, 10)\nInteger(foo.bar, 10)\n",
        )
        .run();
    }

    /// `&:to_i` はブロックへ広がり、括弧は空白に置き換わる。
    #[test]
    fn a_symbol_proc_becomes_a_block() {
        CopCase::new(COP, "[1, 2].map(&:to_i)\nfoo.map(&:to_i)\n", Vec::new())
            .config(ENABLED)
            .without_offense_check()
            .corrected("[1, 2].map { |i| Integer(i, 10) }\nfoo.map { |i| Integer(i, 10) }\n")
            .run();
    }

    /// `&.` は `nil` を通す意図なので報告だけして補正しない。
    #[test]
    fn safe_navigation_is_reported_but_not_corrected() {
        CopCase::annotated(
            COP,
            r#"
            foo&.to_i
            ^^^^^^^^^ Replace unsafe number conversion with number class parsing, instead of using `foo&.to_i`, use stricter `Integer(foo, 10)`.
            "#,
        )
        .config(ENABLED)
        .correctable(false)
        .run();
    }

    /// 数値リテラル、変換メソッドの結果、`AllowedClasses` の既定 (`Time` / `DateTime`)、
    /// 引数が 2 つ以上の呼び出しは対象外。
    #[test]
    fn what_the_cop_leaves_alone() {
        for source in [
            "1.to_i\n",
            "1.5.to_f\n",
            "Time.now.to_i\n",
            "DateTime.now.to_f\n",
            "::Time.now.to_i\n",
            "[1, 2].each_with_object({}, &:to_i)\n",
            "to_i\n",
            "foo.to_s\n",
        ] {
            CopCase::new(COP, source, Vec::new()).config(ENABLED).run();
        }
    }

    /// 演算子と添字も上流では呼び出しなので、シンボルの引数を見るほうの経路に入る。
    #[test]
    fn a_symbol_passed_to_an_operator_or_an_index_is_seen_too() {
        for source in ["foo == :to_f\n", "h[:to_i]\n"] {
            let report = CopCase::new(COP, source, Vec::new())
                .config(ENABLED)
                .without_offense_check()
                .inspect();
            assert_eq!(report.offenses.len(), 1, "{source:?}");
        }
    }

    /// 入れ子の変換は報告するが補正はしない。外側の補正が書き換えた文字列を
    /// もう一度書き換えることになるので、本家は `ignore_node` で下りを外す。
    #[test]
    fn a_conversion_inside_a_corrected_one_is_reported_without_a_correction() {
        let report = CopCase::new(COP, "Math.sqrt(a.to_f / b).round.to_i\n", Vec::new())
            .config(ENABLED)
            .without_offense_check()
            .inspect();
        assert_eq!(report.offenses.len(), 2);
        assert!(report.offenses[0].is_correctable());
        assert!(!report.offenses[1].is_correctable());
    }
}

/// `Lint/RedundantTypeConversion`。
///
/// 期待値は本家 1.89.0 を `--only Lint/RedundantTypeConversion` で走らせた実出力から
/// 取った (検出 34 件・`-A` の結果ともバイト一致を確認済み)。
mod lint_redundant_type_conversion {
    use super::*;

    const COP: &str = "Lint/RedundantTypeConversion";

    /// レンジはセレクタだけ。補正はドットからセレクタ (あるいは閉じ括弧) までを消す。
    #[test]
    fn a_conversion_of_the_same_type_is_removed() {
        expect_offense(
            COP,
            r#"
            "foo".to_s
                  ^^^^ Redundant `to_s` detected.
            "#,
        );
        expect_correction(
            COP,
            "\"foo\".to_s\n:foo.to_sym\n1.to_i\n1.0.to_f\n1r.to_r\n1i.to_c\n[].to_a\n{}.to_h\n\
             \"foo#{x}\".to_s\n?a.to_s\n",
            "\"foo\"\n:foo\n1\n1.0\n1r\n1i\n[]\n{}\n\"foo#{x}\"\n?a\n",
        );
    }

    /// コンストラクタが返した値の変換も冗長。`exception: false` を渡していると
    /// `nil` になり得るので対象外。
    #[test]
    fn a_constructor_result_needs_no_conversion() {
        expect_correction(
            COP,
            "String.new(\"x\").to_s\nString(\"x\").to_s\nKernel.String(\"x\").to_s\n\
             Integer(\"1\").to_i\nBigDecimal(\"1\").to_d\nArray[1].to_a\nHash[[1,2]].to_h\n\
             Set.new.to_set\n",
            "String.new(\"x\")\nString(\"x\")\nKernel.String(\"x\")\nInteger(\"1\")\n\
             BigDecimal(\"1\")\nArray[1]\nHash[[1,2]]\nSet.new\n",
        );
        expect_no_offenses(COP, "Integer(\"1\", exception: false).to_i\n");
    }

    /// 同じ変換の 2 段重ねと、既に文字列を返すメソッドへの `to_s` も冗長。
    #[test]
    fn a_chain_of_the_same_conversion_is_reported() {
        expect_correction(
            COP,
            "foo.to_s.to_s\nfoo.inspect.to_s\nfoo.to_json.to_s\n",
            "foo.to_s\nfoo.inspect\nfoo.to_json\n",
        );
    }

    /// ブロック付きの `to_h` / `to_set`、括弧の中が呼び出しのものは対象外。
    #[test]
    fn what_the_cop_leaves_alone() {
        for source in [
            "foo.to_s\n",
            "foo.to_s()\n",
            "(foo).to_s\n",
            "[].to_h { |x| x }\n",
            "[].to_set(&:foo)\n",
            "x.to_h { |a| a }\n",
            "1.to_s\n",
        ] {
            expect_no_offenses(COP, source);
        }
    }
}

/// `Lint/SymbolConversion`。
///
/// 期待値は本家 1.89.0 を `--only Lint/SymbolConversion` で走らせた実出力から取った
/// (検出 20 件・`-A` の結果ともバイト一致を、`strict` / `consistent` 両方で確認済み)。
mod lint_symbol_conversion {
    use super::*;

    const COP: &str = "Lint/SymbolConversion";

    /// `to_sym` / `intern` の呼び出しは `Symbol#inspect` の綴りへ畳まれる。
    #[test]
    fn a_conversion_call_folds_into_a_symbol_literal() {
        expect_offense(
            COP,
            r#"
            "foo".to_sym
            ^^^^^^^^^^^^ Unnecessary symbol conversion; use `:foo` instead.
            "#,
        );
        expect_correction(
            COP,
            "\"foo\".to_sym\n:foo.to_sym\n\"foo bar\".to_sym\n\"a#{b}\".to_sym\n:foo.intern\n",
            ":foo\n:foo\n:\"foo bar\"\n:\"a#{b}\"\n:foo\n",
        );
    }

    /// 引用符が要らないシンボルは裸で書く。演算子・`@`/`$` 付き・`?` 付きも裸。
    #[test]
    fn unnecessary_quotes_are_dropped() {
        expect_correction(
            COP,
            ":\"foo\"\n:'foo'\n:\"[]\"\n:\"+\"\n:\"@a\"\n:\"$a\"\n:\"a?\"\n:\"A\"\n",
            ":foo\n:foo\n:[]\n:+\n:@a\n:$a\n:a?\n:A\n",
        );
    }

    /// ハッシュキーはコロン形なら先頭のコロンを落とした形が期待値になる。
    #[test]
    fn a_hash_key_keeps_the_shape_it_was_written_in() {
        expect_offense(
            COP,
            r#"
            { "a": 1 }
              ^^^ Unnecessary symbol conversion; use `a:` instead.
            "#,
        );
        expect_correction(
            COP,
            "{ \"a\": 1 }\n{ 'a': 1 }\n{ :\"a\" => 1 }\n{ \"_a\": 1 }\n{ \"Ab\": 1 }\n",
            "{ a: 1 }\n{ a: 1 }\n{ :a => 1 }\n{ _a: 1 }\n{ Ab: 1 }\n",
        );
    }

    /// `EnforcedStyle: consistent` では、引用符の要るキーが 1 つでもあるハッシュの
    /// キーをすべて引用符付きに揃える。`strict` だけの `=` 免除も無くなる。
    #[test]
    fn the_consistent_style_quotes_every_key_of_a_mixed_hash() {
        CopCase::new(COP, "{ \"a\": 1, \"b c\": 2 }\n", Vec::new())
            .config("Lint/SymbolConversion:\n  EnforcedStyle: consistent\n")
            .run();
        CopCase::annotated(
            COP,
            r#"
            x = :"foo="
                ^^^^^^^ Unnecessary symbol conversion; use `:foo=` instead.
            "#,
        )
        .config("Lint/SymbolConversion:\n  EnforcedStyle: consistent\n")
        .corrected("x = :foo=\n")
        .run();
    }

    /// 引用符が必要なもの、`alias`、`%i[]`、`=>` の文字列キー、`=` で終わるシンボル
    /// (既定の `strict`) は対象外。
    #[test]
    fn what_the_cop_leaves_alone() {
        for source in [
            ":foo\n",
            ":\"foo bar\"\n",
            "{ \"a b\": 1 }\n",
            "{ a: 1 }\n",
            "{ :a => 1 }\n",
            "alias :foo :bar\n",
            "alias :\"a\" :\"b\"\n",
            "%i[a b]\n",
            ":\"a#{b}\"\n",
            "x = :\"foo=\"\n",
            ":\"1a\"\n",
            ":\"\"\n",
            "{ \"1a\": 1 }\n",
            "{ \"-a\": 1 }\n",
            "x = { \"a\" => 1 }\n",
            ":\"a-b\"\n",
        ] {
            expect_no_offenses(COP, source);
        }
    }

    /// `Symbol#inspect` が裸で書く綴りは識別子だけではない。演算子・1 文字の
    /// グローバル・引用符を含む名前で、引用の要否の判定が本家と分かれていた。
    #[test]
    fn what_ruby_writes_bare_decides_the_quoting() {
        // `!~` は演算子なので `:"!~"` は余計な引用。
        let report = CopCase::new(COP, "x = :\"!~\"\n".to_owned(), Vec::new())
            .without_offense_check()
            .inspect();
        assert_eq!(report.offenses.len(), 1);
        assert!(report.offenses[0].message.contains(":!~"));
        // 1 文字のグローバルと、引用符を含む名前はそのままで正しい。
        for source in ["x = :$'\n", "x = :\"I\\\"like\\\"quotes\"\n"] {
            CopCase::new(COP, source.to_owned(), Vec::new()).run();
        }
    }

    /// 続けて書いた文字列は 1 つの `dstr` で、区切り記号を持たない。置換は値から
    /// 組み立てるので、各部分の引用符を外して繋げた綴りになる。
    #[test]
    fn adjacent_strings_are_one_literal() {
        let report = CopCase::new(
            COP,
            "a = 1\nx = \"#{ a }\" \\\n  \"b#{ a }\".to_sym\n".to_owned(),
            Vec::new(),
        )
        .without_offense_check()
        .inspect();
        assert_eq!(report.offenses.len(), 1);
        assert!(
            report.offenses[0].message.contains(":\"#{ a }b#{ a }\""),
            "{}",
            report.offenses[0].message
        );
    }
}

/// `Lint/ToEnumArguments`。
///
/// 期待値は本家 1.89.0 を `--only Lint/ToEnumArguments` で走らせた実出力から取った
/// (検出 5 件を確認済み)。
mod lint_to_enum_arguments {
    use super::*;

    const COP: &str = "Lint/ToEnumArguments";

    /// 引数が足りない・余っているものだけが報告される。
    #[test]
    fn a_mismatched_argument_list_is_reported() {
        expect_offense(
            COP,
            r#"
            def bar(x)
              return to_enum(:bar) unless block_given?
                     ^^^^^^^^^^^^^ Ensure you correctly provided all the arguments.
            end
            "#,
        );
        for source in [
            "def baz(x, y)\n  return to_enum(:baz, x) unless block_given?\nend\n",
            "def thud(x)\n  to_enum(:thud, x, 1)\nend\n",
            "def b(x, k: 1)\n  return to_enum(:b, x) unless block_given?\nend\n",
            "def c(x)\n  return to_enum(:c, x, k: 1) unless block_given?\nend\n",
        ] {
            let report = CopCase::new(COP, source, Vec::new())
                .without_offense_check()
                .inspect();
            assert_eq!(report.offenses.len(), 1, "{source:?}");
        }
    }

    /// 位置引数・省略可能引数・splat・キーワード・`**`・`...`・`__method__` のどれも
    /// 正しく渡していれば対象外。`def` の外や別のレシーバも見ない。
    #[test]
    fn what_the_cop_leaves_alone() {
        for source in [
            "def foo(x)\n  return to_enum(:foo, x) unless block_given?\nend\n",
            "def qux(x = 1)\n  return to_enum(:qux, x) unless block_given?\nend\n",
            "def quux(*args)\n  return to_enum(:quux, *args) unless block_given?\nend\n",
            "def corge(k:)\n  return to_enum(:corge, k: k) unless block_given?\nend\n",
            "def garply(**opts)\n  return to_enum(:garply, **opts) unless block_given?\nend\n",
            "def waldo(x)\n  return to_enum(__method__, x) unless block_given?\nend\n",
            "def fred(x)\n  return to_enum(:other, x) unless block_given?\nend\n",
            "def plugh(x, &blk)\n  return to_enum(:plugh, x) unless block_given?\nend\n",
            "def xyzzy(x)\n  return enum_for(:xyzzy, x) unless block_given?\nend\n",
            "def d(...)\n  return to_enum(:d, ...) unless block_given?\nend\n",
            "def g(x)\n  return self.to_enum(:g, x) unless block_given?\nend\n",
            "def h(x)\n  return foo.to_enum(:h, x) unless block_given?\nend\n",
            "to_enum(:top)\n",
        ] {
            CopCase::new(COP, source, Vec::new())
                .target_ruby("3.0")
                .run();
        }
    }

    /// 位置は呼び出しの引数までで、後ろに書いたブロックは含まない。上流ではブロックは
    /// 呼び出しを包む別のノードで、`send` はそこで終わっている。
    #[test]
    fn the_range_stops_before_a_block() {
        expect_offense(
            COP,
            r"
            def m(a)
              to_enum(:m) { 1 }
              ^^^^^^^^^^^ Ensure you correctly provided all the arguments.
            end
            ",
        );
    }
}

/// `Layout/LineEndStringConcatenationIndentation`。
///
/// 期待値は本家 1.89.0 を `--only Layout/LineEndStringConcatenationIndentation` で走らせた
/// 実出力から取った (既定 `aligned` で検出 4 件、`indented` でも `-A` までバイト一致を確認済み)。
mod layout_line_end_string_concatenation_indentation {
    use super::*;

    const COP: &str = "Layout/LineEndStringConcatenationIndentation";

    /// 値として渡された連結は先頭の部分に揃える。
    #[test]
    fn a_concatenation_used_as_a_value_is_aligned() {
        expect_correction(
            COP,
            "text = 'offense' \\\n  'not aligned'\n",
            "text = 'offense' \\\n       'not aligned'\n",
        );
        expect_no_offenses(COP, "text = 'offense' \\\n       'aligned'\n");
    }

    /// 呼び出しの引数として渡された連結も「値」なので揃える側。
    #[test]
    fn a_concatenation_handed_to_a_call_is_aligned_too() {
        expect_correction(
            COP,
            "puts 'offense' \\\n  'indented'\n",
            "puts 'offense' \\\n     'indented'\n",
        );
        expect_no_offenses(COP, "puts 'offense' \\\n     'aligned'\n");
    }

    /// 文そのものとして書かれた連結は 1 段下げる。`def` の本体がその場所。
    #[test]
    fn a_concatenation_written_as_a_statement_is_indented() {
        expect_no_offenses(COP, "def foo\n  'a' \\\n    'b'\nend\n");
        expect_correction(
            COP,
            "def bar\n  'a' \\\n  'b'\nend\n",
            "def bar\n  'a' \\\n    'b'\nend\n",
        );
    }

    /// `indented` に切り替えると、値として渡された連結も 1 段下げになる。
    #[test]
    fn the_indented_style_asks_for_one_level_everywhere() {
        CopCase::new(
            COP,
            "text = 'offense' \\\n       'aligned'\n".to_owned(),
            Vec::new(),
        )
        .config("Layout/LineEndStringConcatenationIndentation:\n  EnforcedStyle: indented\n")
        .without_offense_check()
        .corrected("text = 'offense' \\\n  'aligned'\n")
        .run();
    }

    /// `when` の枝に 1 文だけ書いた連結は、上流では親が `when` になるので「字下げ」側では
    /// なく「揃える」側。本体が 1 文のときそれ自体が文であって `begin` ではない。
    #[test]
    fn a_concatenation_alone_in_a_when_branch_is_aligned() {
        expect_no_offenses(COP, "case x\nwhen 1\n  'a' \\\n  'b'\nwhen 2\n  'c'\nend\n");
    }
}

/// `Layout/SingleLineBlockChain` / `Layout/EmptyLineAfterMultilineCondition` /
/// `Layout/MultilineAssignmentLayout` (いずれも既定では無効)。
///
/// 期待値は本家 1.89.0 を各 cop で走らせた実出力から取った (`-A` までバイト一致を確認済み)。
mod layout_disabled_trio {
    use super::*;

    fn case(cop: &str, source: &str) -> CopCase {
        CopCase::new(cop, source.to_owned(), Vec::new())
            .config(&format!("{cop}:\n  Enabled: true\n"))
    }

    fn correction(cop: &str, source: &str, corrected: &str) {
        case(cop, source)
            .without_offense_check()
            .corrected(corrected)
            .run();
    }

    /// 1 行で閉じたブロックに続く呼び出しは改行して分ける。ブロックが複数行なら黙る。
    #[test]
    fn a_call_chained_to_a_single_line_block_is_moved_down() {
        correction(
            "Layout/SingleLineBlockChain",
            "foo { }.bar\n",
            "foo { }\n.bar\n",
        );
        for source in [
            "foo {\n}.bar\n",
            "foo do\nend.bar\n",
            "foo { }\n  .bar\n",
            "foo.bar\n",
        ] {
            case("Layout/SingleLineBlockChain", source).run();
        }
    }

    /// 複数行に渡る条件の下には空行を置く。`if` / `while` / `until` / `when` / `rescue`。
    #[test]
    fn a_multiline_condition_is_followed_by_a_blank_line() {
        correction(
            "Layout/EmptyLineAfterMultilineCondition",
            "if a &&\n   b\n  foo\nend\n",
            "if a &&\n   b\n\n  foo\nend\n",
        );
        correction(
            "Layout/EmptyLineAfterMultilineCondition",
            "while a &&\n      b\n  foo\nend\n",
            "while a &&\n      b\n\n  foo\nend\n",
        );
        correction(
            "Layout/EmptyLineAfterMultilineCondition",
            "case x\nwhen 1,\n     2\n  foo\nend\n",
            "case x\nwhen 1,\n     2\n\n  foo\nend\n",
        );
        correction(
            "Layout/EmptyLineAfterMultilineCondition",
            "begin\n  a\nrescue Foo,\n       Bar\n  b\nend\n",
            "begin\n  a\nrescue Foo,\n       Bar\n\n  b\nend\n",
        );
    }

    /// すでに空行があるもの、1 行に収まる条件、後ろに何も無い後置条件は黙る。
    #[test]
    fn what_the_blank_line_cop_leaves_alone() {
        for source in [
            "if a &&\n   b\n\n  foo\nend\n",
            "if a\n  foo\nend\n",
            "foo if a &&\n       b\n",
        ] {
            case("Layout/EmptyLineAfterMultilineCondition", source).run();
        }
    }

    /// 既定の `new_line` は、複数行になる右辺を `=` の次の行から始めさせる。
    #[test]
    fn a_multiline_right_hand_side_starts_on_its_own_line() {
        correction(
            "Layout/MultilineAssignmentLayout",
            "x = if a\n  1\nend\n",
            // `insert_after(node.loc.operator, "\n")` なので、`=` の後ろにあった空白は
            // そのまま次の行の先頭に残る。
            "x =\n if a\n  1\nend\n",
        );
        case(
            "Layout/MultilineAssignmentLayout",
            "y =\n  if a\n    1\n  end\n",
        )
        .run();
        // `SupportedTypes` に無い型は対象外。
        case("Layout/MultilineAssignmentLayout", "w = [1,\n     2]\n").run();
    }

    /// `same_line` は逆に、右辺を `=` と同じ行から始めさせる。
    #[test]
    fn the_same_line_style_asks_for_the_other_direction() {
        CopCase::new(
            "Layout/MultilineAssignmentLayout",
            "y =\n  if a\n    1\n  end\n".to_owned(),
            Vec::new(),
        )
        .config("Layout/MultilineAssignmentLayout:\n  Enabled: true\n  EnforcedStyle: same_line\n")
        .without_offense_check()
        .corrected("y = if a\n    1\n  end\n")
        .run();
    }
}

/// `Style/NegatedIfElseCondition`。
///
/// 期待値は本家 1.89.0 を `--only Style/NegatedIfElseCondition` で走らせた実出力から取った
/// (検出 13 件・`-A` の結果ともバイト一致を確認済み)。
mod style_negated_if_else_condition {
    use super::*;

    const COP: &str = "Style/NegatedIfElseCondition";

    /// 位置は `if` 全体。条件を反転して枝を入れ替える。
    #[test]
    fn a_negated_condition_with_both_branches_is_reported() {
        // 複数行のレンジは注記が 1 行目しか表せないので位置で指定する。
        CopCase::annotated(COP, "if !x\n  a\nelse\n  b\nend\n")
            .id("if_else")
            .without_offense_check()
            .locations(&[(1, 1, 5, 3)])
            .lengths(&[22])
            .corrected("if x\n  b\nelse\n  a\nend\n")
            .run();
        expect_correction(
            COP,
            "if x != y\n  a\nelse\n  b\nend\n",
            "if x == y\n  b\nelse\n  a\nend\n",
        );
        expect_correction(
            COP,
            "if x !~ y\n  a\nelse\n  b\nend\n",
            "if x =~ y\n  b\nelse\n  a\nend\n",
        );
    }

    /// 三項演算子と `unless` も同じ。括弧の中の否定はその場で置き換わる。
    #[test]
    fn the_other_spellings_are_handled_too() {
        expect_correction(COP, "!x ? a : b\n", "x ? b : a\n");
        expect_correction(
            COP,
            "unless !x\n  a\nelse\n  b\nend\n",
            "unless x\n  b\nelse\n  a\nend\n",
        );
        expect_correction(
            COP,
            "if (!x)\n  a\nelse\n  b\nend\n",
            "if (x)\n  b\nelse\n  a\nend\n",
        );
    }

    /// if 側が空なら `else` の行ごと落ちる。
    #[test]
    fn an_empty_if_branch_drops_the_else_line() {
        expect_correction(COP, "if !x\nelse\n  b\nend\n", "if x\n  b\nend\n");
    }

    /// `!!x`、`elsif` を伴うもの、else の無いもの、否定でない条件は触らない。
    #[test]
    fn what_the_cop_leaves_alone() {
        for source in [
            "if !!x\n  a\nelse\n  b\nend\n",
            "if !x\n  a\nelsif y\n  b\nelse\n  c\nend\n",
            "if x\n  a\nelse\n  b\nend\n",
            "if !x\n  a\nend\n",
        ] {
            expect_no_offenses(COP, source);
        }
    }

    /// 入れ子は外側と内側の両方が報告される。補正を持つのは外側だけだが、
    /// `correctable` は 1 ケースにつき 1 つしか指定できないので、そこは
    /// 本家との `-A` 比較 (内側は直らない) で確かめてある。
    #[test]
    fn a_nest_reports_both_levels() {
        CopCase::annotated(
            COP,
            "if !x\n  if !y\n    a\n  else\n    b\n  end\nelse\n  c\nend\n",
        )
        .id("nested")
        .without_offense_check()
        .locations(&[(1, 1, 9, 3), (2, 3, 6, 5)])
        .lengths(&[51, 30])
        .run();
    }
}

/// `Lint/UnmodifiedReduceAccumulator`。
///
/// 期待値は本家 1.89.0 を `--only Lint/UnmodifiedReduceAccumulator` で走らせた実出力から
/// 取った (検出 12 件を確認済み)。
mod lint_unmodified_reduce_accumulator {
    use super::*;

    const COP: &str = "Lint/UnmodifiedReduceAccumulator";

    /// 蓄積器を返さない枝はメッセージ 1、蓄積器の要素を返す枝はメッセージ 2。
    #[test]
    fn a_branch_that_drops_the_accumulator_is_reported() {
        expect_offense(
            COP,
            r#"
            values.reduce({}) do |acc, el|
              el
              ^^ Ensure the accumulator `acc` will be modified by `reduce`.
            end
            "#,
        );
        expect_offense(
            COP,
            r#"
            values.reduce({}) do |acc, el|
              acc[el] = el
              ^^^^^^^^^^^^ Do not return an element of the accumulator in `reduce`.
            end
            "#,
        );
        for source in [
            "values.reduce(0) do |acc, el|\n  el * 2\nend\n",
            "values.reduce({}) do |acc, el|\n  acc[el[0]]\nend\n",
            "values.reduce(0) { |acc, el| some_method(el) }\n",
            "values.reduce(0) { |acc, el| \"#{el}\" }\n",
            "values.inject(0) { |acc, el| el }\n",
            "values.reduce([]) do |acc, (a, b)|\n  a\nend\n",
            "values.reduce(0) { _2 }\n",
        ] {
            let report = CopCase::new(COP, source, Vec::new())
                .target_ruby("3.0")
                .without_offense_check()
                .inspect();
            assert_eq!(report.offenses.len(), 1, "{source:?}");
        }
        // `next` が返す値も枝のひとつ。
        CopCase::annotated(
            COP,
            r#"
            values.reduce(0) do |acc, el|
              next el if el.nil?
                   ^^ Ensure the accumulator `acc` will be modified by `reduce`.
              acc + el
            end
            "#,
        )
        .run();
    }

    /// 蓄積器を返す枝がひとつでもあれば、要素に触っていれば、あるいは要素以外を
    /// 読んでいれば対象外。ブロック引数が 2 つ未満のものも見ない。
    #[test]
    fn what_the_cop_leaves_alone() {
        for source in [
            "values.reduce({}) do |acc, el|\n  acc[el] = el\n  acc\nend\n",
            "values.reduce(0) do |acc, el|\n  acc + el\nend\n",
            "values.reduce([]) do |acc, el|\n  acc << el\nend\n",
            "values.reduce([]) do |acc, el|\n  acc.push(el)\n  acc\nend\n",
            "values.reduce({}) do |acc, el|\n  acc[el]\nend\n",
            "values.reduce(0) do |acc, el|\n  next acc if el.nil?\n  acc + el\nend\n",
            "values.reduce(0) { |acc, el| some_method(acc, el) }\n",
            "values.reduce(0) { |acc| acc }\n",
            "values.each { |acc, el| el }\n",
            "values.reduce(0) do |acc, el|\n  el.foo(acc)\n  el\nend\n",
            "values.reduce(0) { _1 + _2 }\n",
            "values.reduce(0) { _1 }\n",
        ] {
            CopCase::new(COP, source, Vec::new())
                .target_ruby("3.0")
                .run();
        }
    }

    /// `break` が返す値は文法上では引数リストに包まれる。上流にはその節が無く、値は
    /// キーワードの直接の子なので、包みを外さないと「累算器を返している」ことを
    /// 見落とす。
    #[test]
    fn the_value_a_break_hands_back_counts_as_a_return_value() {
        expect_no_offenses(
            COP,
            "v.reduce(nil) do |offense, variable|\n  break offense unless x\n  variable\nend\n",
        );
    }
}

/// `Lint/UnusedPrivateMethod` と `Lint/NameTypo`。
///
/// どちらもハンドラが `project_index` の有無で早期 return する。索引は
/// `AllCops: UseProjectIndex` を立てて `rubydex` gem を入れたときだけ作られるので、
/// 既定では何も報告しない。sonicop は索引を持たないため常にその側に立つ。
mod lint_project_index_cops {
    use super::*;

    #[test]
    fn nothing_is_reported_without_a_project_index() {
        expect_no_offenses(
            "Lint/UnusedPrivateMethod",
            "class C\n  private\n  def unused_one; end\nend\n",
        );
        expect_no_offenses("Lint/NameTypo", "Foo::Barr\nFoo.barr\n");
    }
}

/// `Lint/HeredocMethodCallPosition` (既定では無効)。
///
/// 期待値は本家 1.89.0 を `--only Lint/HeredocMethodCallPosition` で走らせた実出力から
/// 取った (検出 6 件・`-A` の結果ともバイト一致を確認済み)。
mod lint_heredoc_method_call_position {
    use super::*;

    const COP: &str = "Lint/HeredocMethodCallPosition";

    const ENABLED: &str = "Lint/HeredocMethodCallPosition:\n  Enabled: true\n";

    /// レンジは終端行の次の行の 1 文字目。補正は呼び出しを開始行の末尾へ移す。
    #[test]
    fn the_call_moves_up_to_the_heredoc_opening() {
        CopCase::annotated(
            COP,
            r#"
            x = <<~SQL
              bar
            SQL
              .strip
            ^ Put a method call with a HEREDOC receiver on the same line as the HEREDOC opening.
            "#,
        )
        .config(ENABLED)
        .corrected("x = <<~SQL.strip\n  bar\nSQL\n")
        .run();
        // 直後のカンマは呼び出しと一緒に動く。
        CopCase::new(
            COP,
            "w = [\n  <<~SQL\n    bar\n  SQL\n  .strip,\n]\n",
            Vec::new(),
        )
        .config(ENABLED)
        .without_offense_check()
        .corrected("w = [\n  <<~SQL.strip,\n    bar\n  SQL\n]\n")
        .run();
    }

    /// 動かすと他のものまで連れて行く形は報告だけする。
    #[test]
    fn a_call_that_cannot_be_lifted_is_reported_only() {
        for source in [
            "foo(<<~SQL\n  bar\nSQL\n     .strip)\n",
            "v = <<~SQL\n  bar\nSQL\n  .strip\n  .chomp\n",
        ] {
            CopCase::new(COP, source, Vec::new())
                .config(ENABLED)
                .without_offense_check()
                .correctable(false)
                .run();
        }
    }

    /// 開始行に書かれた呼び出しと、呼び出しの無いヒアドキュメントは対象外。
    #[test]
    fn what_the_cop_leaves_alone() {
        for source in [
            "foo(<<~SQL)\n  bar\nSQL\n",
            "foo(<<~SQL.strip)\n  bar\nSQL\n",
            "y = <<~SQL.strip\n  bar\nSQL\n",
            "z = [\n  <<~SQL,\n    bar\n  SQL\n]\n",
            "d = <<~SQL.strip.chomp\n  x\nSQL\n",
        ] {
            CopCase::new(COP, source, Vec::new()).config(ENABLED).run();
        }
    }
}

/// `Lint/ShadowingOuterLocalVariable` (既定では無効)。
///
/// 期待値は本家 1.89.0 を `--only Lint/ShadowingOuterLocalVariable` で走らせた実出力から
/// 取った (検出 17 件を確認済み)。
mod lint_shadowing_outer_local_variable {
    use super::*;

    const COP: &str = "Lint/ShadowingOuterLocalVariable";

    const ENABLED: &str = "Lint/ShadowingOuterLocalVariable:\n  Enabled: true\n";

    /// 報告されるのはブロックの引数だけ。本家の `before_declaring_variable` は、表に
    /// 無い名前の宣言でしか呼ばれないので、既にある名前への代入は宣言ではない。
    #[test]
    fn a_block_parameter_that_hides_an_outer_name_is_reported() {
        CopCase::annotated(
            COP,
            r#"
            def m
              x = 1
              [1].each { |x| }
                          ^ Shadowing outer local variable - `x`.
            end
            "#,
        )
        .config(ENABLED)
        .run();
        for source in [
            "x = 1\n[1].each { |x| }\n",
            "def a\n  x = 1\n  [1].each { |y; x| }\nend\n",
            "def d(x)\n  [1].each { |x| }\nend\n",
            "def t\n  x = 1\n  [1].each do |y|\n    [2].each { |x| }\n  end\nend\n",
            "def u\n  x = 1\n  ->(x) { }\nend\n",
            "def f\n  x = 1\n  y = [1].each { |x| }\nend\n",
            "def b\n  x = 1\n  case z\n  when 1\n    [1].each { |x| }\n  end\nend\n",
            "def c\n  x = 1\n  while z\n    [1].each { |x| }\n  end\nend\n",
            // 外側の宣言が条件式の外にあるので、`else` の中でも隠している。
            "def c\n  x = 1\n  unless z\n    1\n  else\n    [1].each { |x| }\n  end\nend\n",
        ] {
            let report = CopCase::new(COP, source, Vec::new())
                .config(ENABLED)
                .without_offense_check()
                .inspect();
            assert_eq!(report.offenses.len(), 1, "{source:?}");
        }
    }

    /// `_` 始まり、`Ractor.new`、外側の宣言そのものの中、そして同じ条件式の別の枝は
    /// 対象外。`def` はスコープの探索を打ち切る。
    #[test]
    fn what_the_cop_leaves_alone() {
        for source in [
            "def n\n  [1].each { |x| }\n  x = 1\nend\n",
            "def o\n  _x = 1\n  [1].each { |_x| }\nend\n",
            "def p1\n  x = 1\n  Ractor.new { |x| }\nend\n",
            "def q\n  x = [1].map { |x| x }\nend\n",
            "def r\n  if a\n    x = 1\n  else\n    [1].each { |x| }\n  end\nend\n",
            "def b\n  if z\n    x = 1\n  elsif w\n    [1].each { |x| }\n  end\nend\n",
            "def s\n  x = 1\n  def inner\n    [1].each { |x| }\n  end\nend\n",
            "class Foo\n  x = 1\n  def h\n    [1].each { |x| }\n  end\nend\n",
        ] {
            CopCase::new(COP, source, Vec::new()).config(ENABLED).run();
        }
    }

    /// 多重代入の右側に書いたブロックは何も隠していない。上流は値を先に読むので、
    /// そのときまだ左側の名前は存在しない。文法は代入先を独立したリストに集めるため、
    /// 宣言のノードがブロックを含まなくなる。
    #[test]
    fn a_block_on_the_right_of_a_multiple_assignment_shadows_nothing() {
        expect_no_offenses(
            COP,
            "def m\n  a, b = f do |a, b|\n    [a, b]\n  end\n  [a, b]\nend\n",
        );
    }
}

/// `Layout/HeredocArgumentClosingParenthesis` (既定では無効)。
///
/// 期待値は本家 1.89.0 を同じソースで走らせた実出力から取った (検出も `-A` もバイト一致を
/// 確認済み)。`-A` は本家と同じく安定するまで繰り返すので、入れ子の呼び出しは 2 周かけて
/// 内側から順に閉じ括弧が上がっていく。
mod layout_heredoc_argument_closing_parenthesis {
    use super::*;

    const COP: &str = "Layout/HeredocArgumentClosingParenthesis";

    fn case(source: &str) -> CopCase {
        CopCase::new(COP, source.to_owned(), Vec::new())
            .config(&format!("{COP}:\n  Enabled: true\n"))
    }

    fn correction(source: &str, corrected: &str) {
        case(source)
            .without_offense_check()
            .corrected(corrected)
            .run();
    }

    /// 報告するのは閉じ括弧 1 文字。
    #[test]
    fn the_offense_is_the_closing_parenthesis_itself() {
        CopCase::new(
            COP,
            "foo(<<~SQL\n  text\nSQL\n)\n".to_owned(),
            vec![Annotation::new(
                4,
                1,
                1,
                "Put the closing parenthesis for a method call with a HEREDOC parameter on the \
                 same line as the HEREDOC opening.",
            )],
        )
        .config(&format!("{COP}:\n  Enabled: true\n"))
        .locations(&[(4, 1, 4, 1)])
        .lengths(&[1])
        .run();
    }

    /// 閉じ括弧だけの行はまるごと消え、括弧はヒアドキュメントの開始の後ろに移る。
    #[test]
    fn the_parenthesis_moves_up_to_the_heredoc_opening() {
        correction("foo(<<~SQL\n  text\nSQL\n)\n", "foo(<<~SQL)\n  text\nSQL\n");
        // 引数の直後に書かれていた読点は括弧と一緒に消える。
        correction(
            "foo(<<~SQL,\n  text\nSQL\n)\n",
            "foo(<<~SQL)\n  text\nSQL\n",
        );
        correction(
            "foo(<<~SQL, 123\n  text\nSQL\n)\n",
            "foo(<<~SQL, 123)\n  text\nSQL\n",
        );
        // `<<~SQL.strip` は send だが、レシーバのヒアドキュメントが行をまたぐので対象。
        correction(
            "foo(<<~SQL.strip\n  text\nSQL\n)\n",
            "foo(<<~SQL.strip)\n  text\nSQL\n",
        );
        // 波括弧の無い hash の値にあるヒアドキュメントも見つける。
        correction(
            "foo(key: <<~SQL\n  text\nSQL\n)\n",
            "foo(key: <<~SQL)\n  text\nSQL\n",
        );
    }

    /// 入れ子は内側から 1 周ずつ上がる。閉じ括弧だけの行ではないので、消えるのは括弧 1 文字。
    #[test]
    fn nested_calls_close_one_round_at_a_time() {
        correction(
            "foo(bar(<<~SQL\n  text\nSQL\n))\n",
            "foo(bar(<<~SQL))\n  text\nSQL\n",
        );
        correction(
            "array = [foo(<<~SQL\n  text\nSQL\n)]\n",
            "array = [foo(<<~SQL)\n  text\nSQL\n]\n",
        );
    }

    /// 括弧の外にあった読点は、括弧と一緒に引数の後ろへ移る。
    #[test]
    fn a_trailing_comma_written_after_the_parenthesis_moves_with_it() {
        correction(
            "[foo(<<~SQL\n  text\nSQL\n), 1]\n",
            "[foo(<<~SQL),\n  text\nSQL\n 1]\n",
        );
        correction(
            "baz(foo(<<~SQL\n  text\nSQL\n), [1])\n",
            "baz(foo(<<~SQL),\n  text\nSQL\n [1])\n",
        );
        // 外側も呼び出しで、その閉じ括弧が最後の引数の直後に来る形 (`baz(foo(...), 1)`) は、
        // 本家でも 2 周目が `baz` の閉じ括弧を報告して何も変えないため
        // `Infinite loop detected` で終わる。ここでも同じ結果になるので correction として
        // 書けない。
    }

    /// `end` で閉じるものの中に書かれた呼び出し、括弧を書いていない呼び出し、
    /// すでに開始行で閉じているものは黙る。
    #[test]
    fn what_the_cop_leaves_alone() {
        for source in [
            "def m\n  foo(<<~SQL\n    text\n  SQL\n  )\nend\n",
            "class C\n  foo(<<~SQL\n    text\n  SQL\n  )\nend\n",
            "foo(<<~SQL)\n  text\nSQL\n",
            "foo <<~SQL\n  text\nSQL\n",
            // ヒアドキュメントの終端と閉じ括弧の間に引数が残っている。
            "foo(<<~SQL,\n  text\nSQL\n  bar)\n",
            "foo(<<~SQL, bar(\n  text\nSQL\n  1\n))\n",
            // 最後の引数が閉じた直後に並んでいる閉じ括弧。
            "foo(bar(<<~X), [\n  t\nX\n  1\n])\n",
            "foo(bar(<<~X), baz(\n  t\nX\n  1\n))\n",
        ] {
            case(source).run();
        }
    }
}

/// `Layout/ClassStructure` (既定無効) — 期待値は本家 1.89.0 の実測。
mod layout_class_structure {
    use super::*;

    const COP: &str = "Layout/ClassStructure";
    const ON: &str = "Layout/ClassStructure:\n  Enabled: true\n";

    /// `ExpectedOrder` の並びに反した要素を報告する。既定は module_inclusion →
    /// constants → public_class_methods → initializer → public_methods →
    /// protected_methods → private_class_methods → private_methods。
    #[test]
    fn an_element_out_of_the_expected_order_is_reported() {
        CopCase::annotated(
            COP,
            r#"
            class A
              include Bar
              CONST = 1
              def self.klass; end
              def initialize; end
              def pub; end
              protected
              def prot; end
              private
              def priv; end
            end
            class B
              def pub; end
              include Bar
              ^^^^^^^^^^^ `module_inclusion` is supposed to appear before `public_methods`.
            end
            class C
              CONST = 1
              include Bar
              ^^^^^^^^^^^ `module_inclusion` is supposed to appear before `constants`.
            end
            class D
              def initialize; end
              CONST = 1
              ^^^^^^^^^ `constants` is supposed to appear before `initializer`.
            end
            "#,
        )
        .config(ON)
        .run();
    }

    /// 可視性は上に書いた裸の修飾子で決まる。`private def foo` も `private` 扱い。
    /// `private :a, :b` のように名前を複数渡した修飾子は本家のパターンに合わないので
    /// どのメソッドも private にしない。
    #[test]
    fn visibility_follows_the_modifier_above() {
        CopCase::annotated(
            COP,
            r#"
            class E
              private
              def priv; end
              public
              def pub; end
              ^^^^^^^^^^^^ `public_methods` is supposed to appear before `private_methods`.
            end
            class F
              private def priv; end
              def pub; end
              ^^^^^^^^^^^^ `public_methods` is supposed to appear before `private_methods`.
            end
            class G
              def a; end
              def b; end
              private :a, :b
            end
            "#,
        )
        .config(ON)
        .run();
    }

    /// `private_constant` で伏せた定数は並びから外れる。補正は 1 つ前の別分類の
    /// 兄弟の上へ、コメントごと動かす。
    #[test]
    fn a_private_constant_is_left_out_of_the_order() {
        CopCase::new(
            COP,
            "class H\n  PRIVATE_CONST = 1\n  private_constant :PRIVATE_CONST\n  include Bar\nend\n",
            Vec::new(),
        )
        .config(ON)
        .run();
        CopCase::annotated(
            COP,
            r#"
            class I
              extend Foo
              # a comment
              def pub; end
              include Bar
              ^^^^^^^^^^^ `module_inclusion` is supposed to appear before `public_methods`.
            end
            "#,
        )
        .config(ON)
        .corrected(
            r#"
            class I
              extend Foo
              include Bar
              # a comment
              def pub; end
            end
            "#,
        )
        .run();
    }

    /// `module` の本体は見ない (`on_class` と `on_sclass` だけ)。
    #[test]
    fn a_module_body_is_not_checked() {
        CopCase::new(
            COP,
            "module M\n  def pub; end\n  include Bar\nend\n",
            Vec::new(),
        )
        .config(ON)
        .run();
        CopCase::annotated(
            COP,
            r#"
            class << self
              def pub; end
              include Bar
              ^^^^^^^^^^^ `module_inclusion` is supposed to appear before `public_methods`.
            end
            "#,
        )
        .config(ON)
        .run();
    }

    /// 定数が呼び出しの結果なら (凍らせたリテラルを除いて) 動的なので動かせない。
    /// リテラルの中のコメントやヒアドキュメントは本家の木には無いので数に入れない。
    #[test]
    fn a_dynamic_constant_is_reported_without_a_correction() {
        CopCase::annotated(
            COP,
            r#"
            class J
              def pub; end
              INSTANCE = create
              ^^^^^^^^^^^^^^^^^ `constants` is supposed to appear before `public_methods`.
            end
            "#,
        )
        .config(ON)
        .correctable(false)
        .run();
        CopCase::annotated(
            COP,
            r#"
            class K
              def pub; end
              FROZEN = %i[a b].freeze
              ^^^^^^^^^^^^^^^^^^^^^^^ `constants` is supposed to appear before `public_methods`.
            end
            "#,
        )
        .config(ON)
        .correctable(true)
        .without_offense_check()
        .run();
    }
}

/// `Style/InvertibleUnlessCondition` (既定無効)。
///
/// 期待値は本家 1.89.0 を `--only Style/InvertibleUnlessCondition` で走らせた実出力から
/// 取った (検出 20 件・`-A` の結果ともバイト一致を確認済み)。
mod style_invertible_unless_condition {
    use super::*;

    const COP: &str = "Style/InvertibleUnlessCondition";

    fn correction(source: &str, corrected: &str) {
        CopCase::new(COP, source.to_owned(), Vec::new())
            .without_offense_check()
            .corrected(corrected)
            .run();
    }

    /// 位置は `unless` 全体。メッセージには反転後と元の条件が入る。
    #[test]
    fn an_invertible_condition_is_reported() {
        expect_offense(
            COP,
            r"
            a unless x != y
            ^^^^^^^^^^^^^^^ Prefer `if x == y` over `unless x != y`.
            ",
        );
        correction("a unless x != y\n", "a if x == y\n");
        correction("unless x.zero?\n  a\nend\n", "if x.nonzero?\n  a\nend\n");
        correction("unless !x\n  a\nend\n", "if x\n  a\nend\n");
        correction("unless x > y\n  a\nend\n", "if x <= y\n  a\nend\n");
        correction("unless x.any?\n  a\nend\n", "if x.none?\n  a\nend\n");
        correction("unless (x != y)\n  a\nend\n", "if (x == y)\n  a\nend\n");
    }

    /// 論理演算は演算子ごと反転し、`||` の中の `&&` は括弧が付く。
    #[test]
    fn a_logical_condition_inverts_both_sides() {
        correction(
            "unless x != y && z.zero?\n  a\nend\n",
            "if x == y || z.nonzero?\n  a\nend\n",
        );
        correction(
            "unless x != y || z.zero?\n  a\nend\n",
            "if x == y && z.nonzero?\n  a\nend\n",
        );
        correction(
            "unless (a != b && c != d) || e.zero?\n  a\nend\n",
            "if (a == b || c == d) && e.nonzero?\n  a\nend\n",
        );
    }

    /// `x < Bar` は継承の宣言に見えるので触らない。全部大文字の定数なら比較として扱う。
    #[test]
    fn an_inheritance_check_is_left_alone() {
        expect_no_offenses(COP, "unless x < Foo\n  a\nend\n");
        correction("unless x < CONST\n  a\nend\n", "if x >= CONST\n  a\nend\n");
        correction(
            "unless x < Foo::CONST\n  a\nend\n",
            "if x >= Foo::CONST\n  a\nend\n",
        );
    }

    /// ブロック付きの呼び出しは上流では `block` ノードで `send` ではない。
    /// `InverseMethods` に無いメソッドも対象外。
    #[test]
    fn what_the_cop_leaves_alone() {
        for source in [
            "unless x.any? { |y| y }\n  a\nend\n",
            "unless x.foo\n  a\nend\n",
            "unless x.include?(y)\n  a\nend\n",
            "unless x.eql? y\n  a\nend\n",
            "unless a && b || c\n  a\nend\n",
        ] {
            expect_no_offenses(COP, source);
        }
    }

    /// `&.` で書いた呼び出しは上流では `csend` で、`send` の枝に入らない。
    #[test]
    fn a_call_written_with_safe_navigation_is_left_alone() {
        expect_no_offenses(COP, "return false unless arguments&.any?\n");
    }

    /// 引数付きの呼び出しは括弧の有無をそのまま保つ。
    #[test]
    fn the_argument_spelling_is_kept() {
        correction(
            "unless x.any?(Integer)\n  a\nend\n",
            "if x.none?(Integer)\n  a\nend\n",
        );
    }
}

/// `Style/MultilineMethodSignature` (既定無効)。
///
/// 期待値は本家 1.89.0 を `--only Style/MultilineMethodSignature` で走らせた実出力から
/// 取った (検出 9 件・`-A` の結果ともバイト一致を確認済み)。
mod style_multiline_method_signature {
    use super::*;

    const COP: &str = "Style/MultilineMethodSignature";

    fn correction(source: &str, corrected: &str) {
        CopCase::new(COP, source.to_owned(), Vec::new())
            .without_offense_check()
            .corrected(corrected)
            .run();
    }

    /// 位置は定義全体。引数が 1 行に畳まれる。
    #[test]
    fn a_signature_spread_over_lines_is_folded() {
        CopCase::annotated(COP, "def foo(a,\n        b)\nend\n")
            .id("multiline")
            .without_offense_check()
            .locations(&[(1, 1, 3, 3)])
            .lengths(&[25])
            .run();
        correction("def foo(a,\n        b)\nend\n", "def foo(a, b)\nend\n");
        correction(
            "def self.baz(a,\n             b)\nend\n",
            "def self.baz(a, b)\nend\n",
        );
        correction(
            "class C\n  def m(a,\n        b)\n  end\nend\n",
            "class C\n  def m(a, b)\n  end\nend\n",
        );
    }

    /// 閉じ括弧だけの行は引数と一緒に運ばれ、その行ごと落ちる。
    #[test]
    fn a_closing_paren_on_its_own_line_travels_with_the_arguments() {
        correction(
            "def bar(a,\n        b\n       )\nend\n",
            "def bar(a, b)\nend\n",
        );
        correction("def qux(\n  a,\n  b\n)\nend\n", "def qux(a, b)\nend\n");
    }

    /// 1 行の定義、引数の無い定義、括弧の無い定義は触らない。
    #[test]
    fn what_the_cop_leaves_alone() {
        for source in [
            "def one(a, b)\nend\n",
            "def noargs\nend\n",
            "def noparens a,\n             b\nend\n",
        ] {
            expect_no_offenses(COP, source);
        }
    }

    /// 畳むと `Layout/LineLength` の `Max` を超えるものは触らない。あの cop を切ると
    /// 上限が無くなるので報告される。
    #[test]
    fn a_correction_that_would_be_too_long_is_skipped() {
        let source = "def long_one(aaaaaaaaaaaaaaaaaaaaaaaaaaaaaaa,\n             bbbbbbbbbbbbbbbbbbbbbbbbbbbbbbb,\n             ccccccccccccccccccccccccccccccc,\n             ddddddddddddddddddddddddddddddd)\nend\n";
        expect_no_offenses(COP, source);
        CopCase::new(COP, source.to_owned(), Vec::new())
            .config("Layout/LineLength:\n  Enabled: false\n")
            .without_offense_check()
            .corrected("def long_one(aaaaaaaaaaaaaaaaaaaaaaaaaaaaaaa, bbbbbbbbbbbbbbbbbbbbbbbbbbbbbbb, ccccccccccccccccccccccccccccccc, ddddddddddddddddddddddddddddddd)\nend\n")
            .run();
    }

    /// キーワード引数・splat・既定値付きも同じ。
    #[test]
    fn every_parameter_kind_folds() {
        correction("def kw(a:,\n       b: 1)\nend\n", "def kw(a:, b: 1)\nend\n");
        correction(
            "def splat(*a,\n          **b)\nend\n",
            "def splat(*a, **b)\nend\n",
        );
        correction(
            "def defaults(a = 1,\n             b = 2)\nend\n",
            "def defaults(a = 1, b = 2)\nend\n",
        );
    }
}

/// `Style/SelectByRegexp` / `Style/SelectByKind` / `Style/SelectByRange`。
///
/// 期待値は本家 1.89.0 を同じソースで走らせた実出力から取った (検出も `-A` もバイト一致を
/// 確認済み)。
mod style_select_by {
    use super::*;

    fn correction(cop: &str, source: &str, corrected: &str) {
        CopCase::new(cop, source.to_owned(), Vec::new())
            .without_offense_check()
            .corrected(corrected)
            .run();
    }

    /// `select` は `grep`、`reject` は `grep_v`。否定が挟まると入れ替わる。
    #[test]
    fn a_regexp_match_becomes_grep() {
        correction(
            "Style/SelectByRegexp",
            "array.select { |x| x.match?(/re/) }\n",
            "array.grep(/re/)\n",
        );
        correction(
            "Style/SelectByRegexp",
            "array.reject { |x| x =~ /re/ }\n",
            "array.grep_v(/re/)\n",
        );
        // `/re/ =~ x` は名前付きキャプチャを束縛する別のノードだが、正規表現は左側にある。
        correction(
            "Style/SelectByRegexp",
            "array.select { |x| /re/ =~ x }\n",
            "array.grep(/re/)\n",
        );
        correction(
            "Style/SelectByRegexp",
            "array.select { |x| x !~ /re/ }\n",
            "array.grep_v(/re/)\n",
        );
        correction(
            "Style/SelectByRegexp",
            "array.select { |x| !x.match?(/re/) }\n",
            "array.grep_v(/re/)\n",
        );
        correction(
            "Style/SelectByRegexp",
            "array.select { _1.match?(/re/) }\n",
            "array.grep(/re/)\n",
        );
    }

    /// `is_a?` は `grep`、`between?` と `cover?` も同じ形。
    #[test]
    fn a_kind_or_range_check_becomes_grep() {
        correction(
            "Style/SelectByKind",
            "array.select { |x| x.is_a?(Foo) }\n",
            "array.grep(Foo)\n",
        );
        correction(
            "Style/SelectByKind",
            "array.reject { |x| x.kind_of?(Foo) }\n",
            "array.grep_v(Foo)\n",
        );
        correction(
            "Style/SelectByRange",
            "array.select { |x| x.between?(1, 10) }\n",
            "array.grep(1..10)\n",
        );
        correction(
            "Style/SelectByRange",
            "array.select { |x| (1..10).cover?(x) }\n",
            "array.grep(1..10)\n",
        );
        // `find` / `detect` は最初の 1 件なので `.first` が付く。
        correction(
            "Style/SelectByRange",
            "array.find { |x| x.between?(1, 10) }\n",
            "array.grep(1..10).first\n",
        );
    }

    /// hash を返すレシーバ、要素を読まないブロック、文が 2 つ以上のブロックは黙る。
    #[test]
    fn what_the_select_by_cops_leave_alone() {
        for (cop, source) in [
            (
                "Style/SelectByRegexp",
                "array.select { |x| y.match?(/re/) }\n",
            ),
            (
                "Style/SelectByRegexp",
                "array.select { |x| match?(/re/) }\n",
            ),
            (
                "Style/SelectByRegexp",
                "array.select { |x| x.match?(/re/) && x.size > 1 }\n",
            ),
            (
                "Style/SelectByRegexp",
                "ENV.select { |x| x.match?(/re/) }\n",
            ),
            (
                "Style/SelectByRegexp",
                "array.to_h.select { |x| x.match?(/re/) }\n",
            ),
            ("Style/SelectByKind", "array.select { |x| y.is_a?(Foo) }\n"),
            // 括弧で包んだ否定は `is_a?` 側のパターンには無い。
            (
                "Style/SelectByKind",
                "array.select { |x| !(x.is_a?(Foo)) }\n",
            ),
            (
                "Style/SelectByRange",
                "array.select { |x| (1..10).cover?(y) }\n",
            ),
        ] {
            CopCase::new(cop, source.to_owned(), Vec::new()).run();
        }
    }
}

/// `Style/TallyMethod` / `Style/SingleLineDoEndBlock` / `Style/RequireOrder`。
///
/// 期待値は本家 1.89.0 を同じソースで走らせた実出力から取った (検出も `-A` もバイト一致を
/// 確認済み)。
mod style_tally_and_layout_of_statements {
    use super::*;

    fn correction(cop: &str, source: &str, corrected: &str) {
        CopCase::new(cop, source.to_owned(), Vec::new())
            .without_offense_check()
            .corrected(corrected)
            .run();
    }

    /// 数え上げの 2 つの書き方はどちらも `tally`。
    #[test]
    fn counting_by_hand_becomes_tally() {
        correction(
            "Style/TallyMethod",
            "array.each_with_object(Hash.new(0)) { |el, hash| hash[el] += 1 }\n",
            "array.tally\n",
        );
        correction(
            "Style/TallyMethod",
            "array.each_with_object(Hash.new(0)) { _2[_1] += 1 }\n",
            "array.tally\n",
        );
        correction(
            "Style/TallyMethod",
            "array.group_by(&:itself).transform_values(&:count)\n",
            "array.tally\n",
        );
        correction(
            "Style/TallyMethod",
            "array.group_by { |x| x }.transform_values { |v| v.size }\n",
            "array.tally\n",
        );
        // 既定値が 0 でない hash、`itself` でない group_by、数えない transform_values。
        for source in [
            "array.each_with_object(Hash.new(1)) { |el, hash| hash[el] += 1 }\n",
            "array.each_with_object({}) { |el, hash| hash[el] += 1 }\n",
            "array.group_by(&:foo).transform_values(&:count)\n",
            "array.group_by(&:itself).transform_values(&:to_a)\n",
        ] {
            CopCase::new("Style/TallyMethod", source.to_owned(), Vec::new()).run();
        }
    }

    /// 1 行の `do ... end` は改行する。ヒアドキュメントがあると `end` はその後ろへ回る。
    #[test]
    fn a_one_line_do_end_block_is_broken_up() {
        correction(
            "Style/SingleLineDoEndBlock",
            "foo do bar end\n",
            "foo do\n bar \nend\n",
        );
        correction(
            "Style/SingleLineDoEndBlock",
            "foo do |x| bar(x) end\n",
            "foo do |x|\n bar(x) \nend\n",
        );
        correction(
            "Style/SingleLineDoEndBlock",
            "x = -> do bar end\n",
            "x = -> do\n bar \nend\n",
        );
        correction(
            "Style/SingleLineDoEndBlock",
            "foo do bar(<<~TEXT) end\n  hello\nTEXT\n",
            "foo do\n bar(<<~TEXT) \n  hello\nTEXT\nend\n",
        );
        CopCase::new(
            "Style/SingleLineDoEndBlock",
            "foo { bar }\n".to_owned(),
            Vec::new(),
        )
        .run();
    }

    /// 連続した `require` は辞書順。直上の行コメントも一緒に動く。
    #[test]
    fn requires_are_sorted() {
        correction(
            "Style/RequireOrder",
            "require 'b'\nrequire 'a'\n",
            "require 'a'\nrequire 'b'\n",
        );
        correction(
            "Style/RequireOrder",
            "require_relative 'b'\nrequire_relative 'a'\n",
            "require_relative 'a'\nrequire_relative 'b'\n",
        );
        correction(
            "Style/RequireOrder",
            "# comment for d\nrequire 'd'\nrequire 'a2'\n",
            "require 'a2'\n# comment for d\nrequire 'd'\n",
        );
        correction(
            "Style/RequireOrder",
            "require 'x' if cond\nrequire 'w' if cond\n",
            "require 'w' if cond\nrequire 'x' if cond\n",
        );
        // 空行で区切られた別の塊、種類の違う require、間に挟まった別の文は数えない。
        for source in [
            "require 'b'\n\nrequire 'a'\n",
            "require 'm'\nrequire_relative 'l'\nrequire 'k'\n",
            "require 'q'\nfoo\nrequire 'p'\n",
        ] {
            CopCase::new("Style/RequireOrder", source.to_owned(), Vec::new()).run();
        }
    }
}

/// `Style/SuperArguments` / `Style/RedundantDoubleSplatHashBraces`。
///
/// 期待値は本家 1.89.0 を同じソースで走らせた実出力から取った (検出も `-A` もバイト一致を
/// 確認済み)。
mod style_super_and_double_splat {
    use super::*;

    fn correction(cop: &str, source: &str, corrected: &str) {
        CopCase::new(cop, source.to_owned(), Vec::new())
            .without_offense_check()
            .corrected(corrected)
            .run();
    }

    /// 引数がそのまま渡っているだけの `super(...)` は裸の `super` にする。
    #[test]
    fn super_that_forwards_everything_loses_its_arguments() {
        correction(
            "Style/SuperArguments",
            "class Foo\n  def m(a, b)\n    super(a, b)\n  end\nend\n",
            "class Foo\n  def m(a, b)\n    super\n  end\nend\n",
        );
        correction(
            "Style/SuperArguments",
            "class Foo\n  def m(*args, **kw, &blk)\n    super(*args, **kw, &blk)\n  end\nend\n",
            "class Foo\n  def m(*args, **kw, &blk)\n    super\n  end\nend\n",
        );
        correction(
            "Style/SuperArguments",
            "class Foo\n  def m(x:, y: 2)\n    super(x: x, y: y)\n  end\nend\n",
            "class Foo\n  def m(x:, y: 2)\n    super\n  end\nend\n",
        );
        // 既定値付きの引数が続くと文法が 1 つのノードへ畳むので、ほどいてから数える。
        correction(
            "Style/SuperArguments",
            "class Foo\n  def m(a = nil, b = nil, c = nil)\n    super(a, b, c)\n  end\nend\n",
            "class Foo\n  def m(a = nil, b = nil, c = nil)\n    super\n  end\nend\n",
        );
        // ブロックを `super` 自身に書いた形は、ブロック引数が渡っているのと同じ。
        correction(
            "Style/SuperArguments",
            "class Foo\n  def m(a, &blk)\n    super(a) { blk.call }\n  end\nend\n",
            "class Foo\n  def m(a, &blk)\n    super { blk.call }\n  end\nend\n",
        );
    }

    /// 並びが違う、数が違う、`=>` で書いた、他人のブロックの中、後から代入された、は黙る。
    #[test]
    fn what_the_super_cop_leaves_alone() {
        for source in [
            "class Foo\n  def m(a, b)\n    super(b, a)\n  end\nend\n",
            "class Foo\n  def m(a)\n    super(a, 1)\n  end\nend\n",
            "class Foo\n  def m(a, b: 1)\n    super(a, :b => b)\n  end\nend\n",
            "class Foo\n  def m(a)\n    foo { super(a) }\n  end\nend\n",
            "class Foo\n  def m(a, &blk)\n    blk = other\n    super(a, &blk)\n  end\nend\n",
            // 引数を書かない `super` は別のノードで、この cop は見ない。
            "class Foo\n  def m\n    super do |x|\n      x\n    end\n  end\nend\n",
        ] {
            CopCase::new("Style/SuperArguments", source.to_owned(), Vec::new()).run();
        }
    }

    /// `**{ ... }` は波括弧ごと消える。後ろに続く `merge` も引数へ畳まれる。
    #[test]
    fn a_double_splatted_hash_literal_loses_its_braces() {
        correction(
            "Style/RedundantDoubleSplatHashBraces",
            "do_something(**{foo: bar, baz: qux})\n",
            "do_something(foo: bar, baz: qux)\n",
        );
        correction(
            "Style/RedundantDoubleSplatHashBraces",
            "do_something(**{foo: bar}.merge(baz: qux))\n",
            "do_something(foo: bar, baz: qux)\n",
        );
        correction(
            "Style/RedundantDoubleSplatHashBraces",
            "do_something(**{foo: bar}.merge(baz: qux).merge(quux: corge))\n",
            "do_something(foo: bar, baz: qux, quux: corge)\n",
        );
        // `=>` で書いた組、空の hash、hash でないもの、`merge` 以外の呼び出しは黙る。
        for source in [
            "do_something(**{'foo' => bar})\n",
            "do_something(**{})\n",
            "do_something(**kwargs)\n",
            "do_something(**h.merge(foo: bar))\n",
            "do_something(**{foo: bar}.compact)\n",
        ] {
            CopCase::new(
                "Style/RedundantDoubleSplatHashBraces",
                source.to_owned(),
                Vec::new(),
            )
            .run();
        }
    }
}

mod lint_unescaped_bracket_in_regexp {
    use super::*;

    const COP: &str = "Lint/UnescapedBracketInRegexp";

    /// 位置は本体の先頭から数えた文字数。`/.../` でも `%r{...}` でも同じ数え方になる。
    #[test]
    fn a_bare_bracket_in_a_regexp_literal_is_reported() {
        expect_offense(
            COP,
            r"
            /abc]123/
                ^ Regular expression has `]` without escape.
            ",
        );
        expect_correction(COP, "/abc]123/\n", "/abc\\]123/\n");
        expect_offense(
            COP,
            r"
            %r{abc]123}
                  ^ Regular expression has `]` without escape.
            ",
        );
        expect_correction(COP, "%r{abc]123}\n", "%r{abc\\]123}\n");
    }

    /// 補間は同じ幅の空白に置き換えてから解析するので、後ろの位置がずれない。
    #[test]
    fn an_interpolation_does_not_shift_the_positions_after_it() {
        expect_offense(
            COP,
            r#"
            /x#{y}]z/
                  ^ Regular expression has `]` without escape.
            "#,
        );
        expect_correction(COP, "/x#{y}]z/\n", "/x#{y}\\]z/\n");
    }

    /// `Regexp.new` / `Regexp.compile` の文字列引数も見る。位置は引用符の次から数える。
    #[test]
    fn the_string_a_regexp_is_built_from_is_read_too() {
        expect_offense(
            COP,
            r"
            Regexp.new('abc]123')
                           ^ Regular expression has `]` without escape.
            ",
        );
        expect_correction(COP, "Regexp.new('abc]123')\n", "Regexp.new('abc\\]123')\n");
        expect_offense(
            COP,
            r"
            ::Regexp.compile('x]y')
                               ^ Regular expression has `]` without escape.
            ",
        );
    }

    /// `[]` と `[^]` は空の文字クラスで、その直後の `]` はクラスを閉じている。
    /// 先頭の `]` も Ruby は警告しない。
    #[test]
    fn a_bracket_that_closes_something_is_left_alone() {
        for source in [
            "/[^]]/\n",
            "/]abc/\n",
            "/a\\]b/\n",
            // 補間を含む `Regexp.new` は本家が丸ごと見送る。
            "Regexp.new(\"abc]#{x}\")\n",
            // 隣接する文字列リテラルは本家の `dstr`。
            "Regexp.new(\"a\" \"b]c\")\n",
        ] {
            expect_no_offenses(COP, source);
        }
    }

    /// 補間の中身が多バイトでも、位置は文字数で数える。
    #[test]
    fn a_multibyte_interpolation_does_not_shift_the_position_after_it() {
        expect_offense(
            COP,
            r#"
            /あ#{い}]z/
                  ^ Regular expression has `]` without escape.
            "#,
        );
        expect_correction(COP, "/あ#{い}]z/\n", "/あ#{い}\\]z/\n");
    }

    /// 空クラスの次の `]` を 1 つ見送った後は、同じリテラルの中の次の `]` を報告する。
    #[test]
    fn only_the_first_bracket_after_an_empty_class_is_skipped() {
        expect_offense(
            COP,
            r"
            /[^]]]/
                 ^ Regular expression has `]` without escape.
            ",
        );
        expect_correction(COP, "/[^]]]/\n", "/[^]]\\]/\n");
    }
}

mod lint_duplicate_regexp_character_class_element {
    use super::*;

    const COP: &str = "Lint/DuplicateRegexpCharacterClassElement";

    /// 同じ文字クラスに 2 度書かれた要素。2 つ目を消す。
    #[test]
    fn a_repeated_member_is_reported() {
        expect_offense(
            COP,
            r"
            /[xyx]/
                ^ Duplicate element inside regexp character class
            ",
        );
        expect_correction(COP, "/[xyx]/\n", "/[xy]/\n");
        // 範囲もエスケープも POSIX ブラケットも要素 1 つとして数える。
        expect_offense(
            COP,
            r"
            /[0-9x0-9]/
                  ^^^ Duplicate element inside regexp character class
            ",
        );
        expect_correction(COP, "/[0-9x0-9]/\n", "/[0-9x]/\n");
        expect_correction(COP, "/[\\d\\d]/\n", "/[\\d]/\n");
        expect_correction(COP, "/[[:alpha:][:alpha:]]/\n", "/[[:alpha:]]/\n");
    }

    /// 補間は同じ幅の空白に置き換わるので、2 文字目以降が重複に見える。
    /// その空白は補間の範囲と重なるので数えない。
    #[test]
    fn the_spaces_an_interpolation_was_blanked_to_are_not_members() {
        expect_offense(
            COP,
            r#"
            /[a-z#{x}a-z]/
                     ^^^ Duplicate element inside regexp character class
            "#,
        );
        expect_correction(COP, "/[a-z#{x}a-z]/\n", "/[a-z#{x}]/\n");
    }

    /// 補間の中身が多バイトでも、位置は文字数で数えるので後ろがずれない。
    #[test]
    fn a_multibyte_interpolation_does_not_shift_the_members_after_it() {
        expect_offense(
            COP,
            r#"
            /[x#{い}yy]/
                    ^ Duplicate element inside regexp character class
            "#,
        );
        expect_correction(COP, "/[x#{い}yy]/\n", "/[x#{い}y]/\n");
    }

    /// 拡張モードでも文字クラスの中の空白は文字のまま。
    #[test]
    fn a_blank_inside_a_class_counts_even_in_extended_mode() {
        expect_offense(
            COP,
            r"
            /[a a]/x
                ^ Duplicate element inside regexp character class
            ",
        );
        expect_correction(COP, "/[a a]/x\n", "/[a ]/x\n");
    }

    /// `&&` の左右は別の集合なので、またいだ重複は数えない。
    #[test]
    fn what_the_cop_leaves_alone() {
        for source in ["/[xy]/\n", "/[0-9x]/\n", "/[a&&a]/\n"] {
            expect_no_offenses(COP, source);
        }
    }
}

mod lint_mixed_case_range {
    use super::*;

    const COP: &str = "Lint/MixedCaseRange";

    const MSG: &str = "Ranges from upper to lower case ASCII letters may include unintended \
                       characters. Instead of `A-z` (which also includes several symbols) \
                       specify each range individually: `A-Za-z` and individually specify any \
                       symbols.";

    /// 文字クラスの中の `A-z`。2 つの範囲に割る。
    #[test]
    fn a_mixed_case_range_in_a_character_class_is_reported() {
        expect_offense(COP, &format!("/[A-z]/\n  ^^^ {MSG}\n"));
        expect_correction(COP, "/[A-z]/\n", "/[A-Za-z]/\n");
        expect_correction(COP, "/[^A-z]/\n", "/[^A-Za-z]/\n");
        expect_correction(COP, "/[A-z0-9]/\n", "/[A-Za-z0-9]/\n");
        // 片方だけが 1 文字の範囲になるときは、その 1 文字だけを書く。
        expect_correction(COP, "/[Z-a]/\n", "/[Za]/\n");
    }

    /// `Range` オブジェクトも同じ質問をされるが、2 つには割れないので報告だけ。
    #[test]
    fn a_range_object_is_reported_without_a_correction() {
        expect_offense(COP, &format!("('A'..'z')\n ^^^^^^^^ {MSG}\n"));
        expect_offense(COP, &format!("('A'...'z')\n ^^^^^^^^^ {MSG}\n"));
        expect_offense(COP, &format!("('Z'..'a')\n ^^^^^^^^ {MSG}\n"));
    }

    /// 大小が揃っている範囲、片方が英字でない範囲、端が 1 文字でないもの、
    /// 端がエスケープのものは黙る。
    #[test]
    fn what_the_cop_leaves_alone() {
        for source in [
            "/[A-Za-z]/\n",
            "/[0-9]/\n",
            "/[\\x41-z]/\n",
            "('AA'..'zz')\n",
            "(1..9)\n",
            "('A'..)\n",
            // `!` はどちらの範囲にも入らないので、書き換えようがない。
            "/[!-z]/\n",
        ] {
            expect_no_offenses(COP, source);
        }
    }
}

mod lint_redundant_regexp_quantifiers {
    use super::*;

    const COP: &str = "Lint/RedundantRegexpQuantifiers";

    /// `(?:x+)+` の 2 つの量指定子。内側を書き換えて外側を消す。
    #[test]
    fn a_quantified_group_around_a_quantified_expression_is_reported() {
        expect_offense(
            COP,
            r"
            /(?:x+)+/
                 ^^^ Replace redundant quantifiers `+` and `+` with a single `+`.
            ",
        );
        expect_correction(COP, "/(?:x+)+/\n", "/(?:x+)/\n");
        expect_offense(
            COP,
            r"
            /(?:x+)?/
                 ^^^ Replace redundant quantifiers `+` and `?` with a single `*`.
            ",
        );
        expect_correction(COP, "/(?:x+)?/\n", "/(?:x*)/\n");
        // `{1,}` は `+` と同じ意味なので、短いほうに揃えて書き換える。
        expect_offense(
            COP,
            r"
            /(?:x{1,})+/
                 ^^^^^^ Replace redundant quantifiers `{1,}` and `+` with a single `+`.
            ",
        );
        expect_correction(COP, "/(?:x{1,})+/\n", "/(?:x+)/\n");
    }

    /// 量指定子を 2 つ並べて書いた形も、暗黙のグループが 1 つ挟まっているだけで同じ。
    #[test]
    fn two_quantifiers_written_side_by_side_are_the_same_shape() {
        expect_offense(
            COP,
            r"
            /a+*/
              ^^ Replace redundant quantifiers `+` and `*` with a single `*`.
            ",
        );
        expect_correction(COP, "/a+*/\n", "/a*/\n");
    }

    /// 入れ子のグループは外側から数えて 1 回ずつ、内側は再訪しない。
    #[test]
    fn a_nested_group_is_paired_with_the_outermost_quantifier_only() {
        expect_offense(
            COP,
            r"
            /(?:(?:x+)+)+/
                    ^^^^^ Replace redundant quantifiers `+` and `+` with a single `+`.
                      ^^^ Replace redundant quantifiers `+` and `+` with a single `+`.
            ",
        );
        expect_correction(COP, "/(?:(?:x+)+)+/\n", "/(?:(?:x+))/\n");
    }

    /// 拡張モードの空白と `#` の注釈は、要素が 1 つかどうかの数に入らない。
    #[test]
    fn free_spacing_does_not_change_what_the_group_holds() {
        expect_offense(
            COP,
            r"
            /(?: x+ )+/x
                  ^^^^ Replace redundant quantifiers `+` and `+` with a single `+`.
            ",
        );
        expect_correction(COP, "/(?: x+ )+/x\n", "/(?: x+ )/x\n");
    }

    /// 捕獲グループ、要素が 2 つ以上のグループ、怠惰な量指定子、補間のあるリテラルは黙る。
    #[test]
    fn what_the_cop_leaves_alone() {
        for source in [
            "/(?:x)+/\n",
            "/(?:x+)/\n",
            "/(x+)+/\n",
            "/(?:x+y)+/\n",
            "/(?:x+?)+/\n",
            "/(?:a*#{x})?/x\n",
        ] {
            expect_no_offenses(COP, source);
        }
    }
}

/// `Style/PartitionInsteadOfDoubleSelect` (既定 pending) — 期待値は本家 1.89.0 の実測。
mod style_partition_instead_of_double_select {
    use super::*;

    const COP: &str = "Style/PartitionInsteadOfDoubleSelect";

    /// 位置は 2 つ目の文の全体。メッセージには前の文・後の文の順で selector が入り、
    /// 補正は 1 つ目の文を多重代入に書き換えて 2 つ目の行ごと落とす。
    #[test]
    fn a_select_beside_a_reject_is_reported_on_the_second_statement() {
        expect_offense(
            COP,
            r"
            good = xs.select { |x| x.ok? }
            bad = xs.reject { |x| x.ok? }
            ^^^^^^^^^^^^^^^^^^^^^^^^^^^^^ Use `partition` instead of consecutive `select` and `reject` calls.
            ",
        );
        expect_correction(
            COP,
            "good = xs.select { |x| x.ok? }\nbad = xs.reject { |x| x.ok? }\n",
            "good, bad = xs.partition { |x| x.ok? }\n",
        );
    }

    /// `reject` が先でも同じ。変数の並びは常に `select` 側が先。
    #[test]
    fn the_select_names_the_first_half_whichever_order_it_was_written_in() {
        expect_offense(
            COP,
            r"
            bad = xs.reject { |x| x.ok? }
            good = xs.select { |x| x.ok? }
            ^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^ Use `partition` instead of consecutive `reject` and `select` calls.
            ",
        );
        expect_correction(
            COP,
            "bad = xs.reject { |x| x.ok? }\ngood = xs.select { |x| x.ok? }\n",
            "good, bad = xs.partition { |x| x.ok? }\n",
        );
    }

    /// `filter` と `find_all` も `select` の綴り。メッセージには書かれた綴りが出る。
    #[test]
    fn filter_and_find_all_are_spellings_of_select() {
        expect_offense(
            COP,
            r"
            good = xs.filter { |x| x.ok? }
            bad = xs.reject { |x| x.ok? }
            ^^^^^^^^^^^^^^^^^^^^^^^^^^^^^ Use `partition` instead of consecutive `filter` and `reject` calls.
            ",
        );
        expect_offense(
            COP,
            r"
            good = xs.find_all { |x| x.ok? }
            bad = xs.reject { |x| x.ok? }
            ^^^^^^^^^^^^^^^^^^^^^^^^^^^^^ Use `partition` instead of consecutive `find_all` and `reject` calls.
            ",
        );
    }

    /// `&:sym` は同じことを言うブロックと釣り合う。片方だけがブロックでも同じ。
    #[test]
    fn a_symbol_to_proc_matches_the_block_saying_the_same_thing() {
        expect_correction(
            COP,
            "good = xs.select(&:ok?)\nbad = xs.reject(&:ok?)\n",
            "good, bad = xs.partition(&:ok?)\n",
        );
        expect_correction(
            COP,
            "good = xs.select(&:ok?)\nbad = xs.reject { |x| x.ok? }\n",
            "good, bad = xs.partition(&:ok?)\n",
        );
    }

    /// 同じ selector が 2 つでも、片方の本体がもう片方の否定なら同じ組。
    /// `partition` は真の側を先に返すので、変数の並びは selector で決まる。
    #[test]
    fn the_same_selector_twice_pairs_when_one_body_negates_the_other() {
        expect_offense(
            COP,
            r"
            good = xs.select { |x| x.ok? }
            other = xs.select { |x| !x.ok? }
            ^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^ Use `partition` instead of consecutive `select` and `select` calls.
            ",
        );
        expect_correction(
            COP,
            "good = xs.select { |x| x.ok? }\nother = xs.select { |x| !x.ok? }\n",
            "good, other = xs.partition { |x| x.ok? }\n",
        );
        expect_correction(
            COP,
            "other = xs.reject { |x| !x.ok? }\ngood = xs.reject { |x| x.ok? }\n",
            "other, good = xs.partition { |x| x.ok? }\n",
        );
    }

    /// 番号付き引数のブロックも組になる。ブロックの種類が食い違えば組にならない。
    #[test]
    fn a_numbered_parameter_pairs_only_with_another_one() {
        expect_correction(
            COP,
            "good = xs.select { _1.ok? }\nbad = xs.reject { _1.ok? }\n",
            "good, bad = xs.partition { _1.ok? }\n",
        );
        expect_no_offenses(
            COP,
            "good = xs.select { |x| x.ok? }\nbad = xs.reject { _1.ok? }\n",
        );
    }

    /// 両方が局所変数への代入でなければ報告だけで補正はしない。
    #[test]
    fn a_pair_that_does_not_name_both_halves_is_reported_without_a_correction() {
        CopCase::annotated(
            COP,
            r"
            @good = xs.select { |x| x.ok? }
            @bad = xs.reject { |x| x.ok? }
            ^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^ Use `partition` instead of consecutive `select` and `reject` calls.
            ",
        )
        .correctable(false)
        .run();
        CopCase::annotated(
            COP,
            r"
            xs.select { |x| x.ok? }
            xs.reject { |x| x.ok? }
            ^^^^^^^^^^^^^^^^^^^^^^^ Use `partition` instead of consecutive `select` and `reject` calls.
            ",
        )
        .correctable(false)
        .run();
    }

    /// `begin ... end` に直接並んだ 2 文は本家の木では `kwbegin` の子で、`begin` の
    /// 子ではないので組にならない。`rescue` が付くと中身が `begin` になり報告される。
    #[test]
    fn a_written_begin_end_holds_no_pair_unless_it_rescues() {
        expect_no_offenses(
            COP,
            "begin\n  good = xs.select { |x| x.ok? }\n  bad = xs.reject { |x| x.ok? }\nend\n",
        );
        expect_correction(
            COP,
            "begin\n  good = xs.select { |x| x.ok? }\n  bad = xs.reject { |x| x.ok? }\nrescue\n  nil\nend\n",
            "begin\n  good, bad = xs.partition { |x| x.ok? }\nrescue\n  nil\nend\n",
        );
    }

    /// 1 行に並べた 2 文は本家が補正で自分の書き換えを踏み潰して例外になり、
    /// offense ごと落ちる。
    #[test]
    fn a_pair_written_on_one_line_is_not_reported() {
        expect_no_offenses(
            COP,
            "good = xs.select { |x| x.ok? }; bad = xs.reject { |x| x.ok? }\n",
        );
    }

    /// 組にならないもの。
    #[test]
    fn what_the_cop_leaves_alone() {
        for source in [
            // レシーバが違う。
            "good = xs.select { |x| x.ok? }\nbad = ys.reject { |x| x.ok? }\n",
            // ブロック引数が違う。
            "good = xs.select { |x| x.ok? }\nbad = xs.reject { |y| y.ok? }\n",
            // selector が対象外。
            "good = xs.map { |x| x.ok? }\nbad = xs.map { |x| !x.ok? }\n",
            // 間に別の文がある。
            "good = xs.select { |x| x.ok? }\nputs 1\nbad = xs.reject { |x| x.ok? }\n",
            // ブロックもブロック渡しも無い。
            "good = xs.select\nbad = xs.reject\n",
        ] {
            expect_no_offenses(COP, source);
        }
    }
}

/// `Style/ClassMethodsDefinitions` (既定無効) — 期待値は本家 1.89.0 の実測。
mod style_class_methods_definitions {
    use super::*;

    const COP: &str = "Style/ClassMethodsDefinitions";
    const ON: &str = "Style/ClassMethodsDefinitions:\n  Enabled: true\n";
    const SELF_CLASS: &str =
        "Style/ClassMethodsDefinitions:\n  Enabled: true\n  EnforcedStyle: self_class\n";

    fn correction(source: &str, corrected: &str) {
        CopCase::new(COP, source.to_owned(), Vec::new())
            .config(ON)
            .without_offense_check()
            .corrected(corrected)
            .run();
    }

    /// 位置は `class << self` 全体。補正は公開メソッドを外へ出し、抜け殻は残す。
    #[test]
    fn a_public_method_in_a_singleton_class_is_reported_on_the_class() {
        CopCase::new(
            COP,
            "class SomeClass\n  class << self\n    attr_accessor :class_accessor\n\n    def class_method\n      1\n    end\n  end\nend\n",
            Vec::new(),
        )
        .config(ON)
        .without_offense_check()
        .locations(&[(2, 3, 8, 5)])
        .lengths(&[91])
        .cop_names(&[COP])
        .run();
        correction(
            "class SomeClass\n  class << self\n    attr_accessor :class_accessor\n\n    def class_method\n      1\n    end\n  end\nend\n",
            "class SomeClass\n  class << self\n    attr_accessor :class_accessor\n\n  end\n\n  def self.class_method\n    1\n  end\nend\n",
        );
    }

    /// メソッドしか無い `class << self` は丸ごと消え、最初の定義がその場所に座る。
    #[test]
    fn a_singleton_class_holding_only_methods_goes_away_with_them() {
        correction(
            "class Other\n  class << self\n    def only_method\n      1\n    end\n  end\nend\n",
            "class Other\n  def self.only_method\n    1\n  end\nend\n",
        );
        correction(
            "class Fifth\n  class << self\n    def a; end\n    def b; end\n  end\nend\n",
            "class Fifth\n  def self.a; end\n\n  def self.b; end\nend\n",
        );
    }

    /// 定義の上に書かれたコメントは一緒に動く。間の空行はコメントを切り離さない。
    #[test]
    fn the_comments_written_over_a_definition_travel_with_it() {
        correction(
            "class Third\n  class << self\n    attr_accessor :acc\n\n    # a comment\n    def one\n      1\n    end\n\n    def two\n      2\n    end\n  end\nend\n",
            "class Third\n  class << self\n    attr_accessor :acc\n\n\n  end\n\n  # a comment\n  def self.one\n    1\n  end\n\n  def self.two\n    2\n  end\nend\n",
        );
        correction(
            "class X\n  class << self\n    # comment\n\n    def a; end\n  end\nend\n",
            "class X\n  # comment\n\n  def self.a; end\nend\n",
        );
        // 行末のコメントは、その行のコードのものなので動かない。
        correction(
            "class Z\n  class << self\n    attr_accessor :q\n    foo # trailing\n    def a; end\n  end\nend\n",
            "class Z\n  class << self\n    attr_accessor :q\n    foo # trailing\n  end\n\n  def self.a; end\nend\n",
        );
    }

    /// `class << self` より深く書かれた定義は、その差の分だけ左へ寄る。
    #[test]
    fn a_definition_indented_further_is_moved_back_by_the_difference() {
        correction(
            "class Deep\n  class << self\n      def deep; end\n  end\nend\n",
            "class Deep\n  def self.deep; end\nend\n",
        );
    }

    /// 公開でない定義が 1 つでもあれば報告しない。
    #[test]
    fn a_singleton_class_with_a_hidden_method_is_left_alone() {
        for source in [
            "class Fourth\n  class << self\n    attr_accessor :acc\n\n    private\n\n    def priv; end\n  end\nend\n",
            "class Ninth\n  class << self\n    def a; end\n\n    private :a\n  end\nend\n",
        ] {
            CopCase::new(COP, source.to_owned(), Vec::new())
                .config(ON)
                .run();
        }
    }

    /// 本家の木で `def` でないものは数に入らない。修飾子に渡した定義は `send` の子で、
    /// `def self.` は `defs` なので、どちらも動かす対象にならない。
    #[test]
    fn only_a_plain_def_written_straight_in_the_body_counts() {
        correction(
            "class Tenth\n  class << self\n    private def a; end\n    def b; end\n  end\nend\n",
            "class Tenth\n  class << self\n    private def a; end\n  end\n\n  def self.b; end\nend\n",
        );
        correction(
            "class Eleventh\n  class << self\n    def self.weird; end\n    def normal; end\n  end\nend\n",
            "class Eleventh\n  class << self\n    def self.weird; end\n  end\n\n  def self.normal; end\nend\n",
        );
    }

    /// 触らないもの。
    #[test]
    fn what_the_cop_leaves_alone() {
        for source in [
            // `class << obj` は自分の特異クラスではない。
            "class Eighth\n  class << obj\n    def x; end\n  end\nend\n",
            // 定義が無い。
            "class Sixth\n  class << self\n  end\nend\n",
            "class Seventh\n  class << self\n    attr_accessor :x\n  end\nend\n",
            // 1 行に書いた `class << self` は、本家が補正で自分の書き換えを踏み潰して
            // 例外になり、offense ごと落ちる。
            "class A1\n  class << self; def a; end; end\nend\n",
        ] {
            CopCase::new(COP, source.to_owned(), Vec::new())
                .config(ON)
                .run();
        }
    }

    /// `self_class` では逆に `def self.` を報告する。補正は無い。`def Other.x` は
    /// このクラスの特異クラスを開かないので対象外。
    #[test]
    fn the_other_enforced_style_asks_for_a_singleton_class() {
        CopCase::annotated(
            COP,
            r"
            def self.top; end
            ^^^^^^^^^^^^^^^^^ Use `class << self` to define a class method.
            ",
        )
        .config(SELF_CLASS)
        .correctable(false)
        .run();
        CopCase::new(
            COP,
            "class SomeClass\n  def Other.x; end\n  def inst; end\n  class << self\n    def a; end\n  end\nend\n",
            Vec::new(),
        )
        .config(SELF_CLASS)
        .run();
    }
}

/// `Style/DisableCopsWithinSourceCodeDirective` (既定無効) — 期待値は本家 1.89.0 の実測。
mod style_disable_cops_within_source_code_directive {
    use super::*;

    const COP: &str = "Style/DisableCopsWithinSourceCodeDirective";
    const ON: &str = "Style/DisableCopsWithinSourceCodeDirective:\n  Enabled: true\n";
    const ALLOWED: &str = "Style/DisableCopsWithinSourceCodeDirective:\n  Enabled: true\n  AllowedCops:\n    - Metrics/AbcSize\n    - Style/For\n";
    const DISALLOWED: &str = "Style/DisableCopsWithinSourceCodeDirective:\n  Enabled: true\n  DisallowedCops:\n    - Lint/Void\n    - Style/Next\n";

    fn correction(config: &str, source: &str, corrected: &str) {
        CopCase::new(COP, source.to_owned(), Vec::new())
            .config(config)
            .without_offense_check()
            .corrected(corrected)
            .run();
    }

    /// 位置はコメント全体。`disable` も `enable` も同じように報告され、補正は
    /// コメントを消す。
    #[test]
    fn every_directive_comment_is_reported_and_taken_out() {
        CopCase::annotated(
            COP,
            r"
            # rubocop:disable Metrics/AbcSize
            ^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^ RuboCop disable/enable directives are not permitted.
            def foo
            end
            # rubocop:enable Metrics/AbcSize
            ^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^ RuboCop disable/enable directives are not permitted.
            ",
        )
        .config(ON)
        .run();
        correction(
            ON,
            "x = 0\n# rubocop:disable Metrics/AbcSize\ndef foo\nend\n# rubocop:enable Metrics/AbcSize\n",
            "x = 0\n\ndef foo\nend\n\n",
        );
    }

    /// コードの後ろに書かれたものも同じ。位置はコメントだけで、コードは残る。
    #[test]
    fn a_directive_written_after_code_is_reported_on_the_comment_alone() {
        CopCase::annotated(
            COP,
            r"
            x = 1 # rubocop:disable Style/For
                  ^^^^^^^^^^^^^^^^^^^^^^^^^^^ RuboCop disable/enable directives are not permitted.
            ",
        )
        .config(ON)
        .run();
        correction(
            ON,
            "y = 0\nx = 1 # rubocop:disable Style/For\n",
            "y = 0\nx = 1 \n",
        );
    }

    /// マーカーの前が `#` と空白だけのものは、コメントアウトされたディレクティブ
    /// なので数に入らない。前にコードがあるものは数に入る。
    #[test]
    fn a_directive_that_has_itself_been_commented_out_is_not_one() {
        CopCase::new(
            COP,
            "## rubocop:disable Style/For\n# a plain comment\nx = 1\n".to_owned(),
            Vec::new(),
        )
        .config(ON)
        .run();
        correction(
            ON,
            "x = 0\n#   def f # rubocop:disable Style/For\nx = 1\n",
            "x = 0\n\nx = 1\n",
        );
    }

    /// `push` の引数も名前として読まれる。`pop` は名前を持たないので報告されない。
    #[test]
    fn the_names_a_push_carries_are_read_as_its_cops() {
        CopCase::annotated(
            COP,
            r"
            # rubocop:push +Style/For
            ^^^^^^^^^^^^^^^^^^^^^^^^^ RuboCop disable/enable directives are not permitted.
            x = 1
            # rubocop:pop
            ",
        )
        .config(ON)
        .run();
    }

    /// `AllowedCops` に挙げた名前は許される。残りが名前で挙がり、コメントからは
    /// 許されない名前だけが落ちる。`all` は挙げても許されない。
    #[test]
    fn allowed_cops_keeps_the_names_it_lists() {
        for source in [
            "# rubocop:disable Metrics/AbcSize\ndef foo\nend\n# rubocop:enable Metrics/AbcSize\n",
            "x = 1 # rubocop:disable Style/For\n",
            "# rubocop:disable Style/For -- because\nx = 1\n",
        ] {
            CopCase::new(COP, source.to_owned(), Vec::new())
                .config(ALLOWED)
                .run();
        }
        CopCase::annotated(
            COP,
            r"
            # rubocop:disable Metrics/AbcSize, Style/Next
            ^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^ RuboCop disable/enable directives for `Style/Next` are not permitted.
            x = 1
            ",
        )
        .config(ALLOWED)
        .run();
        correction(
            ALLOWED,
            "x = 0\n# rubocop:disable Metrics/AbcSize, Style/Next\nx = 1\n",
            "x = 0\n# rubocop:disable Metrics/AbcSize\nx = 1\n",
        );
        CopCase::annotated(
            COP,
            r"
            # rubocop:disable all
            ^^^^^^^^^^^^^^^^^^^^^ RuboCop disable/enable directives for `all` are not permitted.
            x = 1
            ",
        )
        .config(ALLOWED)
        .run();
    }

    /// `DisallowedCops` を書いたときは、そこに挙げた名前と `all` だけが対象。
    #[test]
    fn disallowed_cops_reports_only_the_names_it_lists() {
        for source in [
            "x = 1 # rubocop:disable Style/For\n",
            "# rubocop:push +Style/For\nx = 1\n# rubocop:pop\n",
        ] {
            CopCase::new(COP, source.to_owned(), Vec::new())
                .config(DISALLOWED)
                .run();
        }
        CopCase::annotated(
            COP,
            r"
            # rubocop:disable Metrics/AbcSize, Style/Next
            ^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^ RuboCop disable/enable directives for `Style/Next` are not permitted.
            x = 1
            ",
        )
        .config(DISALLOWED)
        .run();
        // `all` は挙げていない名前も道連れにする。
        CopCase::annotated(
            COP,
            r"
            # rubocop:disable all
            ^^^^^^^^^^^^^^^^^^^^^ RuboCop disable/enable directives for `all` are not permitted.
            x = 1
            ",
        )
        .config(DISALLOWED)
        .run();
    }

    /// 設定が明示的に有効にしたこの cop は、ディレクティブでは黙らせられない。
    #[test]
    fn a_directive_cannot_switch_the_cop_off_once_the_configuration_asks_for_it() {
        CopCase::annotated(
            COP,
            r"
            # rubocop:disable all
            ^^^^^^^^^^^^^^^^^^^^^ RuboCop disable/enable directives are not permitted.
            x = 1
            # rubocop:enable all
            ^^^^^^^^^^^^^^^^^^^^ RuboCop disable/enable directives are not permitted.
            ",
        )
        .config(ON)
        .run();
    }
}

mod lint_require_range_parentheses {
    use super::*;

    const COP: &str = "Lint/RequireRangeParentheses";

    const MSG: &str = "Wrap the range literal `1..` in parentheses to avoid confusion with an \
                       endless range.";

    /// 行末で終わるレンジは括弧で囲む。レンジ全体を報告し、補正はしない。
    ///
    /// 注記のキャレットは 1 行目までしか描けないので、またいだ先までの範囲は
    /// `tests/conformance.rs` 側で `locations` / `lengths` に固定してある。
    #[test]
    fn a_range_whose_end_is_on_the_next_line_is_reported() {
        expect_offense(COP, &format!("x = 1..\n    ^^^ {MSG}\n42\n"));
        // 文法はレンジを 2 つに割るが、Ruby は 1 つのレンジとして読む。
        // 報告の範囲は組み直したレンジ全体。
        expect_offense(COP, &format!("1..\n^^^ {MSG}\n42\n"));
    }

    /// 括弧の中では改行が区切りにならないので、文法もレンジを割らない。
    /// それでも本家は演算子と終端の行が違えば報告する。
    #[test]
    fn a_range_the_grammar_kept_whole_is_reported_the_same_way() {
        expect_offense(COP, &format!("a = [1..\n     ^^^ {MSG}\n42]\n"));
        expect_offense(COP, &format!("foo(1..\n    ^^^ {MSG}\n42)\n"));
    }

    /// 終端の式は行頭の 1 語ではなく式全体。
    #[test]
    fn the_end_is_the_whole_expression_that_follows() {
        expect_offense(COP, &format!("x = 1..\n    ^^^ {MSG}\n8 + 9\n"));
    }

    /// 間にコメントしかなければ、Ruby は改行をまたいでレンジを続ける。
    #[test]
    fn a_comment_in_between_does_not_end_the_range() {
        expect_offense(COP, &format!("x = 1..\n    ^^^ {MSG}\n# note\n42\n"));
    }

    /// 括弧で囲めばそれが答え。式が続かない書き方、終端が同じ行にあるもの、
    /// 始端の無いレンジ、複数の文を持つ本体の中にあるものは黙る。
    #[test]
    fn what_the_cop_leaves_alone() {
        for source in [
            "y = (1..\n42)\n",
            "z = 1..42\n",
            "x = (1..)\ny = 2\n",
            "def m\n  1..\nend\n",
            // `,` があるので Ruby は終端を取り込まない。
            "c = [1.., 2]\n",
            "d = [1..,\n3]\n",
            "f = {a: 1..,\nb: 2}\n",
            // `then` が挟まると endless range のまま。
            "case x\nwhen 1..\nthen y\nend\n",
            // 本体が 2 文以上あると、本家はレンジの親を `begin` にする。
            "def n\n  q = 0\n  1..\n  42\nend\n",
            "puts 0\n1..\n42\n",
            // 補間は 1 文でも `begin`。
            "s = \"#{3..\n44}\"\n",
        ] {
            expect_no_offenses(COP, source);
        }
    }
}

/// `Style/RedundantFormat`。
///
/// 期待値は本家 1.89.0 を同じソースで走らせた実出力から取った (検出も `-A` もバイト一致を
/// 確認済み)。
mod style_redundant_format {
    use super::*;

    const COP: &str = "Style/RedundantFormat";

    fn correction(source: &str, corrected: &str) {
        CopCase::new(COP, source.to_owned(), Vec::new())
            .without_offense_check()
            .corrected(corrected)
            .run();
    }

    /// 書式指定の無い `format` は、その文字列そのもの。
    #[test]
    fn a_format_with_nothing_to_format_is_the_string_itself() {
        correction("a = format('name')\n", "a = 'name'\n");
        correction("a = sprintf(\"name\")\n", "a = \"name\"\n");
        correction("a = Kernel.format('name')\n", "a = 'name'\n");
        correction("a = format(CONST)\n", "a = CONST\n");
    }

    /// 引数が全部リテラルなら、書式を当てた結果まで畳める。
    #[test]
    fn literal_arguments_are_folded_into_the_result() {
        correction("a = format('%s', 'foo')\n", "a = 'foo'\n");
        correction("a = format('%d', 1)\n", "a = '1'\n");
        correction("a = format('%f', 1.5)\n", "a = '1.500000'\n");
        correction("a = format('%05d', 42)\n", "a = '00042'\n");
        correction("a = format('%-10s|', 'ab')\n", "a = 'ab        |'\n");
        correction("a = format('%.2f', 1.234)\n", "a = '1.23'\n");
        correction("a = format('%<x>s', x: 'foo')\n", "a = 'foo'\n");
        correction("a = format('%{x}', x: 'foo')\n", "a = 'foo'\n");
        correction("a = format('%2$s %1$s', 'x', 'y')\n", "a = 'y x'\n");
        correction("a = format('%*d', 5, 42)\n", "a = '   42'\n");
        correction("a = format('%s', nil)\n", "a = ''\n");
        correction("a = format('%s', :sym)\n", "a = 'sym'\n");
        // 式展開のある引数は結果も式展開できる形にする。
        correction("a = format('%s', \"x#{b}y\")\n", "a = \"x#{b}y\"\n");
    }

    /// リテラルでない引数、型の合わない書式、`%%`、splat は黙る。
    #[test]
    fn what_the_format_cop_leaves_alone() {
        for source in [
            "a = format('%s', foo)\n",
            "a = format('%x', 255)\n",
            "a = format('%s%%', 'a')\n",
            "a = format('%s', *args)\n",
            "a = format('%s', **opts)\n",
            "a = format('%s %d', 'a')\n",
            "a = format('%d', true)\n",
            "a = format('%5s', \"a#{b}c\")\n",
        ] {
            CopCase::new(COP, source.to_owned(), Vec::new()).run();
        }
    }
}

/// `Style/RedundantLineContinuation`。
///
/// 期待値は本家 1.89.0 を同じソースで走らせた実出力から取った (検出も `-A` もバイト一致を
/// 確認済み)。
mod style_redundant_line_continuation {
    use super::*;

    const COP: &str = "Style/RedundantLineContinuation";

    fn correction(source: &str, corrected: &str) {
        CopCase::new(COP, source.to_owned(), Vec::new())
            .without_offense_check()
            .corrected(corrected)
            .run();
    }

    /// 消しても構文が変わらない `\` は消える。消えるのは backslash 1 文字だけなので、
    /// 手前にあった空白はそのまま残る。
    #[test]
    fn a_line_continuation_the_parser_did_not_need_is_removed() {
        correction("foo = 1 + \\\n  2\n", "foo = 1 + \n  2\n");
        correction("qux = foo \\\n  .bar\n", "qux = foo \n  .bar\n");
        correction("quux(1, \\\n  2)\n", "quux(1, \n  2)\n");
        correction("corge = [1, \\\n  2]\n", "corge = [1, \n  2]\n");
        // 最終行の末尾に残った `\` も対象。
        correction("fred = 1 + 2 \\\n", "fred = 1 + 2 \n");
    }

    /// 文字列の中、コメントの中、暗黙の文字列連結、消すと構文が変わるものは黙る。
    #[test]
    fn what_the_line_continuation_cop_leaves_alone() {
        for source in [
            "baz = \"a\" \\\n  \"b\"\n",
            "waldo = \"a\\\nb\"\n",
            "# comment \\\ngarply = 1\n",
            "grault = <<~T\n  a \\\n  b\nT\n",
            // 次の行が演算子で始まるので、`\` を消すと別の構文になる。
            "s = 1 if foo \\\n  && bar\n",
            // 空行を挟んだ leading dot は `\` が無いと繋がらない。
            "r = foo \\\n\n  .bar\n",
            // 次の行が新しい式を始めるなら、`\` はそれを引数として繋いでいる。
            "assert_equal \\\n  \"a\",\n  b\n",
        ] {
            CopCase::new(COP, source.to_owned(), Vec::new()).run();
        }
    }
}

/// `Style/RedundantStringEscape`。
///
/// 期待値は本家 1.89.0 を同じソースで走らせた実出力から取った (検出も `-A` もバイト一致を
/// 確認済み)。
mod style_redundant_string_escape {
    use super::*;

    const COP: &str = "Style/RedundantStringEscape";

    fn correction(source: &str, corrected: &str) {
        CopCase::new(COP, source.to_owned(), Vec::new())
            .without_offense_check()
            .corrected(corrected)
            .run();
    }

    /// 何も escape していない backslash は消える。
    #[test]
    fn a_backslash_that_escapes_nothing_is_removed() {
        correction("foo = \"\\.bar\"\n", "foo = \".bar\"\n");
        correction("foo = \"\\!bar\"\n", "foo = \"!bar\"\n");
        // 二重引用符の中の単引用符は区切り文字ではない。
        correction("foo = \"\\'bar\"\n", "foo = \"'bar\"\n");
        // `%W` は式展開が効くので escape も効く。`%w` は効かない。
        correction("foo = %W[a\\.b]\n", "foo = %W[a.b]\n");
        correction("foo = \"a\\ b\"\n", "foo = \"a b\"\n");
        // ヒアドキュメントの中も見る。
        correction("foo = <<~T\n  a\\.b\nT\n", "foo = <<~T\n  a.b\nT\n");
    }

    /// 区切り文字、英数字、`\\`、式展開を止める `\#{`、式展開の無い書き方は黙る。
    #[test]
    fn what_the_escape_cop_leaves_alone() {
        for source in [
            "foo = \"\\\"bar\"\n",
            "foo = \"\\n\"\n",
            "foo = \"\\\\\"\n",
            "foo = 'a\\.b'\n",
            "foo = 'a\\'b'\n",
            "foo = %q(a\\.b)\n",
            "foo = %w[a\\.b]\n",
            "foo = \"a\\#{b}c\"\n",
            "foo = /a\\.b/\n",
            "foo = ?\\.\n",
            "foo = <<~'T'\n  a\\.b\nT\n",
            "foo = %(a\\(b\\)c)\n",
        ] {
            CopCase::new(COP, source.to_owned(), Vec::new()).run();
        }
    }
}

/// `Style/MissingElse` (既定無効) — 期待値は本家 1.89.0 の実測。
mod style_missing_else {
    use super::*;

    const COP: &str = "Style/MissingElse";
    const EMPTY: &str = "Style/EmptyElse:\n  EnforcedStyle: empty\n";
    const NIL: &str = "Style/EmptyElse:\n  EnforcedStyle: nil\n";

    /// 位置は条件式の全体。既定では `Style/EmptyElse` が `else` の中身を決めないので
    /// 補正は付かない。
    #[test]
    fn a_conditional_without_an_else_is_reported() {
        expect_offense(
            COP,
            r"
            if a
            ^^^^ `if` condition requires an `else`-clause.
              b
            end
            ",
        );
        expect_offense(
            COP,
            r"
            case v
            ^^^^^^ `case` condition requires an `else`-clause.
            when 1
              b
            end
            ",
        );
        for source in [
            "if a\n  b\nelse\n  c\nend\n",
            "case v\nwhen 1\n  b\nelse\n  c\nend\n",
        ] {
            expect_no_offenses(COP, source);
        }
    }

    /// `elsif` は本家の木では `if` そのものなので、それだけで報告される。`elsif` を
    /// 持つ外側の `if` は `loc.else` を持つので報告されない。
    #[test]
    fn an_elsif_is_a_conditional_of_its_own() {
        expect_offense(
            COP,
            r"
            if a
              b
            elsif c
            ^^^^^^^ `if` condition requires an `else`-clause.
              d
            end
            ",
        );
        expect_no_offenses(COP, "if a\n  b\nelsif c\n  d\nelse\n  e\nend\n");
    }

    /// ヒアドキュメントの本体も行末のコメントも本家の式の範囲には入らないので、
    /// `elsif` はそれを開いた文までで終わる。
    #[test]
    fn the_range_stops_at_the_last_statement_of_the_branch() {
        CopCase::annotated(
            COP,
            "if a\n  b\nelsif c\n  raise D, <<~MSG\n    text\n  MSG\nend\n",
        )
        .without_offense_check()
        .locations(&[(3, 1, 4, 17)])
        .lengths(&[25])
        .run();
    }

    /// 三項演算子と後置修飾は `OnNormalIfUnless` が外す。`case ... in` は何も
    /// 合わなければ例外を上げるので `else` を要らない。
    #[test]
    fn what_the_cop_leaves_alone() {
        for source in [
            "x = a ? b : c\ny = b if a\nz = b unless a\n",
            "case v\nin 1\n  b\nend\n",
            // `Style/UnlessElse` が有効なら `unless` はあちらの持ち場。
            "unless a\n  b\nend\n",
        ] {
            expect_no_offenses(COP, source);
        }
    }

    /// `Style/UnlessElse` を切ると `unless` もこちらが見る。
    #[test]
    fn an_unless_is_checked_once_the_other_cop_is_off() {
        CopCase::annotated(
            COP,
            r"
            unless a
            ^^^^^^^^ `if` condition requires an `else`-clause.
              b
            end
            ",
        )
        .config("Style/UnlessElse:\n  Enabled: false\n")
        .run();
    }

    /// `EnforcedStyle` はどちらを見るかを決める。
    #[test]
    fn the_enforced_style_chooses_between_if_and_case() {
        let both = "if a\n  b\nend\ncase v\nwhen 1\n  b\nend\n";
        CopCase::new(COP, both.to_owned(), Vec::new())
            .config("Style/MissingElse:\n  EnforcedStyle: if\n")
            .without_offense_check()
            .locations(&[(1, 1, 3, 3)])
            .lengths(&[12])
            .run();
        CopCase::new(COP, both.to_owned(), Vec::new())
            .config("Style/MissingElse:\n  EnforcedStyle: case\n")
            .without_offense_check()
            .locations(&[(4, 1, 7, 3)])
            .lengths(&[21])
            .run();
    }

    /// `Style/EmptyElse` の style が `else` の中身を決めているときだけ補正が付く。
    /// 空の `else` を報告する側なら `nil` を入れ、`nil` を報告する側なら空で足す。
    #[test]
    fn the_neighbouring_cop_decides_what_the_added_else_holds() {
        CopCase::annotated(
            COP,
            r"
            if a
            ^^^^ `if` condition requires an `else`-clause with `nil` in it.
              b
            end
            ",
        )
        .config(EMPTY)
        .run();
        CopCase::new(COP, "if a\n  b\nend\n".to_owned(), Vec::new())
            .config(EMPTY)
            .without_offense_check()
            .corrected("if a\n  b\nelse; nil; end\n")
            .run();
        CopCase::annotated(
            COP,
            r"
            if a
            ^^^^ `if` condition requires an empty `else`-clause.
              b
            end
            ",
        )
        .config(NIL)
        .run();
        CopCase::new(COP, "if a\n  b\nend\n".to_owned(), Vec::new())
            .config(NIL)
            .without_offense_check()
            .corrected("if a\n  b\nelse; end\n")
            .run();
        // `elsif` を閉じるのは自分の `end` ではなく、属している `if` の `end`。
        CopCase::new(COP, "if a\n  b\nelsif c\n  d\nend\n".to_owned(), Vec::new())
            .config(NIL)
            .without_offense_check()
            .corrected("if a\n  b\nelsif c\n  d\nelse; end\n")
            .run();
        CopCase::new(COP, "case v\nwhen 1\n  b\nend\n".to_owned(), Vec::new())
            .config(NIL)
            .without_offense_check()
            .corrected("case v\nwhen 1\n  b\nelse; end\n")
            .run();
    }
}

mod style_arguments_forwarding {
    use super::*;

    const COP: &str = "Style/ArgumentsForwarding";

    const FORWARDING: &str = "Use shorthand syntax `...` for arguments forwarding.";
    const ARGS: &str = "Use anonymous positional arguments forwarding (`*`).";
    const KWARGS: &str = "Use anonymous keyword arguments forwarding (`**`).";
    const BLOCK: &str = "Use anonymous block arguments forwarding (`&`).";

    /// 2.7 では `...` にまとめられる。定義と呼び出しの両方を報告する。
    #[test]
    fn everything_forwarded_together_becomes_the_shorthand() {
        CopCase::annotated(
            COP,
            &format!(
                "def foo(*args, &block)\n        ^^^^^^^^^^^^^ {FORWARDING}\n  \
                 bar(*args, &block)\n      ^^^^^^^^^^^^^ {FORWARDING}\nend\n"
            ),
        )
        .corrected("def foo(...)\n  bar(...)\nend\n")
        .run();
    }

    /// `AllowOnlyRestArgument` が既定で真なので、`*args` だけの転送は 2.7 では通る。
    /// ブロックまで持っていってしまう `...` とは意味が違うため。
    #[test]
    fn only_a_rest_argument_is_allowed_before_3_2() {
        expect_no_offenses(COP, "def foo(*args)\n  bar(*args)\nend\n");
        expect_no_offenses(COP, "def foo(**kwargs)\n  bar(**kwargs)\nend\n");
    }

    /// 3.2 では `*` と `**` の両方が揃っていないと `...` にできない。片方だけなら
    /// それぞれを匿名にする。
    #[test]
    fn from_3_2_each_one_is_anonymised_on_its_own() {
        CopCase::annotated(
            COP,
            &format!(
                "def foo(*args, &block)\n        ^^^^^ {ARGS}\n               ^^^^^^ {BLOCK}\n  \
                 bar(*args, &block)\n      ^^^^^ {ARGS}\n             ^^^^^^ {BLOCK}\nend\n"
            ),
        )
        .target_ruby("3.2")
        .corrected("def foo(*, &)\n  bar(*, &)\nend\n")
        .run();
        // 3 つ揃っていれば 3.2 でも `...`。
        CopCase::annotated(
            COP,
            &format!(
                "def foo(*args, **kwargs, &block)\n        ^^^^^^^^^^^^^^^^^^^^^^^ {FORWARDING}\n  \
                 bar(*args, **kwargs, &block)\n      ^^^^^^^^^^^^^^^^^^^^^^^ {FORWARDING}\nend\n"
            ),
        )
        .target_ruby("3.2")
        .corrected("def foo(...)\n  bar(...)\nend\n")
        .run();
    }

    /// 括弧を書いていない定義や呼び出しには、書き換えのついでに括弧が付く。
    #[test]
    fn parentheses_are_added_where_they_were_missing() {
        expect_correction(
            COP,
            "def foo(*args, &block)\n  bar *args, &block\nend\n",
            "def foo(...)\n  bar(...)\nend\n",
        );
        expect_correction(
            COP,
            "def foo *args, &block\n  bar(*args, &block)\nend\n",
            "def foo(...)\n  bar(...)\nend\n",
        );
    }

    /// 名前が設定の一覧に無ければ、意味のある名前として残す。
    #[test]
    fn a_meaningful_name_is_left_alone() {
        expect_no_offenses(
            COP,
            "def foo(*things, &callback)\n  bar(*things, &callback)\nend\n",
        );
        // 転送以外の場所で読まれている名前も残す。
        expect_no_offenses(
            COP,
            "def foo(*args, &block)\n  args.first\n  bar(*args, &block)\nend\n",
        );
    }

    /// ブロックの中では匿名の引数が 3.3 で構文エラーになるので、3.4 未満では提案しない。
    /// 本家では `block` ノードが呼び出しを包むので、ブロックを持つ呼び出しの引数も
    /// 「ブロックの中」に数える。
    #[test]
    fn nothing_is_anonymised_inside_a_block_before_3_4() {
        for source in [
            "def foo(*args, &block)\n  [1].each { bar(*args, &block) }\nend\n",
            "def foo(*args)\n  bar(*args) { baz }\nend\n",
            "def foo(*args)\n  bar(*args).tap { |x| x }\nend\n",
        ] {
            CopCase::new(COP, support::annotation::dedent(source), Vec::new())
                .target_ruby("3.2")
                .run();
        }
    }

    /// 2.7 より前にはそもそも `...` が無い。
    #[test]
    fn the_cop_is_silent_before_2_7() {
        CopCase::new(
            COP,
            "def foo(*args, &block)\n  bar(*args, &block)\nend\n".to_owned(),
            Vec::new(),
        )
        .target_ruby("2.6")
        .run();
    }

    /// 一覧に載っている名前と載っていない名前が混じっていたら、載っている方だけが
    /// 匿名になる。
    #[test]
    fn only_the_redundant_half_of_a_mixed_pair_is_anonymised() {
        CopCase::annotated(
            COP,
            &format!(
                "def foo(*rest, &blk)\n               ^^^^ {BLOCK}\n  \
                 bar(*rest, &blk)\n             ^^^^ {BLOCK}\nend\n"
            ),
        )
        .target_ruby("3.2")
        .corrected("def foo(*rest, &)\n  bar(*rest, &)\nend\n")
        .run();
    }

    /// 多重代入の左辺も `lvasgn` なので、そこに現れた名前は転送ではなく参照。
    #[test]
    fn a_name_written_on_the_left_of_a_multiple_assignment_is_referenced() {
        expect_no_offenses(
            COP,
            "def foo(*args, **options)\n  a, b, options = split(*args, **options)\n  \
             bar(*args, **options)\nend\n",
        );
    }

    /// `Naming/BlockForwarding` が `explicit` なら、ブロックだけは名前のまま残す。
    #[test]
    fn an_explicit_block_name_is_left_where_the_other_cop_wants_it() {
        CopCase::new(
            COP,
            "def foo(*args, &block)\n  bar(*args, &block)\nend\n".to_owned(),
            Vec::new(),
        )
        .config("Naming/BlockForwarding:\n  Enabled: true\n  EnforcedStyle: explicit\n")
        .target_ruby("3.4")
        .without_offense_check()
        .corrected("def foo(*, &block)\n  bar(*, &block)\nend\n")
        .run();
    }

    /// 3.4 からはブロックの中でも匿名にできる。
    #[test]
    fn ruby_34_anonymises_inside_a_block_after_all() {
        CopCase::new(
            COP,
            "def foo(*args, &block)\n  [1].each { bar(*args, &block) }\nend\n".to_owned(),
            Vec::new(),
        )
        .target_ruby("3.4")
        .without_offense_check()
        .corrected("def foo(*, &)\n  [1].each { bar(*, &) }\nend\n")
        .run();
    }

    /// 入れ子のブロックの引数が定義の引数と同じ名前でも、宣言は参照ではない。
    /// 本家は `lvar` と `lvasgn` しか数えず、`restarg` などの宣言は数に入らない。
    #[test]
    fn a_nested_block_parameter_of_the_same_name_is_not_a_reference() {
        CopCase::new(
            COP,
            "def foo(*args, **kwargs, &block)\n  block = proc { |*args, **kwargs| nil }\n  \
             baz(*args, **kwargs, &block)\nend\n"
                .to_owned(),
            Vec::new(),
        )
        .target_ruby("3.4")
        .without_offense_check()
        .corrected(
            "def foo(*, **, &block)\n  block = proc { |*args, **kwargs| nil }\n  \
             baz(*, **, &block)\nend\n",
        )
        .run();
    }

    /// 本体の無い定義と、何も転送していない呼び出しは触らない。
    #[test]
    fn what_the_cop_leaves_alone() {
        for source in [
            "def foo(*args); end\n",
            "def foo(*args)\n  bar(1)\nend\n",
            "def foo(...)\n  bar(...)\nend\n",
        ] {
            expect_no_offenses(COP, source);
        }
    }

    /// `yield` と `x[...]` も本家では送信なので同じように見る。
    #[test]
    fn a_yield_and_an_index_are_sends_too() {
        CopCase::annotated(
            COP,
            &format!(
                "def foo(*args, **kwargs)\n        ^^^^^ {ARGS}\n               ^^^^^^^^ {KWARGS}\n  \
                 yield(*args, **kwargs)\n        ^^^^^ {ARGS}\n               ^^^^^^^^ {KWARGS}\nend\n"
            ),
        )
        .target_ruby("3.2")
        .corrected("def foo(*, **)\n  yield(*, **)\nend\n")
        .run();
    }
}

/// `Style/MethodCallWithArgsParentheses` (既定無効) — 期待値は本家 1.89.0 の実測。
mod style_method_call_with_args_parentheses {
    use super::*;

    const COP: &str = "Style/MethodCallWithArgsParentheses";
    const NO_MACROS: &str = "Style/MethodCallWithArgsParentheses:\n  IgnoreMacros: false\n";
    const OMIT: &str = "Style/MethodCallWithArgsParentheses:\n  EnforcedStyle: omit_parentheses\n";

    fn correction(config: &str, source: &str, corrected: &str) {
        CopCase::new(COP, source.to_owned(), Vec::new())
            .config(config)
            .without_offense_check()
            .corrected(corrected)
            .run();
    }

    /// 位置は呼び出し全体。補正は selector の後ろの空白を `(` に変え、引数の末尾へ
    /// `)` を足す。
    #[test]
    fn a_call_given_arguments_without_parentheses_is_reported() {
        expect_offense(
            COP,
            r"
            obj.foo 1, 2
            ^^^^^^^^^^^^ Use parentheses for method calls with arguments.
            ",
        );
        expect_correction(COP, "obj.foo 1, 2\n", "obj.foo(1, 2)\n");
    }

    /// `IgnoreMacros` が既定で真なので、クラス本体やトップレベルに書かれた呼び出しは
    /// マクロとして見逃される。`def` の中はマクロの立ち位置ではない。
    #[test]
    fn a_macro_is_left_alone_unless_the_configuration_asks_for_it() {
        CopCase::annotated(
            COP,
            r"
            class C
              validates :a
              def m
                helper 1
                ^^^^^^^^ Use parentheses for method calls with arguments.
              end
            end
            ",
        )
        .run();
        CopCase::annotated(
            COP,
            r"
            class C
              validates :a
              ^^^^^^^^^^^^ Use parentheses for method calls with arguments.
              def m
                helper 1
                ^^^^^^^^ Use parentheses for method calls with arguments.
              end
            end
            ",
        )
        .config("Style/MethodCallWithArgsParentheses:\n  IncludedMacros:\n    - validates\n")
        .run();
        correction(
            NO_MACROS,
            "puts \"x\"\nassert_equal 1, 2\nfoo 1\n",
            "puts(\"x\")\nassert_equal(1, 2)\nfoo(1)\n",
        );
    }

    /// 引数が 1 つで、それ自身が括弧で括られているなら、その括弧を借りて閉じる。
    /// `yield` の selector はキーワードそのもの。
    #[test]
    fn an_argument_that_is_already_parenthesized_lends_its_own() {
        correction(NO_MACROS, "foo (1)\n", "foo(1)\n");
        correction(NO_MACROS, "yield 1\n", "yield(1)\n");
    }

    /// `AllowedMethods` と `AllowedPatterns` に当たる名前は見逃す。
    #[test]
    fn the_allowed_names_are_left_alone() {
        CopCase::new(
            COP,
            "puts \"x\"\nassert_equal 1, 2\nfoo 1\n".to_owned(),
            Vec::new(),
        )
        .config(
            "Style/MethodCallWithArgsParentheses:\n  AllowedMethods:\n    - puts\n  AllowedPatterns:\n    - '\\Aassert'\n",
        )
        .run();
    }

    /// 演算子・setter・`super`・既に括弧のあるもの・引数の無いものは触らない。
    #[test]
    fn what_the_cop_leaves_alone() {
        CopCase::new(
            COP,
            "a.+ b\nfoo.bar = 1\nsuper 1\nfoo(1)\nfoo\n".to_owned(),
            Vec::new(),
        )
        .config(NO_MACROS)
        .run();
    }

    /// `omit_parentheses` では逆向き。位置は括弧の開きから閉じまで。
    #[test]
    fn the_other_enforced_style_takes_the_parentheses_away() {
        CopCase::annotated(
            COP,
            r"
            foo(1)
               ^^^ Omit parentheses for method calls with arguments.
            ",
        )
        .config(OMIT)
        .run();
        correction(OMIT, "foo(1)\n", "foo 1\n");
        // 大文字で始まる名前は引数があれば報告される。設定で見逃せる。
        correction(OMIT, "Foo(1)\n", "Foo 1\n");
        CopCase::new(COP, "Foo(1)\n".to_owned(), Vec::new())
            .config("Style/MethodCallWithArgsParentheses:\n  EnforcedStyle: omit_parentheses\n  AllowParenthesesInCamelCaseMethod: true\n")
            .run();
    }

    /// 中身の無い括弧も外す。本家のパーサは空の引数リストにノードを作らないので、`foo()` と
    /// `foo`、`yield()` と `yield` は同じ木になる。tree-sitter は前者に `argument_list` を
    /// 作るため、外した後の木が元と一致せず報告できなかった。
    #[test]
    fn a_pair_of_parentheses_holding_nothing_comes_off_too() {
        CopCase::annotated(
            COP,
            r"
            def a
              mail()
                  ^^ Omit parentheses for method calls with arguments.
            end
            def b
              Firm.new()
                      ^^ Omit parentheses for method calls with arguments.
            end
            def c
              yield()
                   ^^ Omit parentheses for method calls with arguments.
            end
            ",
        )
        .config(OMIT)
        .run();
        // 訂正は `(` を空白に置き換えて `)` を消すので、行末に空白が 1 つ残る。
        correction(
            OMIT,
            "def a
  mail()
end
",
            "def a
  mail 
end
",
        );
        correction(
            OMIT,
            "def b
  Firm.new()
end
",
            "def b
  Firm.new 
end
",
        );
        correction(
            OMIT,
            "def c
  yield()
end
",
            "def c
  yield 
end
",
        );
        correction(
            OMIT,
            "def d
  bar() do
    1
  end
end
",
            "def d
  bar  do
    1
  end
end
",
        );
    }

    /// 名前を局所変数が持っているときだけは残る。括弧があるうちは呼び出しだが、外すと
    /// その変数を読むだけになり、本家の再パースが別の木として弾く。
    #[test]
    fn empty_parentheses_stay_where_the_name_is_a_local_variable() {
        for source in [
            "def d
  foo = 1
  foo()
end
",
            // 波括弧のブロックを持つ呼び出しと、引数を渡さない `super`。
            "def e
  bar() { 1 }
end
",
            "def f
  super()
end
",
            // 連鎖の途中。
            "def h
  qux().to_s
end
",
        ] {
            CopCase::new(COP, source.to_owned(), Vec::new())
                .config(OMIT)
                .run();
        }
    }

    /// 括弧が行末を閉じている複数行の呼び出しは、空白ではなく行継続を置く。
    /// 継続の後ろの空白は構文誤りなので、そこまで巻き取る。
    #[test]
    fn a_multiline_call_leaves_a_line_continuation_behind() {
        correction(OMIT, "x = foo(\n  1\n)\n", "x = foo \\\n  1\n\n");
        CopCase::new(COP, "x = foo(\n  1\n)\n".to_owned(), Vec::new())
            .config("Style/MethodCallWithArgsParentheses:\n  EnforcedStyle: omit_parentheses\n  AllowParenthesesInMultilineCall: true\n")
            .run();
    }

    /// 外すと読み方が変わるものは残す。
    #[test]
    fn the_parentheses_a_call_needs_are_left_where_they_are() {
        for source in [
            // ブロックを持つ呼び出し。
            "foo(1) { }\n",
            // 別の呼び出しの引数。
            "x = { a: 1 }\nbar foo(1)\n",
            // 符号付きの数、三項演算子、終端の無い範囲、波括弧のハッシュ。
            "foo(-1)\nfoo(a ? b : c)\nfoo(1..)\nfoo({ a: 1 })\n",
            // 1 行の継承、既定値、`when` の条件。
            "class C < Foo(1); end\ndef m(a = foo(1)); end\ncase x\nwhen foo(1)\n  y\nend\n",
        ] {
            CopCase::new(COP, source.to_owned(), Vec::new())
                .config(OMIT)
                .run();
        }
    }

    /// エンドレス定義の引数は括弧が要る。
    #[test]
    fn an_endless_definition_keeps_the_parentheses_of_its_body() {
        CopCase::new(
            COP,
            "def m = foo(1)\nx = foo(\n  1\n)\n".to_owned(),
            Vec::new(),
        )
        .config(OMIT)
        .target_ruby("3.4")
        .without_offense_check()
        .locations(&[(2, 8, 4, 1)])
        .lengths(&[7])
        .run();
    }
}

/// `Lint/LiteralAsCondition` の後置形。
///
/// 期待値は本家 1.89.0 の `--only Lint/LiteralAsCondition -A` の実出力。
mod lint_literal_as_condition_modifier {
    use super::*;

    const COP: &str = "Lint/LiteralAsCondition";

    fn correction(source: &str, corrected: &str) {
        CopCase::new(COP, source.to_owned(), Vec::new())
            .without_offense_check()
            .corrected(corrected)
            .run();
    }

    /// 後置の `if` / `unless` は、条件が消えても**守っていた式は残る**。文法では
    /// 後置形が式を `body` に持ち、`consequence` を持つのはブロック形だけなので、
    /// `consequence` だけを見ると式ごと消えてしまう。
    #[test]
    fn a_modifier_keeps_what_it_guarded() {
        correction("def m\n  a if true\nend\n", "def m\n  a\nend\n");
        correction("def m\n  b unless false\nend\n", "def m\n  b\nend\n");
        // 制御構造でも同じ。以前はここで `break` / `return` が消えていた。
        correction(
            "def m\n  foo do\n    break if true\n  end\nend\n",
            "def m\n  foo do\n    break\n  end\nend\n",
        );
        correction("def m\n  return if true\nend\n", "def m\n  return\nend\n");
        // 生き残らない側は消える。
        correction("def m\n  c if false\nend\n", "def m\n  \nend\n");
        correction("def m\n  d unless true\nend\n", "def m\n  \nend\n");
    }
}

/// `Lint/UnusedBlockArgument` の補正の作り方。
///
/// 期待値は本家 1.89.0 の `--only Lint/UnusedBlockArgument,Style/Lambda -A` の実出力。
mod lint_unused_block_argument_correction {
    use super::*;

    /// 名前を丸ごと `_name` に置き換える (先頭に `_` を差し込むのではない)。同じ引数を
    /// 同じパスで別の cop が書き換えているとき、範囲が一致する置換は clobber として
    /// 次のパスへ回るが、範囲の端への挿入はすり抜けて隣の字面にくっついてしまう。
    /// `-> env do` を `lambda do |env|` にする `Style/Lambda` と重なると、`lambda_` が
    /// できていた。
    /// 単独で走らせるとどちらの形でも `_env` になるので、字面だけでは捕まらない。
    /// Edit の形そのものを見る。
    #[test]
    fn the_name_is_replaced_rather_than_prefixed() {
        let source = "def m\n  foo(bar: -> env do\n    1\n  end)\nend\n";
        let report = CopCase::new("Lint/UnusedBlockArgument", source.to_owned(), Vec::new())
            .without_offense_check()
            .inspect();
        let corrections: Vec<_> = report
            .offenses
            .iter()
            .flat_map(|offense| offense.corrections.iter())
            .collect();
        let name = source.find("env").expect("引数が見つからない");
        assert_eq!(corrections.len(), 1, "correction は 1 件のはず");
        assert_eq!(
            (
                corrections[0].start,
                corrections[0].end,
                corrections[0].replacement.as_str()
            ),
            (name, name + "env".len(), "_env"),
            "名前のレンジごと `_env` に置き換わっていない (先頭への挿入になっている)"
        );
    }

    /// 実際に壊れていた組み合わせ。`-> env do` を `lambda do |env|` に組み替える
    /// `Style/Lambda` と重なると、先頭への挿入は引数から離れて `lambda_` になっていた。
    #[test]
    fn the_lambda_keyword_does_not_absorb_the_underscore() {
        CopCase::new(
            "Lint/UnusedBlockArgument",
            "def m\n  foo(bar: -> env do\n    1\n  end)\nend\n".to_owned(),
            Vec::new(),
        )
        .cops(&["Lint/UnusedBlockArgument", "Style/Lambda"])
        .without_offense_check()
        .corrected("def m\n  foo(bar: lambda do |_env|\n    1\n  end)\nend\n")
        .run();
    }
}

/// `Lint/UnusedMethodArgument` の correction。
///
/// 期待値は本家 1.89.0 の
/// `--only Lint/UnusedMethodArgument,Style/MethodDefParentheses -A` の実出力。
mod lint_unused_method_argument_correction {
    use super::*;

    /// `Lint/UnusedBlockArgument` と同じ `UnusedArgCorrector` を共有していて、同じ
    /// 取り違えをしていた。本家は `corrector.replace(node.loc.name, "_#{name}")` で
    /// **名前を丸ごと置き換える**。移植版は先頭へ `_` を差し込んでいた。
    ///
    /// 直った字面だけを見ても捕まらない。単独で走らせればどちらの形でも `_bar` に
    /// なるからで、差が出るのは同じ引数を別の cop が同じパスで書き換えたときだけ。
    /// メソッド引数ではその相手になる cop が今のところ無く、`-A` の出力比較では
    /// 一致してしまう。だから **Edit の形そのもの** を見る。
    #[test]
    fn the_name_is_replaced_rather_than_prefixed() {
        let source = "def foo(bar)\n  1\nend\n";
        let report = CopCase::new("Lint/UnusedMethodArgument", source.to_owned(), Vec::new())
            .without_offense_check()
            .inspect();
        let corrections: Vec<_> = report
            .offenses
            .iter()
            .flat_map(|offense| offense.corrections.iter())
            .collect();
        let name = source.find("bar").expect("引数が見つからない");
        assert_eq!(corrections.len(), 1, "correction は 1 件のはず");
        assert_eq!(
            (
                corrections[0].start,
                corrections[0].end,
                corrections[0].replacement.as_str()
            ),
            (name, name + "bar".len(), "_bar"),
            "名前のレンジごと `_bar` に置き換わっていない (先頭への挿入になっている)"
        );
    }

    /// 上と同じことを `-A` の側からも押さえておく。括弧を補う
    /// `Style/MethodDefParentheses` と重なっても本家と同じ字面になる。
    #[test]
    fn parentheses_are_added_around_the_renamed_argument() {
        CopCase::new(
            "Lint/UnusedMethodArgument",
            "def foo bar\n  1\nend\n".to_owned(),
            Vec::new(),
        )
        .cops(&["Lint/UnusedMethodArgument", "Style/MethodDefParentheses"])
        .without_offense_check()
        .corrected("def foo(_bar)\n  1\nend\n")
        .run();
    }

    /// splat は `*` を残して名前だけを置き換える (本家の `gsub(/\A\*+/, '')`)。
    #[test]
    fn a_splat_keeps_its_star() {
        CopCase::new(
            "Lint/UnusedMethodArgument",
            "def one(*bar)\n  do_something(1, 2)\nend\n".to_owned(),
            Vec::new(),
        )
        .without_offense_check()
        .corrected("def one(*_bar)\n  do_something(1, 2)\nend\n")
        .run();
    }
}

/// `Layout/DefEndAlignment` の走査。
///
/// 期待値は本家 1.89.0 の `--only Layout/DefEndAlignment -A` の実出力。
mod layout_def_end_alignment_walk {
    use super::*;

    const COP: &str = "Layout/DefEndAlignment";

    /// ブロックの中の定義も見る。`private def foo` を拾う枝が、それ以外の呼び出しで
    /// 走査ごと打ち切っていたので、ブロックがぶら下がる呼び出しの下がまるごと
    /// 見えなくなっていた。`class` の中なら通っていたぶん気づきにくい。
    #[test]
    fn a_definition_inside_a_block_is_still_measured() {
        CopCase::new(
            COP,
            "Foo.bar do\n  def m\n    x\n      end\nend\n".to_owned(),
            Vec::new(),
        )
        .without_offense_check()
        .corrected("Foo.bar do\n  def m\n    x\n  end\nend\n")
        .run();
        CopCase::new(
            COP,
            "Foo.bar {\n  def m\n    x\n      end\n}\n".to_owned(),
            Vec::new(),
        )
        .without_offense_check()
        .corrected("Foo.bar {\n  def m\n    x\n  end\n}\n")
        .run();
        // `private def foo` の枝は従来どおり。
        CopCase::new(
            COP,
            "class C\n  private def m\n    x\n      end\nend\n".to_owned(),
            Vec::new(),
        )
        .without_offense_check()
        .corrected("class C\n  private def m\n    x\n  end\nend\n")
        .run();
    }
}

/// `Naming/RescuedExceptionsVariableName` の correction。
///
/// 期待値は本家 1.89.0 の
/// `--only Naming/RescuedExceptionsVariableName,Lint/UselessAssignment -a` の実出力。
mod naming_rescued_exceptions_variable_name_correction {
    use super::*;

    const COP: &str = "Naming/RescuedExceptionsVariableName";

    /// 本家は改名する箇所ごとに `corrector.replace` を呼ぶ。移植版は宣言から最後の参照
    /// までを 1 つの Edit にまとめていて、その間に書かれたものを丸ごと飲み込んでいた。
    ///
    /// 変数は `begin`/`end` を抜けても生きているので、ブロックの後ろの参照まで改名する。
    /// つまりこの 1 つの Edit は**ファイルの後ろにある別の `rescue` ごと覆う**。同名を
    /// 使う 2 つ目の `rescue` は自分の offense が clobber して次のパスへ回され、本体だけ
    /// 新しい名前になった中間状態が残る。そこで `Lint/UselessAssignment` が
    /// 「もう誰も読んでいない」と見て `=> error` を消してしまい、動かないコードになる。
    #[test]
    fn each_rename_is_its_own_edit() {
        let source = "begin\n  a\nrescue LoadError => error\n  raise error\nend\n";
        let report = CopCase::new(COP, source.to_owned(), Vec::new())
            .without_offense_check()
            .inspect();
        let corrections: Vec<_> = report
            .offenses
            .iter()
            .flat_map(|offense| offense.corrections.iter())
            .collect();
        assert_eq!(
            corrections.len(),
            2,
            "宣言と参照で 2 件のはず。1 件なら間を飲み込む 1 つの Edit に戻っている: {corrections:?}"
        );
        for correction in &corrections {
            assert_eq!(
                correction.replacement, "e",
                "置き換えるのは名前だけのはず: {correction:?}"
            );
        }
    }

    /// 同じ名前を使う `rescue` がもう 1 つあっても、両方とも改名される。
    /// まとめた Edit だったころは 2 つ目が `rescue Foo` になり、本体は `c e` のまま
    /// 残っていた。
    #[test]
    fn a_second_handler_using_the_same_name_keeps_its_variable() {
        CopCase::new(
            COP,
            "begin\n  a\nrescue LoadError => error\n  raise error\nend\n\n\
             def m\n  b\nrescue Foo => error\n  c error\nend\n"
                .to_owned(),
            Vec::new(),
        )
        .cops(&[COP, "Lint/UselessAssignment"])
        .without_offense_check()
        .corrected(
            "begin\n  a\nrescue LoadError => e\n  raise e\nend\n\n\
             def m\n  b\nrescue Foo => e\n  c e\nend\n",
        )
        .run();
    }
}

/// `Style/RedundantCondition` が `||` に畳んだ式を括弧で包むかどうか。
///
/// 期待値は本家 1.89.0 の `--only Style/RedundantCondition -A` の実出力。
mod style_redundant_condition_parentheses {
    use super::*;

    const COP: &str = "Style/RedundantCondition";

    /// `make_ternary_form` は `node.parent&.send_type?` のときだけ包む。文法はこの
    /// 「send」を複数の節に散らしていて、うち 2 つは send ではない。論理演算子は
    /// 本家では `and`/`or` の節で、代入が send なのは `[]=` と属性の書き手のときだけ。
    fn corrects(source: &str, corrected: &str) {
        CopCase::new(COP, source.to_owned(), Vec::new())
            .without_offense_check()
            .corrected(corrected)
            .run();
    }

    const BRANCHES: &str = "if a\n  a\nelse\n  b\nend\n";

    /// `[]=` と属性の書き手は send なので包む。
    #[test]
    fn writing_through_a_send_wraps() {
        corrects(&format!("h[k] = {BRANCHES}"), "h[k] = (a || b)\n");
        corrects(&format!("o.attr = {BRANCHES}"), "o.attr = (a || b)\n");
    }

    /// ふつうの代入は send ではないので包まない。`&.` は `csend` で、
    /// `send_type?` は偽になる。
    #[test]
    fn the_other_assignments_do_not() {
        corrects(&format!("x = {BRANCHES}"), "x = a || b\n");
        corrects(&format!("@x = {BRANCHES}"), "@x = a || b\n");
        corrects(&format!("X = {BRANCHES}"), "X = a || b\n");
        // 演算子代入は書き先によらず `op-asgn` で send ではない。
        corrects(&format!("h[k] += {BRANCHES}"), "h[k] += a || b\n");
        corrects(&format!("o&.attr = {BRANCHES}"), "o&.attr = a || b\n");
    }

    /// 演算子は本家では send だが、論理演算子だけは `and`/`or` の節になる。
    #[test]
    fn operators_wrap_except_the_logical_ones() {
        corrects(&format!("z = 1 == {BRANCHES}"), "z = 1 == (a || b)\n");
        corrects(&format!("z = 1 + {BRANCHES}"), "z = 1 + (a || b)\n");
        corrects(&format!("z = c && {BRANCHES}"), "z = c && a || b\n");
        corrects(&format!("z = c || {BRANCHES}"), "z = c || a || b\n");
        corrects(&format!("z = c and {BRANCHES}"), "z = c and a || b\n");
    }

    /// 添字は `[]` の send。
    #[test]
    fn an_index_wraps() {
        corrects("z = h[if a\n  a\nelse\n  b\nend]\n", "z = h[(a || b)]\n");
    }
}

/// `Lint/AssignmentInCondition` の correction の形。
///
/// 期待値は本家 1.89.0 の
/// `--only Layout/IndentationConsistency,Lint/AssignmentInCondition -A` の実出力。
mod lint_assignment_in_condition_wrap {
    use super::*;

    const COP: &str = "Lint/AssignmentInCondition";

    /// 本家は `corrector.wrap(asgn_node, '(', ')')` で、範囲の両端への挿入 2 つ。
    /// 移植版は範囲ごとの置換にしていて、括弧の間の字面をそのまま複写していた。
    /// 複数行にまたがる代入では、その範囲の中で別の cop が直そうとしたものを
    /// 丸ごと飲み込む。
    #[test]
    fn the_parentheses_are_inserted_rather_than_the_range_replaced() {
        let source = "if x = foo\n  bar\nend\n";
        let report = CopCase::new(COP, source.to_owned(), Vec::new())
            .without_offense_check()
            .inspect();
        let corrections: Vec<_> = report
            .offenses
            .iter()
            .flat_map(|offense| offense.corrections.iter())
            .collect();
        assert_eq!(
            corrections.len(),
            2,
            "両端への挿入 2 件のはず: {corrections:?}"
        );
        for correction in &corrections {
            assert_eq!(
                correction.start, correction.end,
                "挿入なのでレンジは空のはず: {correction:?}"
            );
        }
    }

    /// 同じパスで `Layout/IndentationConsistency` が中の行を横へずらしても、
    /// そのずれが失われない。まとめた置換だったころは継続行だけ元の桁に残っていた。
    #[test]
    fn a_shift_inside_the_assignment_survives() {
        CopCase::new(
            COP,
            "class C\n  private\n    def m\n      if p = (\n          a ||\n          b\n        )\n        c\n      end\n    end\nend\n"
                .to_owned(),
            Vec::new(),
        )
        .cops(&[COP, "Layout/IndentationConsistency"])
        .without_offense_check()
        .corrected(
            "class C\n  private\n  def m\n    if (p = (\n        a ||\n        b\n      ))\n      c\n    end\n  end\nend\n",
        )
        .run();
    }
}

/// `Style/RedundantReturn` が heredoc を返すメソッドを見落とす件。
///
/// 期待値は本家 1.89.0 の `--only Style/RedundantReturn -A` の実出力。
mod style_redundant_return_heredoc {
    use super::*;

    const COP: &str = "Style/RedundantReturn";

    /// 文法は heredoc の本体を、それを開いた文の**隣**に置く。`return <<~SQL` だと
    /// 本体が `return` の後ろに立つので、末尾の文を数えるときに本体を勘定すると
    /// `return` が末尾でなくなり、cop がまったく発火しなくなっていた。
    #[test]
    fn a_returned_heredoc_is_still_the_last_statement() {
        CopCase::new(
            COP,
            "def m\n  return <<~SQL\n    select 1\n  SQL\nend\n".to_owned(),
            Vec::new(),
        )
        .without_offense_check()
        .corrected("def m\n  <<~SQL\n    select 1\n  SQL\nend\n")
        .run();
    }

    /// `<<-` と `<<` も同じ。heredoc を引数に渡す形でも本体は隣に立つ。
    #[test]
    fn the_other_heredoc_forms_too() {
        CopCase::new(
            COP,
            "def m\n  return <<-SQL\n    select 1\n  SQL\nend\n".to_owned(),
            Vec::new(),
        )
        .without_offense_check()
        .corrected("def m\n  <<-SQL\n    select 1\n  SQL\nend\n")
        .run();
        CopCase::new(
            COP,
            "def m\n  return foo(<<~SQL)\n    select 1\n  SQL\nend\n".to_owned(),
            Vec::new(),
        )
        .without_offense_check()
        .corrected("def m\n  foo(<<~SQL)\n    select 1\n  SQL\nend\n")
        .run();
    }

    /// heredoc が末尾でないときは今までどおり。
    #[test]
    fn a_heredoc_before_the_return_is_left_alone() {
        CopCase::new(
            COP,
            "def m\n  a = <<~SQL\n    x\n  SQL\n  return a\nend\n".to_owned(),
            Vec::new(),
        )
        .without_offense_check()
        .corrected("def m\n  a = <<~SQL\n    x\n  SQL\n  a\nend\n")
        .run();
    }
}

/// `Lint/EmptyConditionalBody` が末尾の `elsif` のコメントを見落として過剰検出していた件 (#47)。
///
/// 期待値は本家 1.89.0 の `--only Lint/EmptyConditionalBody` の実出力。**5 コーパスには 1 件も
/// 出ない形**なので、ここが唯一の防波堤になる。
mod lint_empty_conditional_body_elsif_comment {
    use super::*;

    const COP: &str = "Lint/EmptyConditionalBody";

    /// 本家 `CommentsHelp#find_end_line` の `elsif?` の分岐。空の `elsif` が最後の枝のとき、
    /// コメントを探す範囲は**それを含む `if` の `end` の行**まで伸びる。
    #[test]
    fn a_comment_in_the_last_elsif_excuses_the_empty_branch() {
        expect_no_offenses(COP, "if a\n  b\nelsif c\n  # 理由\nend\n");
    }

    /// `elsif` が 2 段でも、いちばん外の `if` の `end` まで伸びる。
    #[test]
    fn a_comment_in_a_nested_elsif_is_found_too() {
        expect_no_offenses(COP, "if a\n  b\nelsif c\n  d\nelsif e\n  # 理由\nend\n");
    }

    /// `else` が後ろにあるときは、そこで止まる (以前から通っていた形)。
    #[test]
    fn a_comment_before_a_following_else_still_excuses_it() {
        expect_no_offenses(COP, "if a\n  b\nelsif c\n  # 理由\nelse\n  d\nend\n");
    }

    /// コメントが無ければ報告する。**範囲を伸ばしすぎて黙るようになっていないか**を見る。
    #[test]
    fn an_empty_last_elsif_without_a_comment_is_still_reported() {
        expect_offense(
            COP,
            "if a\n  b\nelsif c\n^^^^^^^ Avoid `elsif` branches without a body.\nend\n",
        );
    }

    /// `end` の行にあるコメントは枝のものではない (本家の範囲は終端の行を含まない)。
    #[test]
    fn a_comment_on_the_end_line_does_not_excuse_it() {
        expect_offense(
            COP,
            "if a\n  b\nelsif c\n^^^^^^^ Avoid `elsif` branches without a body.\nend # 理由\n",
        );
    }
}

/// `Style/CollectionCompact` の `AllowedReceivers` が `Foo::Bar.baz` を `Foo::Bar` と読んでいた件 (#48)。
///
/// 本家の `const_type?` は `Foo` も `Foo::Bar` も真だが、文法は `constant` と `scope_resolution` に
/// 分ける。**既定は `AllowedReceivers: []` なのでコーパスでは踏まない。**
mod style_collection_compact_allowed_receivers {
    use super::*;

    const COP: &str = "Style/CollectionCompact";
    const CONFIG: &str =
        "Style/CollectionCompact:\n  Enabled: true\n  AllowedReceivers:\n    - Foo::Bar\n";

    /// `Foo::Bar.baz` の receiver_name は `Foo::Bar.baz` なので、`Foo::Bar` の許可には当たらない。
    #[test]
    fn a_selector_after_the_constant_is_not_allowed_by_the_constant_alone() {
        let report = CopCase::new(
            COP,
            "Foo::Bar.baz.reject { |e| e.nil? }\n".to_owned(),
            Vec::new(),
        )
        .config(CONFIG)
        .without_offense_check()
        .inspect();
        assert_eq!(
            report
                .offenses
                .iter()
                .filter(|offense| offense.cop_name == COP)
                .count(),
            1,
            "receiver_name は Foo::Bar.baz なので許可リストに当たらない"
        );
    }

    /// 定数そのものが receiver なら許可される。
    #[test]
    fn the_constant_itself_is_allowed() {
        let report = CopCase::new(
            COP,
            "Foo::Bar.reject { |e| e.nil? }\n".to_owned(),
            Vec::new(),
        )
        .config(CONFIG)
        .without_offense_check()
        .inspect();
        assert_eq!(
            report
                .offenses
                .iter()
                .filter(|offense| offense.cop_name == COP)
                .count(),
            0,
            "receiver_name は Foo::Bar なので許可される"
        );
    }
}

/// `Lint/Void` の `-A` が空白だけの行を余分に消していた件 (#53)。
///
/// 本家 `RangeHelp#final_pos` は**段を順に 1 回ずつ**通る (空白/タブ → 行継続 → 改行 → 全空白)。
/// 混ぜて歩くと、改行の向こう側の空白まで食べて**空白だけの行が消える**。
/// 期待値は本家 1.89.0 の `--only Lint/Void -A` の実出力。
mod lint_void_blank_line_before {
    use super::*;

    const COP: &str = "Lint/Void";

    /// 手前に空白だけの行があっても、消えるのは void 式とその行の字下げだけ。
    #[test]
    fn a_whitespace_only_line_above_survives() {
        CopCase::new(
            COP,
            "def foo\n  bar\n   \n  42\n  baz\nend\n".to_owned(),
            Vec::new(),
        )
        .without_offense_check()
        .corrected("def foo\n  bar\n   \n  baz\nend\n")
        .run();
    }

    /// 空行 (空白を持たない行) が手前にあるときは、本家も改行をまとめて食べる。
    #[test]
    fn an_empty_line_above_is_taken_with_it() {
        CopCase::new(
            COP,
            "def foo\n  bar\n\n  42\n  baz\nend\n".to_owned(),
            Vec::new(),
        )
        .without_offense_check()
        .corrected("def foo\n  bar\n  baz\nend\n")
        .run();
    }
}
